## Arquivo 3: `src/middleware/errorHandler.js` — Middleware de Tratamento de Erros

```javascript
/**
 * @fileoverview Middleware centralizado de tratamento de erros da API.
 * 
 * Por que um middleware de erro dedicado?
 * - Centraliza a lógica de formatação de respostas de erro
 * - Evita repetição de try/catch em cada rota
 * - Permite logging consistente para debugging e monitoramento
 * - Separa concerns: rotas lançam erros, middleware decide a resposta
 * 
 * Convenção Express: middlewares de erro têm 4 parâmetros (err, req, res, next)
 */

const { ApiError } = require('../classes/errors');

/**
 * Middleware principal de tratamento de erros.
 * 
 * @param {ApiError} err — Instância do erro lançado pela aplicação
 * @param {import('express').Request} req — Objeto de requisição Express
 * @param {import('express').Response} res — Objeto de resposta Express
 * @param {import('express').NextFunction} next — Função para encadear middlewares
 */
function errorHandler(err, req, res, next) {
  // Se o erro não for uma instância de ApiError, trata como erro interno inesperado
  if (!(err instanceof ApiError)) {
    console.error('[ERRO NÃO CAPTURADO]', err); // Log para debugging
    err = new (require('../classes/errors').InternalError)(
      'Ocorreu um erro inesperado no servidor',
      err
    );
  }

  // Estrutura padronizada de resposta de erro
  const errorResponse = {
    success: false,
    statusCode: err.statusCode,
    message: err.message,
    timestamp: new Date().toISOString(),
    path: req.path,
    method: req.method
  };

  // Inclui detalhes apenas para erros operacionais (4xx) e não expõe stack trace
  if (err.isOperational && err.details) {
    errorResponse.details = err.details;
  }

  // Para erros internos (5xx), nunca expomos stack trace ao cliente por segurança
  if (!err.isOperational) {
    console.error('[ERRO INTERNO]', err.stack); // Log completo para o servidor
    errorResponse.message = 'Ocorreu um erro interno. Tente novamente mais tarde.';
  }

  // Envia resposta com código HTTP apropriado e corpo JSON padronizado
  res.status(err.statusCode).json(errorResponse);
}

/**
 * Middleware de tratamento de erros assíncronos não capturados.
 * 
 * Por que este middleware é necessário?
 * - Express não captura automaticamente rejeições de Promises em rotas
 * - Sem isso, um async/await rejeitado causaria crash do processo
 * 
 * Padrão: envolver cada rota com try/catch OU usar este wrapper.
 */
function asyncErrorHandler(fn) {
  /**
   * Função wrapper que captura erros de rotas assíncronas.
   * 
   * @param {import('express').Request} req
   * @param {import('express').Response} res
   * @param {import('express').NextFunction} next
   */
  return function wrapped(req, res, next) {
    Promise.resolve(fn(req, res, next)).catch(next); // Encaminha erro ao middleware de erros
  };
}

module.exports = { errorHandler, asyncErrorHandler };
```

**Explicação:** O `errorHandler` é um middleware Express com **4 parâmetros**, o que o identifica automaticamente como handler de erros. Ele padroniza a resposta JSON de erro com campos `success`, `statusCode`, `message`, `timestamp`, etc. O `asyncErrorHandler` é um wrapper essencial para rotas assíncronas — sem ele, rejeições de Promise causariam crashes não tratados.

