## Arquivo 4: `src/routes/books.js` — Rotas dos Livros

```javascript
/**
 * @fileoverview Rotas REST para gerenciamento de livros.
 * 
 * Estrutura de dados escolhida: Array em memória.
 * 
 * Por que array?
 * - Simplicidade para exemplo educacional (sem banco de dados)
 * - Operações O(1) para push/pop, O(n) para busca por ID
 * - Fácil de entender e depurar
 * - Preparado para migração futura: basta substituir as funções de CRUD
 * 
 * Convenções REST adotadas:
 * - GET /books — Listagem com filtragem via query params
 * - GET /books/:id — Busca por identificador único
 * - POST /books — Criação (body contém dados do novo recurso)
 * - PUT /books/:id — Atualização completa (substituição total)
 * - DELETE /books/:id — Remoção por identificador
 * 
 * Exemplos de uso via curl:
 * 
 * # Listar todos os livros
 * curl http://localhost:3000/books
 * 
 * # Filtrar por autor
 * curl "http://localhost:3000/books?author=J.K.Rowling"
 * 
 * # Filtrar por ano (mínimo)
 * curl "http://localhost:3000/books?yearMin=2000"
 * 
 * # Obter livro por ID
 * curl http://localhost:3000/books/1
 * 
 * # Criar novo livro
 * curl -X POST http://localhost:3000/books \
 *   -H "Content-Type: application/json" \
 *   -d '{"title":"O Senhor dos Anéis","author":"J.R.R. Tolkien","year":1954,"genre":"Fantasia"}'
 * 
 * # Atualizar livro (PUT — substituição completa)
 * curl -X PUT http://localhost:3000/books/1 \
 *   -H "Content-Type: application/json" \
 *   -d '{"title":"O Senhor dos Anéis","author":"J.R.R. Tolkien","year":1954,"genre":"Fantasia"}'
 * 
 * # Excluir livro
 * curl -X DELETE http://localhost:3000/books/1
 */

const express = require('express');
const { asyncErrorHandler } = require('../middleware/errorHandler');
const { ValidationError, NotFoundError } = require('../classes/errors');

// Instância do roteador Express (boa prática: encapsular rotas em módulos)
const router = express.Router();

// ============================================================
// ARMAZENAMENTO EM MEMÓRIA — Array de livros
// 
// Escolha da estrutura: Array simples de objetos.
// - Cada livro é um objeto com propriedades tipadas
// - IDs são gerados automaticamente (auto-incremento)
// - Em produção, substituir por MongoDB/PostgreSQL
// ============================================================

/**
 * Array em memória que armazena todos os livros.
 * 
 * Padrão: usar const para o array (não reatribuído), mas permitir mutação (push/splice).
 * Isso evita reatribuição acidental enquanto permite operações de CRUD.
 */
const books = [];

/**
 * Contador para geração automática de IDs únicos.
 * 
 * Por que contador em vez de UUID?
 * - Simplicidade para exemplo educacional
 * - IDs numéricos são mais legíveis em logs e testes
 * - Em produção, usar UUID v4 ou ObjectId do MongoDB
 */
let nextId = 1;

// ============================================================
// DADOS INICIAIS (seed) — Para facilitar testes
// ============================================================
books.push(
  { id: 1, title: 'Dom Casmurro', author: 'Machado de Assis', year: 1899, genre: 'Romance' },
  { id: 2, title: '1984', author: 'George Orwell', year: 1949, genre: 'Distopia' },
  { id: 3, title: 'O Pequeno Príncipe', author: 'Antoine de Saint-Exupéry', year: 1943, genre: 'Fábula' }
);
nextId = 4; // Próximo ID a ser atribuído

// ============================================================
// FUNÇÕES AUXILIARES DE VALIDAÇÃO
// ============================================================

/**
 * Valida os campos obrigatórios de um livro.
 * 
 * @param {Object} data — Dados do livro a serem validados
 * @returns {void} Lança ValidationError se houver problemas
 */
function validateBook(data) {
  const errors = {};

  // Validação do título: obrigatório e string não vazia
  if (!data.title || typeof data.title !== 'string' || data.title.trim() === '') {
    errors.title = 'Título é obrigatório e deve ser uma string não vazia';
  }

  // Validação do autor: obrigatório e string não vazia
  if (!data.author || typeof data.author !== 'string' || data.author.trim() === '') {
    errors.author = 'Autor é obrigatório e deve ser uma string não vazia';
  }

  // Validação do ano: opcional, mas se fornecido deve ser número válido
  if (data.year !== undefined && data.year !== null) {
    const year = Number(data.year);
    if (!Number.isInteger(year) || year < 0 || year > new Date().getFullYear() + 1) {
      errors.year = 'Ano deve ser um número inteiro entre 0 e o ano atual + 1';
    }
  }

  // Validação do gênero: opcional, mas se fornecido deve ser string não vazia
  if (data.genre !== undefined && data.genre !== null) {
    if (typeof data.genre !== 'string' || data.genre.trim() === '') {
      errors.genre = 'Gênero deve ser uma string não vazia';
    }
  }

  // Lança erro com todos os detalhes de validação se houver problemas
  if (Object.keys(errors).length > 0) {
    throw new ValidationError('Dados do livro inválidos', errors);
  }
}

/**
 * Converte dados de entrada em objeto de livro completo.
 * 
 * @param {Object} data — Dados fornecidos na requisição
 * @returns {Object} Objeto de livro pronto para armazenamento
 */
function buildBook(data) {
  return {
    id: nextId++, // ID auto-incremento
    title: data.title.trim(),
    author: data.author.trim(),
    year: data.year ? Number(data.year) : null,
    genre: data.genre ? data.genre.trim() : null
  };
}

// ============================================================
// ROTA: GET /books — Listar todos os livros com filtragem
// 
 * Exemplos curl:
 *   curl http://localhost:3000/books
 *   curl "http://localhost:3000/books?author=Orwell"
 *   curl "http://localhost:3000/books?yearMin=1950&yearMax=2000"
 *   curl "http://localhost:3000/books?genre=Fantasia"
 * ============================================================

/**
 * @name GET /books
 * @description Lista todos os livros com filtragem opcional por query params.
 * 
 * Query params suportados:
 * - author: filtra por autor (case-insensitive, parcial)
 * - genre: filtra por gênero (case-insensitive, parcial)
 * - yearMin: ano mínimo (inclusivo)
 * - yearMax: ano máximo (inclusivo)
 * - search: busca por título ou autor (case-insensitive)
 */
router.get('/', asyncErrorHandler((req, res) => {
  // Começa com todos os livros
  let result = [...books];

  // Filtragem por autor (busca parcial, case-insensitive)
  if (req.query.author) {
    const authorFilter = req.query.author.toLowerCase();
    result = result.filter(book => 
      book.author.toLowerCase().includes(authorFilter)
    );
  }

  // Filtragem por gênero
  if (req.query.genre) {
    const genreFilter = req.query.genre.toLowerCase();
    result = result.filter(book => 
      book.genre && book.genre.toLowerCase().includes(genreFilter)
    );
  }

  // Filtragem por ano mínimo
  if (req.query.yearMin) {
    const yearMin = Number(req.query.yearMin);
    if (!isNaN(yearMin)) {
      result = result.filter(book => 
        book.year && book.year >= yearMin
      );
    }
  }

  // Filtragem por ano máximo
  if (req.query.yearMax) {
    const yearMax = Number(req.query.yearMax);
    if (!isNaN(yearMax)) {
      result = result.filter(book => 
        book.year && book.year <= yearMax
      );
    }
  }

  // Busca por título ou autor
  if (req.query.search) {
    const searchFilter = req.query.search.toLowerCase();
    result = result.filter(book => 
      book.title.toLowerCase().includes(searchFilter) ||
      book.author.toLowerCase().includes(searchFilter)
    );
  }

  // Resposta padronizada com metadados de paginação (futuro)
  res.json({
    success: true,
    count: result.length,
    total: books.length,
    data: result
  });
}));

// ============================================================
// ROTA: GET /books/:id — Obter único livro por ID
// 
 * Exemplos curl:
 *   curl http://localhost:3000/books/1
 *   curl http://localhost:3000/books/999  // Retorna 404
 * ============================================================

/**
 * @name GET /books/:id
 * @description Busca um livro específico pelo seu identificador numérico.
 * 
 * Parâmetros de rota:
 * - id: identificador numérico do livro (obrigatório)
 */
router.get('/:id', asyncErrorHandler((req, res) => {
  // Converte ID para número e valida
  const id = Number(req.params.id);

  if (isNaN(id)) {
    throw new ValidationError('ID deve ser um número válido');
  }

  // Busca linear no array — O(n), aceitável para exemplo educacional
  const book = books.find(b => b.id === id);

  // Lança NotFoundError se livro não encontrado
  if (!book) {
    throw new NotFoundError('Livro', id);
  }

  res.json({ success: true, data: book });
}));

// ============================================================
// ROTA: POST /books — Criar novo livro
// 
 * Exemplos curl (Postman):
 *   curl -X POST http://localhost:3000/books \
 *     -H "Content-Type: application/json" \
 *     -d '{"title":"O Hobbit","author":"J.R.R. Tolkien","year":1937,"genre":"Fantasia"}'
 * 
 *   // Resposta esperada (201 Created):
 *   { "success": true, "data": { "id": 4, "title": "...", ... } }
 * ============================================================

/**
 * @name POST /books
 * @description Cria um novo livro com os dados fornecidos no corpo da requisição.
 * 
 * Corpo esperado (JSON):
 * - title: string obrigatória
 * - author: string obrigatória
 * - year: número opcional
 * - genre: string opcional
 */
router.post('/', asyncErrorHandler((req, res) => {
  // Valida os dados de entrada antes de processar
  validateBook(req.body);

  // Constrói o objeto livro com ID auto-incremento
  const newBook = buildBook(req.body);

  // Adiciona ao array em memória
  books.push(newBook);

  // HTTP 201 Created — recurso criado com sucesso
  res.status(201).json({
    success: true,
    message: 'Livro criado com sucesso',
    data: newBook
  });
}));

// ============================================================
// ROTA: PUT /books/:id — Atualizar livro existente (substituição completa)
// 
 * Exemplos curl:
 *   curl -X PUT http://localhost:3000/books/1 \
 *     -H "Content-Type: application/json" \
 *     -d '{"title":"Dom Casmurro (Ed. Crítica)","author":"Machado de Assis","year":1899,"genre":"Romance Realista"}'
 * 
 *   // Nota: PUT substitui TODOS os campos — use PATCH para atualização parcial
 * ============================================================

/**
 * @name PUT /books/:id
 * @description Atualiza completamente um livro existente pelo seu ID.
 * 
 * Diferença entre PUT e PATCH:
 * - PUT: substituição completa (todos os campos devem ser fornecidos)
 * - PATCH: atualização parcial (apenas campos que deseja alterar)
 * 
 * Para este exemplo educacional, usamos PUT como substituição completa.
 */
router.put('/:id', asyncErrorHandler((req, res) => {
  const id = Number(req.params.id);

  if (isNaN(id)) {
    throw new ValidationError('ID deve ser um número válido');
  }

  // Busca o livro existente
  const bookIndex = books.findIndex(b => b.id === id);

  if (bookIndex === -1) {
    throw new NotFoundError('Livro', id);
  }

  // Valida os dados de atualização
  validateBook(req.body);

  // Constrói o livro atualizado (mantém o ID original)
  const updatedBook = buildBook(req.body);
  updatedBook.id = id; // Preserva o ID original

  // Substitui o livro no array
  books[bookIndex] = updatedBook;

  // HTTP 200 OK — recurso atualizado com sucesso
  res.json({
    success: true,
    message: 'Livro atualizado com sucesso',
    data: updatedBook
  });
}));

// ============================================================
// ROTA: DELETE /books/:id — Excluir livro
// 
 * Exemplos curl:
 *   curl -X DELETE http://localhost:3000/books/1
 *   
 *   // Resposta esperada (200 OK):
 *   { "success": true, "message": "Livro excluído com sucesso" }
 * 
 *   curl -X DELETE http://localhost:3000/books/999  // Retorna 404
 * ============================================================

/**
 * @name DELETE /books/:id
 * @description Remove um livro do sistema pelo seu identificador.
 */
router.delete('/:id', asyncErrorHandler((req, res) => {
  const id = Number(req.params.id);

  if (isNaN(id)) {
    throw new ValidationError('ID deve ser um número válido');
  }

  // Busca o índice do livro para remoção eficiente
  const bookIndex = books.findIndex(b => b.id === id);

  if (bookIndex === -1) {
    throw new NotFoundError('Livro', id);
  }

  // Remove o livro do array (O(n) para splice, mas simples e correto)
  books.splice(bookIndex, 1);

  // HTTP 200 OK — recurso removido com sucesso
  res.json({
    success: true,
    message: 'Livro excluído com sucesso'
  });
}));

// Exporta o roteador para uso em app.js
module.exports = router;
```

**Explicação:** As rotas seguem convenções REST rigorosas. Cada rota usa `asyncErrorHandler` para capturar erros assíncronos. A validação é feita antes do processamento, e os erros são lançados como instâncias das classes personalizadas. O array em memória é simples mas preparado para migração — basta substituir as operações de CRUD por chamadas ao banco de dados.

