## Arquivo 5: `src/routes/stats.js` — Rota de Estatísticas

```javascript
/**
 * @fileoverview Rota de estatísticas da API de livros.
 * 
 * Por que uma rota separada?
 * - Separação de concerns: rotas de livros vs métricas
 * - Facilita testes unitários independentes
 * - Padrão REST: recursos diferentes têm endpoints diferentes
 */

const express = require('express');
const { asyncErrorHandler } = require('../middleware/errorHandler');
const booksRouter = require('./books'); // Para acessar o array de livros

const router = express.Router();

/**
 * @name GET /stats
 * @description Retorna estatísticas agregadas sobre o acervo de livros.
 * 
 * Estatísticas retornadas:
 * - totalBooks: número total de livros cadastrados
 * - totalAuthors: número de autores únicos
 * - averageYear: ano médio dos livros (arredondado)
 * - booksByGenre: distribuição por gênero
 * - oldestBook: livro mais antigo
 * - newestBook: livro mais recente
 * 
 * Exemplo curl:
 *   curl http://localhost:3000/stats
 * 
 * Resposta esperada:
 * {
 *   "success": true,
 *   "data": {
 *     "totalBooks": 3,
 *     "totalAuthors": 3,
 *     "averageYear": 1864,
 *     "booksByGenre": { "Romance": 1, "Distopia": 1, "Fábula": 1 },
 *     "oldestBook": { "title": "Dom Casmurro", "year": 1899 },
 *     "newestBook": { "title": "1984", "year": 1949 }
 *   }
 * }
 */
router.get('/', asyncErrorHandler((req, res) => {
  // Importa o array de livros do módulo de rotas
  const books = require('./books').getBooks();

  if (books.length === 0) {
    return res.json({
      success: true,
      data: {
        totalBooks: 0,
        totalAuthors: 0,
        averageYear: null,
        booksByGenre: {},
        oldestBook: null,
        newestBook: null
      }
    });
  }

  // Calcula autores únicos usando Set (estrutura que elimina duplicatas)
  const uniqueAuthors = new Set(books.map(book => book.author));

  // Calcula ano médio (arredondado para inteiro)
  const yearsWithValues = books.filter(book => book.year !== null);
  const averageYear = yearsWithValues.length > 0
    ? Math.round(yearsWithValues.reduce((sum, book) => sum + book.year, 0) / yearsWithValues.length)
    : null;

  // Agrupamento por gênero usando reduce (padrão funcional para agregação)
  const booksByGenre = books.reduce((acc, book) => {
    if (book.genre) {
      acc[book.genre] = (acc[book.genre] || 0) + 1;
    }
    return acc;
  }, {});

  // Encontra livro mais antigo e mais recente
  const sortedByYear = [...books].filter(b => b.year !== null).sort((a, b) => a.year - b.year);
  const oldestBook = sortedByYear[0] ? { title: sortedByYear[0].title, year: sortedByYear[0].year } : null;
  const newestBook = sortedByYear[sortedByYear.length - 1] 
    ? { title: sortedByYear[sortedByYear.length - 1].title, year: sortedByYear[sortedByYear.length - 1].year } 
    : null;

  res.json({
    success: true,
    data: {
      totalBooks: books.length,
      totalAuthors: uniqueAuthors.size,
      averageYear,
      booksByGenre,
      oldestBook,
      newestBook
    }
  });
}));

module.exports = router;
```

**Explicação:** A rota de estatísticas calcula métricas agregadas usando operações funcionais (`map`, `reduce`, `Set`). O uso de `Set` para autores únicos é eficiente (O(n)) e evita lógica manual de verificação de duplicatas. As estatísticas são recalculadas a cada requisição, o que é aceitável para volumes pequenos de dados.

