## Arquivo 6: `src/app.js` — Aplicação Principal

```javascript
/**
 * @fileoverview Ponto de entrada da API REST de livros.
 * 
 * Arquitetura adotada:
 * - app.js: configuração central (middlewares, rotas, porta)
 * - routes/: módulos separados por domínio (books, stats)
 * - middleware/: handlers reutilizáveis (errorHandler)
 * - classes/: definições de erro customizadas
 * 
 * Por que esta estrutura?
 * - Separação de concerns facilita manutenção e testes
 * - Módulos independentes podem ser testados isoladamente
 * - Escalabilidade: adicionar novas rotas é simples
 */

const express = require('express');
const { errorHandler } = require('./middleware/errorHandler');

// Instância principal do aplicativo Express
const app = express();

// ============================================================
// CONFIGURAÇÃO DE MIDDLEWARES
// ============================================================

/**
 * Middleware para parsing de JSON no corpo das requisições.
 * 
 * Por que é necessário?
 * - Express não faz parse automático de JSON desde a versão 4.x
 * - Sem este middleware, req.body seria undefined
 * - Limitamos o tamanho do body a 100KB para evitar abuse
 */
app.use(express.json({ limit: '100kb' }));

/**
 * Middleware para parsing de URL-encoded (para formulários).
 * 
 * Não é usado nesta API REST, mas mantido como boa prática.
 */
app.use(express.urlencoded({ extended: true, limit: '100kb' }));

// ============================================================
// ROTAS DA API
// ============================================================

/**
 * Rota raiz — documentação e health check.
 * 
 * Exemplo curl:
 *   curl http://localhost:3000/
 */
app.get('/', (req, res) => {
  res.json({
    success: true,
    message: 'API de Livros — Node.js + Express.js',
    version: '1.0.0',
    endpoints: {
      books: {
        list: 'GET /books',
        getById: 'GET /books/:id',
        create: 'POST /books',
        update: 'PUT /books/:id',
        delete: 'DELETE /books/:id'
      },
      stats: 'GET /stats'
    }
  });
});

/**
 * Health check — verificação de disponibilidade do serviço.
 * 
 * Exemplo curl:
 *   curl http://localhost:3000/health
 */
app.get('/health', (req, res) => {
  res.json({
    success: true,
    status: 'ok',
    timestamp: new Date().toISOString(),
    uptime: process.uptime()
  });
});

// ============================================================
// IMPORTAÇÃO DE ROTAS
// ============================================================

/**
 * Importa o roteador de livros (módulo separado).
 * 
 * Por que usar router em vez de app.get()?
 * - Encapsulamento: rotas podem ser testadas isoladamente
 * - Reusabilidade: mesmo router pode ser montado em múltiplos apps
 * - Organização: código mais limpo e manutenível
 */
const booksRouter = require('./routes/books');
app.use('/books', booksRouter);

/**
 * Importa o roteador de estatísticas.
 */
const statsRouter = require('./routes/stats');
app.use('/stats', statsRouter);

// ============================================================
// TRATAMENTO DE ERROS — Middleware global
// 
 * Por que colocar após as rotas?
 * - Express executa middlewares na ordem em que são definidos
 * - O handler de erros deve ser o ÚLTIMO middleware
 * - Assim, todas as rotas podem lançar erros para ele capturar
 * ============================================================

/**
 * Middleware global de tratamento de erros.
 * 
 * Deve ser o último app.use() antes do listen().
 */
app.use(errorHandler);

// ============================================================
// ROTA 404 — Recurso não encontrado
// 
 * Por que tratar 404 explicitamente?
 * - Middlewares de erro capturam apenas erros lançados, não respostas normais
 * - Uma rota inexistente não lança erro automaticamente
 * - Esta rota captura todas as requisições para endpoints inexistentes
 * ============================================================

/**
 * Middleware para requisições a rotas inexistentes.
 */
app.use((req, res) => {
  res.status(404).json({
    success: false,
    statusCode: 404,
    message: `Rota ${req.method} ${req.path} não encontrada`,
    timestamp: new Date().toISOString()
  });
});

// ============================================================
// INICIALIZAÇÃO DO SERVIDOR
// ============================================================

/**
 * Porta configurável via variável de ambiente (boa prática).
 * 
 * Por que usar variável de ambiente?
 * - Flexibilidade para diferentes ambientes (dev, staging, prod)
 * - Segurança: não hardcodar portas em produção
 * - Padrão 12-factor apps
 */
const PORT = process.env.PORT || 3000;

/**
 * Inicia o servidor e loga na porta configurada.
 */
app.listen(PORT, () => {
  console.log(`✅ API de Livros rodando em http://localhost:${PORT}`);
  console.log(`📚 Endpoints disponíveis:`);
  console.log(`   GET    http://localhost:${PORT}/books`);
  console.log(`   POST   http://localhost:${PORT}/books`);
  console.log(`   GET    http://localhost:${PORT}/stats`);
  console.log(`   GET    http://localhost:${PORT}/health`);
});

// Exporta a instância do app para testes unitários
module.exports = app;
```

**Explicação:** O `app.js` é o ponto de entrada que orquestra middlewares, rotas e inicialização. A ordem dos middlewares é crítica: parsing → rotas → handler de erros → 404. O uso de `process.env.PORT` segue a convenção **12-factor apps**. A exportação do `app` permite testes unitários com bibliotecas como Supertest.

