## File 2: `src/models/book.js`

```javascript
/**
 * ============================================================================
 * BOOK MODEL — In-Memory Data Store
 * ============================================================================
 *
 * DESIGN RATIONALE:
 * We use an in-memory array instead of a database for this educational example.
 * Reasons:
 *   1. Zero setup overhead — no MongoDB/PostgreSQL installation needed.
 *   2. Demonstrates CRUD operations without external dependencies.
 *   3. Easy to inspect and debug by logging the store directly.
 *
 * DATA STRUCTURE CHOICES:
 *   - Array of objects: Simple, ordered, supports filtering via .filter().
 *   - Each book has a unique numeric `id` (auto-incrementing) for O(1) lookups
 *     when combined with a Map, but we use .find() for simplicity and clarity.
 *   - Timestamps (`createdAt`, `updatedAt`) track lifecycle — standard REST practice.
 *
 * SCALABILITY NOTE:
 * In production, replace this module with a database adapter (e.g., MongoDB,
 * PostgreSQL). The route handlers below are written to be agnostic of the store,
 * so swapping backends requires only changing this file.
 */

// --------------------------------------------------------------------------
// Store initialization
// --------------------------------------------------------------------------

/**
 * The books array holds all book records in memory.
 * We seed it with sample data so the API is immediately testable.
 *
 * @type {Array<Book>}
 */
const books = [
  {
    id: 1,
    title: "The Great Gatsby",
    author: "F. Scott Fitzgerald",
    isbn: "978-0743273565",
    genre: "Fiction",
    publishedYear: 1925,
    createdAt: new Date("2024-01-01T00:00:00Z"),
    updatedAt: new Date("2024-01-01T00:00:00Z"),
  },
  {
    id: 2,
    title: "To Kill a Mockingbird",
    author: "Harper Lee",
    isbn: "978-0061120084",
    genre: "Fiction",
    publishedYear: 1960,
    createdAt: new Date("2024-01-01T00:00:00Z"),
    updatedAt: new Date("2024-01-01T00:00:00Z"),
  },
  {
    id: 3,
    title: "A Brief History of Time",
    author: "Stephen Hawking",
    isbn: "978-0553380163",
    genre: "Science",
    publishedYear: 1988,
    createdAt: new Date("2024-01-01T00:00:00Z"),
    updatedAt: new Date("2024-01-01T00:00:00Z"),
  },
];

/**
 * Auto-incrementing ID counter.
 * Starts at books.length + 1 so newly created IDs don't collide with seeds.
 * In a real app, use a UUID or database auto-increment.
 */
let nextId = books.length + 1;

// --------------------------------------------------------------------------
// Exported store interface
// --------------------------------------------------------------------------

/**
 * Returns the entire in-memory book collection.
 * @returns {Array<Book>} Copy of the books array to prevent external mutation.
 */
function getAllBooks() {
  return [...books]; // Return a shallow copy — callers can't mutate the store directly
}

/**
 * Finds a single book by its numeric ID.
 * @param {number} id - The unique identifier of the book.
 * @returns {Book|undefined} The matching book, or undefined if not found.
 */
function getBookById(id) {
  return books.find((book) => book.id === id);
}

/**
 * Creates a new book and appends it to the store.
 * Auto-assigns an incrementing ID and timestamps.
 * @param {Object} bookData - Partial book object (id, createdAt, updatedAt omitted).
 * @returns {Book} The newly created book with assigned id and timestamps.
 */
function createBook(bookData) {
  const newBook = {
    ...bookData, // Spread in the provided fields
    id: nextId++, // Assign and increment the ID counter
    createdAt: new Date(),
    updatedAt: new Date(),
  };
  books.push(newBook);
  return newBook;
}

/**
 * Updates an existing book by ID. Merges only the provided fields.
 * @param {number} id - The ID of the book to update.
 * @param {Object} updates - Fields to overwrite (e.g., { title: "New Title" }).
 * @returns {Book|undefined} The updated book, or undefined if not found.
 */
function updateBook(id, updates) {
  const index = books.findIndex((book) => book.id === id);
  if (index === -1) return undefined;

  // Merge: keep existing fields, overwrite only the ones provided
  books[index] = {
    ...books[index],
    ...updates,
    updatedAt: new Date(), // Always refresh the updatedAt timestamp
  };
  return books[index];
}

/**
 * Deletes a book by ID.
 * @param {number} id - The ID of the book to remove.
 * @returns {boolean} True if the book was found and deleted, false otherwise.
 */
function deleteBook(id) {
  const index = books.findIndex((book) => book.id === id);
  if (index === -1) return false;

  books.splice(index, 1); // Remove from array in-place
  return true;
}

/**
 * Computes aggregate statistics across all books.
 * Used by the GET /stats endpoint.
 * @returns {Object} Statistics object with counts and averages.
 */
function getStats() {
  const totalBooks = books.length;

  // Group books by genre to count per-genre occurrences
  const genreCounts = {};
  for (const book of books) {
    genreCounts[book.genre] = (genreCounts[book.genre] || 0) + 1;
  }

  // Compute average published year (rounded to nearest integer)
  const avgYear =
    totalBooks > 0
      ? Math.round(books.reduce((sum, b) => sum + b.publishedYear, 0) / totalBooks)
      : 0;

  return {
    totalBooks,
    averagePublishedYear: avgYear,
    genreCounts,
  };
}

// Export all store functions as a module
module.exports = {
  getAllBooks,
  getBookById,
  createBook,
  updateBook,
  deleteBook,
  getStats,
};
```

> **Key design decisions explained:**
> - **Shallow copy on `getAllBooks()`**: Prevents external code from accidentally mutating the store. This is a form of *defensive programming*.
> - **Auto-incrementing ID**: Simple and predictable for an educational example. In production, UUIDs or database sequences are preferred to avoid collisions in distributed systems.
> - **`updatedAt` on every mutation**: Standard REST practice — clients can use this for conditional requests (e.g., `If-Modified-Since`).

