## File 3: `src/middleware/errorHandler.js`

```javascript
/**
 * ============================================================================
 * ERROR HANDLING MIDDLEWARE
 * ============================================================================
 *
 * DESIGN RATIONALE:
 * Custom error classes let us distinguish between different failure modes
 * (not found, validation failure, internal server error) so we can return
 * appropriate HTTP status codes and consistent JSON error responses.
 *
 * Express error-handling middleware has a special signature:
 *   (err, req, res, next) => ...
 * The 4-parameter signature is how Express recognizes it as an error handler.
 * Regular middleware only takes (req, res, next).
 *
 * WHY MIDDLEWARE INSTEAD OF TRY/CATCH EVERYWHERE?
 * Using express-async-errors or wrapping routes in a central handler keeps
 * route files clean. Here we use the traditional try/catch + next(err) pattern
 * for maximum clarity and zero extra dependencies.
 */

// --------------------------------------------------------------------------
// Custom Error Classes
// --------------------------------------------------------------------------

/**
 * Base error class — all custom errors extend this.
 * Provides a consistent structure: name, message, statusCode, isOperational.
 */
class AppError extends Error {
  /**
   * @param {string} message - Human-readable error description.
   * @param {number} statusCode - HTTP status code (e.g., 404, 400).
   */
  constructor(message, statusCode) {
    super(message); // Call the parent Error constructor
    this.statusCode = statusCode;
    this.isOperational = true; // Marks this as a known, expected error

    // Capture the stack trace for debugging
    Error.captureStackTrace(this, this.constructor);
  }
}

/**
 * Resource not found error — maps to HTTP 404.
 */
class NotFoundError extends AppError {
  constructor(resource) {
    super(`${resource} not found`, 404);
  }
}

/**
 * Validation / bad request error — maps to HTTP 400.
 */
class ValidationError extends AppError {
  constructor(message) {
    super(message, 400);
  }
}

// --------------------------------------------------------------------------
// Error Handler Middleware
// --------------------------------------------------------------------------

/**
 * Centralized error-handling middleware.
 * Catches all errors passed via next(err) and returns a consistent JSON response.
 *
 * @param {Error} err - The error object (should be an AppError instance).
 * @param {import('express').Request} req - Express request object.
 * @param {import('express').Response} res - Express response object.
 * @param {import('express').NextFunction} next - Express next function.
 */
function errorHandler(err, req, res, next) {
  // Log the full error for server-side debugging (never expose stack to clients)
  console.error(`[ERROR] ${err.name}: ${err.message}`);
  if (process.env.NODE_ENV === "development" && err.stack) {
    console.error(err.stack);
  }

  // Determine status code: default to 500 for unexpected errors
  const statusCode = err.statusCode || 500;

  // Build a consistent JSON error response
  const errorResponse = {
    success: false,
    error: {
      name: err.name,
      message: err.message,
    },
  };

  // In development, include the stack trace for easier debugging
  if (process.env.NODE_ENV === "development" && err.stack) {
    errorResponse.error.stack = err.stack;
  }

  // Send the JSON response
  res.status(statusCode).json(errorResponse);
}

// --------------------------------------------------------------------------
// Async Wrapper Middleware
// --------------------------------------------------------------------------

/**
 * Wraps async route handlers to catch rejected promises.
 * Without this, a thrown error inside an async handler would cause an
 * unhandled promise rejection (crashing the server in newer Node versions).
 *
 * @param {Function} fn - The async route handler function.
 * @returns {Function} Wrapped handler that forwards errors to Express middleware.
 */
function asyncHandler(fn) {
  return (req, res, next) => {
    // Call the original handler; if it rejects, forward the error to next()
    Promise.resolve(fn(req, res, next)).catch(next);
  };
}

// Export classes and middleware
module.exports = {
  AppError,
  NotFoundError,
  ValidationError,
  errorHandler,
  asyncHandler,
};
```

> **Why custom error classes?** They let us return `404` for missing books vs. `500` for server bugs vs. `400` for bad input — each with a clear semantic meaning. The `isOperational` flag is a convention that lets monitoring tools distinguish between expected errors (like "book not found") and unexpected ones (like null pointer exceptions).

> **Why the async wrapper?** Express doesn't automatically catch rejections from async route handlers. Without this wrapper, any rejected promise would crash the process. The wrapper converts rejections into `next(err)` calls, routing them through our error handler.

