```javascript
/**
 * ============================================================================
 * REQUEST VALIDATION MIDDLEWARE
 * ============================================================================
 *
 * DESIGN RATIONALE:
 * Validation is separated from route logic so routes stay focused on
 * business logic, not input sanitization. This follows the Single
 * Responsibility Principle (SRP).
 *
 * We validate at two levels:
 *   1. Structural validation — required fields, types, formats.
 *   2. Semantic validation — e.g., ISBN format, year range.
 *
 * WHY NOT USE A LIBRARY LIKE JEST?
 * For this educational example, we write validation manually to demonstrate
 * the underlying logic. In production, libraries like Joi, Zod, or express-validator
 * provide more robust schema-based validation with less boilerplate.
 */

const { ValidationError } = require("./errorHandler");

// --------------------------------------------------------------------------
// ISBN Validation Helper
// --------------------------------------------------------------------------

/**
 * Validates an ISBN-13 string (13 digits, optionally separated by hyphens).
 * This is a simplified check — production apps should use the ISBN checksum algorithm.
 *
 * @param {string} isbn - The ISBN string to validate.
 * @returns {boolean} True if the format looks valid.
 */
function isValidIsbn(isbn) {
  // Remove hyphens and spaces, then check length and digit-only content
  const cleaned = isbn.replace(/[-\s]/g, "");
  return /^\d{13}$/.test(cleaned);
}

// --------------------------------------------------------------------------
// Book Creation Validation
// --------------------------------------------------------------------------

/**
 * Validates the request body for POST /books.
 * All fields except id are required; id is auto-generated so it must NOT be provided.
 *
 * @param {import('express').Request} req - Express request object.
 * @param {import('express').Response} _res - Express response object (unused).
 * @param {import('express').NextFunction} next - Express next function.
 * @throws {ValidationError} If any field is missing or invalid.
 */
function validateCreateBook(req, _res, next) {
  const { title, author, isbn, genre, publishedYear } = req.body;

  // Check required fields — each must be a non-empty string (except year)
  if (!title || typeof title !== "string" || title.trim() === "") {
    return next(new ValidationError("Field 'title' is required and must be a non-empty string"));
  }
  if (!author || typeof author !== "string" || author.trim() === "") {
    return next(new ValidationError("Field 'author' is required and must be a non-empty string"));
  }
  if (!isbn || typeof isbn !== "string" || !isValidIsbn(isbn)) {
    return next(new ValidationError("Field 'isbn' is required and must be a valid ISBN-13"));
  }
  if (!genre || typeof genre !== "string" || genre.trim() === "") {
    return next(new ValidationError("Field 'genre' is required and must be a non-empty string"));
  }
  if (
    publishedYear === undefined ||
    publishedYear === null ||
    !Number.isInteger(publishedYear) ||
    publishedYear < 0 ||
    publishedYear > new Date().getFullYear() + 1
  ) {
    return next(
      new ValidationError("Field 'publishedYear' is required and must be a valid year (0–" + (new Date().getFullYear() + 1) + ")")
    );
  }

  // Ensure client doesn't try to set the ID — that's server-managed
  if (req.body.id !== undefined) {
    return next(new ValidationError("Field 'id' is auto-generated and must not be provided"));
  }

  // Trim string fields to remove accidental whitespace
  req.body.title = title.trim();
  req.body.author = author.trim();
  req.body.genre = genre.trim();

  next(); // All validations passed — proceed to the route handler
}

// --------------------------------------------------------------------------
// Book Update Validation
// --------------------------------------------------------------------------

/**
 * Validates the request body for PUT /books/:id.
 * Unlike creation, all fields are optional (partial update).
 * If provided, each field is validated against the same rules.
 *
 * @param {import('express').Request} req - Express request object.
 * @param {import('express').Response} _res - Express response object (unused).
 * @param {import('express').NextFunction} next - Express next function.
 * @throws {ValidationError} If any provided field is invalid.
 */
function validateUpdateBook(req, _res, next) {
  const allowedFields = ["title", "author", "isbn", "genre", "publishedYear"];

  for (const field of allowedFields) {
    if (req.body[field] === undefined) continue; // Skip fields not present in the request

    switch (field) {
      case "title":
      case "author":
      case "genre":
        if (typeof req.body[field] !== "string" || req.body[field].trim() === "") {
          return next(new ValidationError(`Field '${field}' must be a non-empty string`));
        }
        break;

      case "isbn":
        if (typeof req.body[field] !== "string" || !isValidIsbn(req.body[field])) {
          return next(new ValidationError(`Field '${field}' must be a valid ISBN-13`));
        }
        break;

      case "publishedYear":
        if (
          !Number.isInteger(req.body[field]) ||
          req.body[field] < 0 ||
          req.body[field] > new Date().getFullYear() + 1
        ) {
          return next(new ValidationError(`Field '${field}' must be a valid year`));
        }
        break;
    }
  }

  // Strip disallowed fields (client shouldn't modify id, createdAt, updatedAt)
  const disallowed = ["id", "createdAt", "updatedAt"];
  for (const field of disallowed) {
    delete req.body[field];
  }

  next();
}

// --------------------------------------------------------------------------
// ID Parameter Validation
// --------------------------------------------------------------------------

/**
 * Validates that the :id route parameter is a positive integer.
 * Prevents invalid IDs like "abc" or "-1" from reaching route handlers.
 *
 * @param {import('express').Request} req - Express request object.
 * @param {import('express').Response} _res - Express response object (unused).
 * @param {import('express').NextFunction} next - Express next function.
 * @throws {ValidationError} If the ID is not a valid positive integer.
 */
function validateBookId(req, _res, next) {
  const id = parseInt(req.params.id, 10);

  if (isNaN(id) || id <= 0 || !Number.isInteger(id)) {
    return next(new ValidationError("Invalid book ID: must be a positive integer"));
  }

  // Replace the string param with a parsed number for downstream use
  req.params.id = id;
  next();
}

// Export validation middleware
module.exports = {
  validateCreateBook,
  validateUpdateBook,
  validateBookId,
};
```

> **Why separate validation from routes?** Keeping validation in its own module means:
> - Routes stay short and readable (they only handle business logic).
> - Validation rules can be reused across multiple endpoints.
> - Testing is easier — you can test validators independently of HTTP concerns.
>
> **Partial updates**: For `PUT`, we allow any subset of fields. This is more flexible than requiring all fields every time. The server merges only the provided fields with existing data.

