## File 5: `src/routes/books.js`

```javascript
/**
 * ============================================================================
 * BOOK ROUTES — CRUD Operations
 * ============================================================================
 *
 * DESIGN RATIONALE:
 * We organize routes by resource (books, stats) rather than by operation
 * (create, read, update, delete). This follows RESTful conventions where
 * the URL structure reflects the resource hierarchy.
 *
 * HTTP METHOD SEMANTICS:
 *   GET    — Safe, idempotent, no side effects. Used for listing and retrieval.
 *   POST   — Creates a new resource. Not idempotent (calling twice creates two books).
 *   PUT    — Full replacement of a resource. Idempotent (calling twice has same effect).
 *   DELETE — Removes a resource. Idempotent (deleting an already-deleted book is safe).
 *
 * WHY RETURN JSON WITH A `success` FLAG?
 * Consistent response shapes make client-side parsing predictable. Every
 * successful response includes { success: true, data: ... } and every error
 * includes { success: false, error: { name, message } }.
 */

const express = require("express");
const router = express.Router(); // Creates a standalone route handler

// Import our in-memory store functions
const { getAllBooks, getBookById, createBook, updateBook, deleteBook } = require("../models/book");

// Import custom error classes and utilities
const { NotFoundError, asyncHandler } = require("../middleware/errorHandler");

// Import validation middleware
const { validateCreateBook, validateUpdateBook, validateBookId } = require("../middleware/validation");

// --------------------------------------------------------------------------
// GET /books — List all books with optional filtering
// --------------------------------------------------------------------------

/**
 * @route   GET /books
 * @desc    Retrieve a list of all books with optional query filters
 * @access  Public
 *
 * QUERY PARAMETERS (all optional):
 *   - genre     : Filter by book genre (e.g., ?genre=Fiction)
 *   - author    : Filter by author name (case-insensitive partial match)
 *   - search    : Search title AND author (case-insensitive)
 *   - page      : Page number for pagination (default: 1)
 *   - limit     : Results per page (default: 10, max: 100)
 *
 * @example
 *   // Get all fiction books, page 2, 5 per page
 *   GET /books?genre=Fiction&page=2&limit=5
 *
 *   // Search for books by "Hawking"
 *   GET /books?author=hawking
 */
router.get(
  "/",
  asyncHandler(async (req, res) => {
    // Start with the full collection
    let result = getAllBooks();

    // Apply filters if query parameters are provided
    const { genre, author, search, page = 1, limit = 10 } = req.query;

    // Filter by genre (exact match, case-insensitive)
    if (genre) {
      result = result.filter((book) => book.genre.toLowerCase() === genre.toLowerCase());
    }

    // Filter by author (partial match, case-insensitive)
    if (author) {
      const authorLower = author.toLowerCase();
      result = result.filter((book) => book.author.toLowerCase().includes(authorLower));
    }

    // Global search across title and author
    if (search) {
      const searchLower = search.toLowerCase();
      result = result.filter(
        (book) =>
          book.title.toLowerCase().includes(searchLower) ||
          book.author.toLowerCase().includes(searchLower)
      );
    }

    // --- Pagination ---
    const totalPages = Math.ceil(result.length / limit);
    const currentPage = Math.max(1, parseInt(page, 10));
    const startIndex = (currentPage - 1) * limit;
    const paginatedResults = result.slice(startIndex, startIndex + limit);

    // Build the response with metadata for pagination
    res.json({
      success: true,
      data: paginatedResults,
      pagination: {
        currentPage,
        totalPages,
        totalBooks: result.length,
        limit: parseInt(limit, 10),
        hasNextPage: currentPage < totalPages,
        hasPrevPage: currentPage > 1,
      },
    });
  })
);

// --------------------------------------------------------------------------
// GET /books/:id — Get a single book by ID
// --------------------------------------------------------------------------

/**
 * @route   GET /books/:id
 * @desc    Retrieve a single book by its unique ID
 * @access  Public
 *
 * PATH PARAMETERS:
 *   - id : Numeric book ID (validated by middleware)
 *
 * @example
 *   // Get the book with ID 1
 *   GET /books/1
 *
 *   curl http://localhost:3000/books/1
 */
router.get(
  "/:id",
  validateBookId, // Validate that :id is a positive integer
  asyncHandler(async (req, res) => {
    const book = getBookById(req.params.id);

    if (!book) {
      // Throw NotFoundError — caught by the global error handler
      throw new NotFoundError("Book");
    }

    res.json({ success: true, data: book });
  })
);

// --------------------------------------------------------------------------
// POST /books — Create a new book
// --------------------------------------------------------------------------

/**
 * @route   POST /books
 * @desc    Create a new book record
 * @access  Public
 *
 * REQUEST BODY (JSON):
 *   {
 *     "title": "The Catcher in the Rye",
 *     "author": "J.D. Salinger",
 *     "isbn": "978-0316769488",
 *     "genre": "Fiction",
 *     "publishedYear": 1951
 *   }
 *
 * @example
 *   curl -X POST http://localhost:3000/books \
 *        -H "Content-Type: application/json" \
 *        -d '{"title":"The Catcher in the Rye","author":"J.D. Salinger",
 *             "isbn":"978-0316769488","genre":"Fiction","publishedYear":1951}'
 */
router.post(
  "/",
  validateCreateBook, // Validate request body before processing
  asyncHandler(async (req, res) => {
    const newBook = createBook(req.body);

    // Return 201 Created with the new resource in the response body
    // Location header points to the new resource's URL (REST best practice)
    res.status(201).json({
      success: true,
      data: newBook,
      message: "Book created successfully",
    });
  })
);

// --------------------------------------------------------------------------
// PUT /books/:id — Update an existing book (full replacement)
// --------------------------------------------------------------------------

/**
 * @route   PUT /books/:id
 * @desc    Fully update an existing book by ID
 * @access  Public
 *
 * PATH PARAMETERS:
 *   - id : Numeric book ID
 *
 * REQUEST BODY (JSON) — all fields optional for partial update:
 *   {
 *     "title": "Updated Title",
 *     "author": "Updated Author",
 *     "isbn": "978-0000000000",
 *     "genre": "New Genre",
 *     "publishedYear": 2024
 *   }
 *
 * @example
 *   curl -X PUT http://localhost:3000/books/1 \
 *        -H "Content-Type: application/json" \
 *        -d '{"title":"The Great Gatsby (Updated Edition)"}'
 */
router.put(
  "/:id",
  validateBookId,       // Validate the ID parameter
  validateUpdateBook,   // Validate the request body
  asyncHandler(async (req, res) => {
    const updatedBook = updateBook(req.params.id, req.body);

    if (!updatedBook) {
      throw new NotFoundError("Book");
    }

    // Return 200 OK with the updated resource
    res.json({
      success: true,
      data: updatedBook,
      message: "Book updated successfully",
    });
  })
);

// --------------------------------------------------------------------------
// DELETE /books/:id — Delete a book
// --------------------------------------------------------------------------

/**
 * @route   DELETE /books/:id
 * @desc    Delete a book by its ID
 * @access  Public
 *
 * PATH PARAMETERS:
 *   - id : Numeric book ID
 *
 * @example
 *   curl -X DELETE http://localhost:3000/books/1
 */
router.delete(
  "/:id",
  validateBookId, // Validate the ID parameter
  asyncHandler(async (req, res) => {
    const deleted = deleteBook(req.params.id);

    if (!deleted) {
      throw new NotFoundError("Book");
    }

    // Return 204 No Content — standard for successful deletions with no body
    res.status(204).end();
  })
);

// Export the router so app.js can mount it
module.exports = router;
```

> **Why `asyncHandler`?** Every route handler is wrapped in `asyncHandler`, which catches any rejected promises and forwards them to Express's error middleware. This means we never need try/catch blocks inside individual routes — errors flow naturally through the pipeline.

> **Why 201 for POST and 204 for DELETE?** These are REST conventions:
> - `201 Created` signals that a new resource was successfully created, and the response body contains the new resource.
> - `204 No Content` signals successful deletion with no response body — cleaner and more efficient.

> **Pagination metadata**: The `pagination` object in GET responses lets clients know total pages, current page, and whether next/prev links exist. This is essential for large datasets.

