## File 7: `src/app.js`

```javascript
/**
 * ============================================================================
 * APPLICATION ENTRY POINT — Express App Configuration
 * ============================================================================
 *
 * DESIGN RATIONALE:
 * app.js is responsible for:
 *   1. Creating the Express application instance.
 *   2. Configuring middleware (body parsing, JSON handling).
 *   3. Mounting route modules at their respective paths.
 *   4. Registering the global error handler.
 *
 * MIDDLEWARE ORDER MATTERS in Express:
 *   Middleware is executed top-to-bottom. Body parsers must come before routes
 *   so req.body is populated when routes run. The error handler MUST be last
 *   because it needs to catch errors from all preceding middleware/routes.
 *
 * WHY app.use() INSTEAD OF app.get()/app.post()?
 * app.use() mounts middleware or a router at a path prefix without caring
 * about the HTTP method. This is perfect for mounting entire route modules.
 */

const express = require("express");

// Create the Express application instance
const app = express();

// --------------------------------------------------------------------------
// Middleware Configuration
// --------------------------------------------------------------------------

/**
 * Body parser middleware — parses incoming JSON request bodies.
 * limit: 10kb prevents abnormally large payloads (DoS protection).
 *
 * Without this, req.body would be undefined and we couldn't read POST/PUT data.
 */
app.use(express.json({ limit: "10kb" }));

/**
 * Simple request logger — prints method, URL, and timestamp to console.
 * Useful for debugging during development.
 * In production, consider a proper logging library (winston, pino).
 */
app.use((req, res, next) => {
  console.log(`[${new Date().toISOString()}] ${req.method} ${req.url}`);
  next(); // Pass control to the next middleware/route
});

// --------------------------------------------------------------------------
// Route Mounting
// --------------------------------------------------------------------------

/**
 * Mount the books router at /books.
 * All routes defined in src/routes/books.js will be prefixed with /books.
 * For example, GET /books/:id in the router becomes GET /books/:id here.
 */
const bookRoutes = require("./routes/books");
app.use("/books", bookRoutes);

/**
 * Mount the stats router at /stats.
 */
const statsRoutes = require("./routes/stats");
app.use("/stats", statsRoutes);

// --------------------------------------------------------------------------
// Root Endpoint — API Health Check
// --------------------------------------------------------------------------

/**
 * @route   GET /
 * @desc    API health check — confirms the server is running
 * @access  Public
 */
app.get("/", (req, res) => {
  res.json({
    success: true,
    message: "Book REST API is running",
    endpoints: {
      books: "/books",
      stats: "/stats",
    },
  });
});

// --------------------------------------------------------------------------
// 404 Handler — Catch-all for undefined routes
// --------------------------------------------------------------------------

/**
 * Any request to an unregistered route falls through to this handler.
 * Returns 404 with a helpful message listing available endpoints.
 */
app.use((req, res, next) => {
  const error = new Error(`Route not found: ${req.method} ${req.url}`);
  error.statusCode = 404;
  next(error); // Pass to the global error handler
});

// --------------------------------------------------------------------------
// Global Error Handler — MUST be last middleware
// --------------------------------------------------------------------------

/**
 * The global error handler catches all errors passed via next(err).
 * It must be registered AFTER all routes and other middleware.
 */
const { errorHandler } = require("./middleware/errorHandler");
app.use(errorHandler);

// Export the configured app for server.js to use
module.exports = app;
```

> **Why middleware order matters:** Express executes middleware in registration order. If we mounted routes before `express.json()`, `req.body` would be undefined and all POST/PUT requests would fail. The error handler must be last so it can catch errors from every route and middleware above it.

> **Why a 404 catch-all?** Without it, Express returns its own generic 404 HTML page. Our custom handler returns JSON (consistent with our API) and passes the error to our global error handler for uniform formatting.

