```javascript
/**
 * ============================================================================
 * SERVER STARTUP — Listen on Port
 * ============================================================================
 *
 * DESIGN RATIONALE:
 * server.js is a thin wrapper around app.js. It handles only the HTTP server
 * creation and port binding. This separation lets us test the app (app.js)
 * independently of the network layer.
 */

const app = require("./app"); // Import the configured Express app

// Determine the port: use PORT env var, default to 3000, fallback to 5000
const PORT = process.env.PORT || 3000;

// Create and start the HTTP server
const server = app.listen(PORT, () => {
  console.log(`========================================`);
  console.log(`  Book REST API running on port ${PORT}`);
  console.log(`  Environment: ${process.env.NODE_ENV || "development"}`);
  console.log(`  Base URL: http://localhost:${PORT}`);
  console.log(`========================================`);
});

// Graceful shutdown — handle SIGTERM and SIGINT (Ctrl+C)
process.on("SIGTERM", () => {
  console.log("SIGTERM received. Shutting down gracefully...");
  server.close(() => {
    console.log("Server closed.");
    process.exit(0);
  });
});

process.on("SIGINT", () => {
  console.log("\nSIGINT received. Shutting down gracefully...");
  server.close(() => {
    console.log("Server closed.");
    process.exit(0);
  });
});

// Handle uncaught exceptions — log and exit to avoid running in a bad state
process.on("uncaughtException", (err) => {
  console.error("Uncaught Exception:", err);
  server.close(() => process.exit(1));
});

module.exports = server;
```

> **Why graceful shutdown?** When receiving SIGTERM/SIGINT, we call `server.close()` which stops accepting new connections and waits for existing requests to finish. This prevents dropping in-flight requests during deployments or restarts.

