## Arquivo 3: `src/middleware/errorHandler.js`

```javascript
/**
 * ============================================
 * MIDDLEWARE DE TRATAMENTO DE ERROS
 * ============================================
 *
 * POR QUE um middleware de erro dedicado?
 * ----------------------------------------
 * No Express, middlewares de erro têm ASSINATURA especial:
 *   (err, req, res, next) => { ... }
 * O Express os identifica pelo número de parâmetros (4 vs 3).
 *
 * Este middleware centraliza toda a lógica de resposta de erro,
 * evitando repetição em cada rota e garantindo consistência nas
 * respostas de erro para o cliente.
 *
 * ESTRUTURA DA RESPOSTA DE ERRO:
 * {
 *   success: false,
 *   error: {
 *     statusCode: 404,
 *     message: "Livro não encontrado",
 *     isOperational: true
 *   }
 * }
 */

const { AppError } = require("../errors/customErrors");

/**
 * Middleware principal de tratamento de erros.
 *
 * @param {Error} err - O erro capturado (pode ser qualquer objeto Error)
 * @param {import('express').Request} req - Objeto de requisição Express
 * @param {import('express').Response} res - Objeto de resposta Express
 * @param {import('express').NextFunction} next - Função para passar ao próximo middleware
 */
function errorHandler(err, req, res, next) {
  // Define valores padrão caso propriedades não estejam presentes
  let statusCode = err.statusCode || 500; // Padrão 500 = erro interno do servidor
  let message = err.message || "Erro interno no servidor";
  let isOperational = err.isOperational !== undefined ? err.isOperational : false;

  // Se for um erro operacional conhecido, responde com os dados do erro
  if (isOperational) {
    return res.status(statusCode).json({
      success: false,
      error: {
        statusCode,
        message,
        isOperational: true,
      },
    });
  }

  // ERROS NÃO-OPERACIONAIS (bugs): não expor detalhes internos
  // Logamos o erro completo no servidor para debugging, mas enviamos
  // apenas uma mensagem genérica ao cliente para segurança.
  console.error("❌ Erro não operacional (BUG):", err);

  return res.status(500).json({
    success: false,
    error: {
      statusCode: 500,
      message: "Erro interno no servidor. Tente novamente mais tarde.",
      isOperational: false,
    },
  });
}

/**
 * Middleware para capturar rotas não definidas (404).
 *
 * POR QUE usar este middleware em vez de tratar 404 nas rotas?
 * -------------------------------------------------------------
 * Se um cliente faz GET /livros/inexistente, nenhuma rota definida
 * vai corresponder. Este middleware captura todas as requisições
 * que chegam até ele sem terem sido respondidas, retornando 404.
 *
 * IMPORTANTE: este middleware DEVE ser colocado APÓS todas as rotas
 * definidas, caso contrário interceptaria todas as requisições.
 */
function notFoundMiddleware(req, res, next) {
  // Cria um AppError com código 404 para ser tratado pelo errorHandler
  const err = new Error(`Rota não encontrada: ${req.method} ${req.originalUrl}`);
  err.statusCode = 404;
  err.isOperational = true;
  next(err); // Passa o erro para o middleware de tratamento de erros
}

module.exports = { errorHandler, notFoundMiddleware };
```

**Explicação:** O Express usa uma convenção especial: middlewares com 4 parâmetros `(err, req, res, next)` são tratados como middlewares de erro. O `next(err)` é o que "pula" para esse middleware. O middleware `notFoundMiddleware` lida com rotas que não correspondem a nenhuma definição — um padrão essencial em APIs REST.

