## Arquivo 4: `src/data/books.js`

```javascript
/**
 * ============================================
 * ARMAZENAMENTO EM MEMÓRIA (DATA STORE)
 * ============================================
 *
 * POR QUE usar um array em memória?
 * ----------------------------------
 * Para este exemplo educacional, um array simples é suficiente porque:
 *   1. Não requer configuração de banco de dados
 *   2. Facilita o entendimento dos conceitos de CRUD
 *   3. Operações são O(1) para push/pop e O(n) para busca — aceitável
 *      para poucos registros em um exemplo
 *
 * POR QUE NÃO usar em produção?
 * ------------------------------
 *   - Dados são perdidos quando o processo reinicia (sem persistência)
 *   - Não escala para múltiplas instâncias do servidor
 *   - Buscas lineares tornam-se lentas com muitos registros
 *
 * Em produção, substituiríamos por um banco como MongoDB ou PostgreSQL.
 *
 * ESTRUTURA DO ARRAY:
 * Cada livro é um objeto com campos bem definidos para facilitar
 * a validação e documentação. O campo `id` é numérico e auto-incrementado.
 */

/**
 * Array que armazena todos os livros em memória.
 * @type {Array<{id: number, title: string, author: string, isbn: string, year: number, genre: string, price: number}>}
 */
const books = [];

/**
 * Contador para gerar IDs únicos e sequenciais.
 * Começa em 1 e incrementa a cada novo livro criado.
 * @type {number}
 */
let nextId = 1;

/**
 * Insere um livro no array e retorna o objeto completo com ID atribuído.
 *
 * @param {Object} bookData - Dados do livro a ser inserido
 * @param {string} bookData.title - Título do livro (obrigatório)
 * @param {string} bookData.author - Autor do livro (obrigatório)
 * @param {string} bookData.isbn - ISBN do livro (obrigatório, único)
 * @param {number} bookData.year - Ano de publicação (opcional)
 * @param {string} bookData.genre - Gênero literário (opcional)
 * @param {number} bookData.price - Preço em reais (opcional)
 * @returns {Object} O livro criado com ID atribuído
 */
function createBook(bookData) {
  const newBook = {
    id: nextId++, // Atribui ID sequencial e incrementa o contador
    title: bookData.title,
    author: bookData.author,
    isbn: bookData.isbn,
    year: bookData.year || null, // Usa null se não fornecido (melhor que undefined)
    genre: bookData.genre || null,
    price: bookData.price || 0, // Padrão 0 se não fornecido
  };

  books.push(newBook); // Adiciona ao final do array
  return newBook;
}

/**
 * Retorna todos os livros armazenados.
 *
 * @returns {Array} Cópia do array de livros (para evitar mutação externa)
 */
function getAllBooks() {
  return [...books]; // Spread operator cria uma cópia rasa do array
}

/**
 * Busca um livro pelo ID.
 *
 * @param {number} id - ID numérico do livro
 * @returns {Object|undefined} O livro encontrado ou undefined se não existir
 */
function getBookById(id) {
  return books.find((book) => book.id === id); // find() retorna o primeiro match
}

/**
 * Busca um livro pelo ISBN.
 *
 * @param {string} isbn - ISBN do livro
 * @returns {Object|undefined} O livro encontrado ou undefined se não existir
 */
function getBookByIsbn(isbn) {
  return books.find((book) => book.isbn === isbn);
}

/**
 * Atualiza um livro existente pelo ID.
 *
 * @param {number} id - ID do livro a ser atualizado
 * @param {Object} updates - Campos a serem atualizados (partial update)
 * @returns {Object|undefined} O livro atualizado ou undefined se não existir
 */
function updateBook(id, updates) {
  const index = books.findIndex((book) => book.id === id); // findIndex para obter o índice

  if (index === -1) return undefined; // Livro não encontrado

  // Atualiza apenas os campos fornecidos (partial update / PATCH semantics)
  // Usamos Object.keys para iterar sobre as chaves do objeto de updates
  const book = books[index];
  for (const key of Object.keys(updates)) {
    if (updates[key] !== undefined && updates[key] !== null) {
      book[key] = updates[key];
    }
  }

  return { ...books[index] }; // Retorna cópia para evitar mutação direta
}

/**
 * Remove um livro pelo ID.
 *
 * @param {number} id - ID do livro a ser removido
 * @returns {boolean} true se removido, false se não encontrado
 */
function deleteBook(id) {
  const index = books.findIndex((book) => book.id === id);

  if (index === -1) return false; // Livro não encontrado

  books.splice(index, 1); // splice remove 1 elemento na posição index
  return true;
}

/**
 * Calcula estatísticas sobre os livros armazenados.
 *
 * @returns {Object} Estatísticas: total, média de preço, por gênero, etc.
 */
function getStats() {
  const total = books.length;

  if (total === 0) {
    return {
      totalLivros: 0,
      mediaPreco: 0,
      precoMinimo: null,
      precoMaximo: null,
      livrosPorGenero: {},
      livrosPorAno: {},
    };
  }

  // Reduz o array para calcular soma e encontrar min/max de preços
  const { somaPreco, precoMinimo, precoMaximo } = books.reduce(
    (acc, book) => ({
      somaPreco: acc.somaPreco + book.price,
      precoMinimo: Math.min(acc.precoMinimo, book.price),
      precoMaximo: Math.max(acc.precoMaximo, book.price),
    }),
    { somaPreco: 0, precoMinimo: Infinity, precoMaximo: -Infinity }
  );

  // Agrupa livros por gênero usando reduce
  const livrosPorGenero = books.reduce((acc, book) => {
    const genero = book.genre || "Sem gênero";
    acc[genero] = (acc[genero] || 0) + 1;
    return acc;
  }, {});

  // Agrupa livros por ano de publicação
  const livrosPorAno = books.reduce((acc, book) => {
    if (book.year) {
      acc[book.year] = (acc[book.year] || 0) + 1;
    }
    return acc;
  }, {});

  return {
    totalLivros: total,
    mediaPreco: parseFloat((somaPreco / total).toFixed(2)),
    precoMinimo,
    precoMaximo,
    livrosPorGenero,
    livrosPorAno,
  };
}

// Exporta todas as funções do data store
module.exports = {
  createBook,
  getAllBooks,
  getBookById,
  getBookByIsbn,
  updateBook,
  deleteBook,
  getStats,
};
```

**Explicação:** O data store usa um array simples com funções puras (sem efeitos colaterais visíveis fora do módulo). Cada função opera sobre o estado interno e retorna cópias quando necessário para evitar que código externo modifique os dados diretamente. O `getStats()` usa `reduce()` — uma função de ordem superior que acumula resultados — para calcular métricas em uma única passagem pelo array, sendo mais eficiente que múltiplos loops.

