## Arquivo 5: `src/routes/books.js`

```javascript
/**
 * ============================================
 * ROTAS DA API DE LIVROS
 * ============================================
 *
 * POR QUE usar express.Router()?
 * --------------------------------
 * O Router permite agrupar rotas relacionadas em um módulo separado,
 * facilitando a manutenção e a escalabilidade. Em vez de definir todas
 * as rotas no app.js, cada domínio (livros, usuários, etc.) tem seu
 * próprio arquivo de rotas.
 *
 * CONVENÇÕES REST utilizadas:
 * ----------------------------
 *   GET    /books          → Listar todos os livros
 *   GET    /books/:id      → Obter livro específico
 *   POST   /books          → Criar novo livro
 *   PUT    /books/:id      → Atualizar livro completo (substituição)
 *   DELETE /books/:id      → Excluir livro
 *
 *   PUT vs PATCH: Usamos PUT porque substituímos o recurso inteiro.
 *   Em uma API real, teríamos ambos: PUT para atualização total e
 *   PATCH para atualização parcial.
 *
 * FILTRAGEM na listagem (GET /books):
 * ------------------------------------
 *   ?author=...    → Filtra por autor (busca parcial, case-insensitive)
 *   ?genre=...     → Filtra por gênero
 *   ?minPrice=...  → Preço mínimo
 *   ?maxPrice=...  → Preço máximo
 *   ?search=...    → Busca por título ou autor
 *
 *   Exemplo: GET /books?author=machado&genre=romance&minPrice=20
 */

const express = require("express");
const router = express.Router(); // Cria um novo roteador Express

// Importa funções do data store (camada de dados)
const {
  createBook,
  getAllBooks,
  getBookById,
  getBookByIsbn,
  updateBook,
  deleteBook,
} = require("../data/books");

// Importa classes de erro personalizadas
const { ValidationError, NotFoundError } = require("../errors/customErrors");

/**
 * ============================================
 * GET /books — Listar todos os livros com filtragem
 * ============================================
 *
 * Retorna uma lista paginada e filtrada de livros.
 * Os filtros são aplicados via query parameters (URL search params).
 *
 * @example
 * // curl -X GET "http://localhost:3000/books"
 * // curl -X GET "http://localhost:3000/books?author=machado&genre=romance"
 * // curl -X GET "http://localhost:3000/books?minPrice=10&maxPrice=50"
 * // curl -X GET "http://localhost:3000/books?page=1&limit=10"
 */
router.get("/", (req, res, next) => {
  try {
    // Obtém todos os livros do data store
    let result = getAllBooks();

    // --- FILTRO POR AUTOR (busca parcial, case-insensitive) ---
    if (req.query.author) {
      const authorFilter = req.query.author.toLowerCase();
      result = result.filter((book) =>
        book.author.toLowerCase().includes(authorFilter)
      );
    }

    // --- FILTRO POR GÊNERO ---
    if (req.query.genre) {
      const genreFilter = req.query.genre.toLowerCase();
      result = result.filter(
        (book) => book.genre && book.genre.toLowerCase() === genreFilter
      );
    }

    // --- FILTRO POR PREÇO MÍNIMO ---
    if (req.query.minPrice) {
      const minPrice = parseFloat(req.query.minPrice);
      if (!isNaN(minPrice)) {
        result = result.filter((book) => book.price >= minPrice);
      }
    }

    // --- FILTRO POR PREÇO MÁXIMO ---
    if (req.query.maxPrice) {
      const maxPrice = parseFloat(req.query.maxPrice);
      if (!isNaN(maxPrice)) {
        result = result.filter((book) => book.price <= maxPrice);
      }
    }

    // --- BUSCA POR TÍTULO OU AUTOR ---
    if (req.query.search) {
      const searchFilter = req.query.search.toLowerCase();
      result = result.filter(
        (book) =>
          book.title.toLowerCase().includes(searchFilter) ||
          book.author.toLowerCase().includes(searchFilter)
      );
    }

    // --- PAGINAÇÃO ---
    const page = parseInt(req.query.page) || 1; // Padrão: página 1
    const limit = parseInt(req.query.limit) || 10; // Padrão: 10 por página
    const startIndex = (page - 1) * limit;
    const endIndex = startIndex + limit;
    const paginatedResult = result.slice(startIndex, endIndex);

    // Retorna resposta estruturada com metadados de paginação
    res.json({
      success: true,
      total: result.length, // Total após filtragem (antes da paginação)
      page,
      limit,
      totalPages: Math.ceil(result.length / limit),
      data: paginatedResult,
    });
  } catch (err) {
    next(err); // Passa erro para o middleware de tratamento de erros
  }
});

/**
 * ============================================
 * GET /books/:id — Obter livro por ID
 * ============================================
 *
 * Busca um livro específico pelo seu identificador numérico.
 * Retorna 404 se o livro não for encontrado.
 *
 * @example
 * // curl -X GET "http://localhost:3000/books/1"
 */
router.get("/:id", (req, res, next) => {
  try {
    const id = parseInt(req.params.id); // Converte param de string para número

    // Valida se o ID é um número válido
    if (isNaN(id)) {
      throw new ValidationError("ID deve ser um número inteiro válido");
    }

    const book = getBookById(id);

    if (!book) {
      // Lança NotFoundError para ser tratado pelo middleware de erros
      throw new NotFoundError("Livro");
    }

    res.json({ success: true, data: book });
  } catch (err) {
    next(err);
  }
});

/**
 * ============================================
 * POST /books — Criar novo livro
 * ============================================
 *
 * Cria um novo livro a partir dos dados enviados no corpo da requisição.
 * Valida campos obrigatórios e verifica duplicidade de ISBN.
 *
 * Corpo esperado (JSON):
 * {
 *   "title": "Dom Casmurro",
 *   "author": "Machado de Assis",
 *   "isbn": "978-85-359-0277-5",
 *   "year": 1899,
 *   "genre": "Romance",
 *   "price": 29.90
 * }
 *
 * @example
 * // curl -X POST "http://localhost:3000/books" \
 * //   -H "Content-Type: application/json" \
 * //   -d '{"title":"Dom Casmurro","author":"Machado de Assis","isbn":"978-85-359-0277-5","year":1899,"genre":"Romance","price":29.90}'
 */
router.post("/", (req, res, next) => {
  try {
    const { title, author, isbn, year, genre, price } = req.body;

    // --- VALIDAÇÃO DOS CAMPOS OBRIGATÓRIOS ---
    if (!title || typeof title !== "string" || title.trim() === "") {
      throw new ValidationError("Campo 'title' é obrigatório e deve ser uma string");
    }
    if (!author || typeof author !== "string" || author.trim() === "") {
      throw new ValidationError("Campo 'author' é obrigatório e deve ser uma string");
    }
    if (!isbn || typeof isbn !== "string" || isbn.trim() === "") {
      throw new ValidationError("Campo 'isbn' é obrigatório e deve ser uma string");
    }

    // --- VALIDAÇÃO DO ISBN (deve ser único) ---
    const existingByIsbn = getBookByIsbn(isbn);
    if (existingByIsbn) {
      throw new ValidationError(
        `Já existe um livro com o ISBN ${isbn}`
      );
    }

    // --- VALIDAÇÃO DO ANO ---
    let parsedYear = null;
    if (year !== undefined && year !== null) {
      parsedYear = parseInt(year);
      if (isNaN(parsedYear) || parsedYear < 0 || parsedYear > new Date().getFullYear() + 1) {
        throw new ValidationError("Campo 'year' deve ser um ano válido");
      }
    }

    // --- VALIDAÇÃO DO GÊNERO ---
    let parsedGenre = null;
    if (genre !== undefined && genre !== null) {
      if (typeof genre !== "string" || genre.trim() === "") {
        throw new ValidationError("Campo 'genre' deve ser uma string não vazia");
      }
      parsedGenre = genre.trim();
    }

    // --- VALIDAÇÃO DO PREÇO ---
    let parsedPrice = 0;
    if (price !== undefined && price !== null) {
      parsedPrice = parseFloat(price);
      if (isNaN(parsedPrice) || parsedPrice < 0) {
        throw new ValidationError("Campo 'price' deve ser um número não negativo");
      }
    }

    // Cria o livro no data store
    const newBook = createBook({
      title: title.trim(),
      author: author.trim(),
      isbn: isbn.trim(),
      year: parsedYear,
      genre: parsedGenre,
      price: parsedPrice,
    });

    // 201 Created é o código HTTP padrão para recursos criados com sucesso
    res.status(201).json({ success: true, data: newBook });
  } catch (err) {
    next(err);
  }
});

/**
 * ============================================
 * PUT /books/:id — Atualizar livro existente
 * ============================================
 *
 * Substitui completamente os dados de um livro pelo ID fornecido.
 * Todos os campos obrigatórios devem ser enviados.
 *
 * Corpo esperado (JSON):
 * {
 *   "title": "Nova Edição",
 *   "author": "Novo Autor",
 *   "isbn": "978-85-359-0277-6",
 *   "year": 2024,
 *   "genre": "Romance Contemporâneo",
 *   "price": 49.90
 * }
 *
 * @example
 * // curl -X PUT "http://localhost:3000/books/1" \
 * //   -H "Content-Type: application/json" \
 * //   -d '{"title":"Dom Casmurro (Ed. Fac-símile)","author":"Machado de Assis","isbn":"978-85-359-0277-5","year":1899,"genre":"Romance","price":39.90}'
 */
router.put("/:id", (req, res, next) => {
  try {
    const id = parseInt(req.params.id);

    if (isNaN(id)) {
      throw new ValidationError("ID deve ser um número inteiro válido");
    }

    // Verifica se o livro existe antes de atualizar
    const existingBook = getBookById(id);
    if (!existingBook) {
      throw new NotFoundError("Livro");
    }

    const { title, author, isbn, year, genre, price } = req.body;

    // --- VALIDAÇÃO DOS CAMPOS OBRIGATÓRIOS ---
    if (!title || typeof title !== "string" || title.trim() === "") {
      throw new ValidationError("Campo 'title' é obrigatório e deve ser uma string");
    }
    if (!author || typeof author !== "string" || author.trim() === "") {
      throw new ValidationError("Campo 'author' é obrigatório e deve ser uma string");
    }
    if (!isbn || typeof isbn !== "string" || isbn.trim() === "") {
      throw new ValidationError("Campo 'isbn' é obrigatório e deve ser uma string");
    }

    // Verifica se o ISBN já existe em OUTRO livro (não pode haver duplicidade)
    const bookWithSameIsbn = getBookByIsbn(isbn);
    if (bookWithSameIsbn && bookWithSameIsbn.id !== id) {
      throw new ValidationError(
        `Já existe outro livro com o ISBN ${isbn}`
      );
    }

    // Validações opcionais (ano, gênero, preço)
    let parsedYear = null;
    if (year !== undefined && year !== null) {
      parsedYear = parseInt(year);
      if (isNaN(parsedYear) || parsedYear < 0 || parsedYear > new Date().getFullYear() + 1) {
        throw new ValidationError("Campo 'year' deve ser um ano válido");
      }
    }

    let parsedGenre = null;
    if (genre !== undefined && genre !== null) {
      if (typeof genre !== "string" || genre.trim() === "") {
        throw new ValidationError("Campo 'genre' deve ser uma string não vazia");
      }
      parsedGenre = genre.trim();
    }

    let parsedPrice = 0;
    if (price !== undefined && price !== null) {
      parsedPrice = parseFloat(price);
      if (isNaN(parsedPrice) || parsedPrice < 0) {
        throw new ValidationError("Campo 'price' deve ser um número não negativo");
      }
    }

    // Atualiza o livro no data store
    const updatedBook = updateBook(id, {
      title: title.trim(),
      author: author.trim(),
      isbn: isbn.trim(),
      year: parsedYear,
      genre: parsedGenre,
      price: parsedPrice,
    });

    res.json({ success: true, data: updatedBook });
  } catch (err) {
    next(err);
  }
});

/**
 * ============================================
 * DELETE /books/:id — Excluir livro
 * ============================================
 *
 * Remove permanentemente um livro pelo ID.
 * Retorna 204 No Content em caso de sucesso (sem corpo na resposta).
 *
 * @example
 * // curl -X DELETE "http://localhost:3000/books/1"
 */
router.delete("/:id", (req, res, next) => {
  try {
    const id = parseInt(req.params.id);

    if (isNaN(id)) {
      throw new ValidationError("ID deve ser um número inteiro válido");
    }

    const existingBook = getBookById(id);
    if (!existingBook) {
      throw new NotFoundError("Livro");
    }

    const deleted = deleteBook(id);

    // 204 No Content: sucesso, mas sem corpo na resposta (padrão REST para DELETE)
    if (deleted) {
      res.status(204).end();
    } else {
      throw new NotFoundError("Livro");
    }
  } catch (err) {
    next(err);
  }
});

module.exports = router;
```

**Explicação:** Cada rota segue o padrão `(req, res, next) => { ... }` com tratamento de erros via `try/catch` e `next(err)`. Isso garante que qualquer erro lançado dentro da rota seja capturado pelo middleware de tratamento de erros centralizado. A filtragem usa `filter()` do Array para aplicar múltiplos critérios simultaneamente — cada filtro é aplicado sequencialmente, criando uma cadeia de redução do resultado.

