## Arquivo 6: `src/app.js`

```javascript
/**
 * ============================================
 * APP PRINCIPAL — Configuração e inicialização
 * ============================================
 *
 * POR QUE separar a configuração da lógica de negócio?
 * ----------------------------------------------------
 * O app.js é o "orquestrador" que conecta todas as partes:
 *   1. Middleware global (body-parser, CORS)
 *   2. Rotas da API
 *   3. Tratamento de erros
 *   4. Rota de estatísticas
 *
 * Esta separação permite que cada módulo seja testado e mantido
 * independentemente, seguindo o princípio de responsabilidade única.
 *
 * POR QUE usar async/await?
 * --------------------------
 * Async/await torna o código assíncrono mais legível ao eliminarmos
 * callbacks aninhados ("callback hell"). Embora este exemplo não
 * use operações assíncronas (o data store é síncrono), a estrutura
 * está preparada para evoluir para um banco de dados assíncrono.
 */

const express = require("express");
const app = express(); // Cria a aplicação Express

// ============================================
// MIDDLEWARE GLOBAL
// ============================================

/**
 * body-parser: parseia o corpo das requisições JSON automaticamente.
 * Sem este middleware, req.body seria undefined.
 * O limit de 10mb evita requisições excessivamente grandes.
 */
app.use(express.json({ limit: "10mb" }));

/**
 * CORS (Cross-Origin Resource Sharing): permite que frontends de
 * diferentes origens acessem esta API. Em produção, restrinja
 * o allowedOrigins ao domínio do seu frontend.
 */
const cors = require("cors");
app.use(cors());

/**
 * Logger simples: registra cada requisição no console.
 * Formato: [TIMESTAMP] METHOD PATH → STATUS
 */
app.use((req, res, next) => {
  const timestamp = new Date().toISOString();
  console.log(`[${timestamp}] ${req.method} ${req.path}`);
  next(); // Passa para o próximo middleware/rota
});

// ============================================
// ROTAS DA API
// ============================================

// Importa as rotas de livros (módulo separado)
const bookRoutes = require("./routes/books");

// Mount das rotas: todas as rotas de livros começam com /books
app.use("/books", bookRoutes);

/**
 * ============================================
 * GET /stats — Estatísticas da API
 * ============================================
 *
 * Retorna métricas agregadas sobre os livros cadastrados.
 * Este endpoint é apenas para leitura (GET) e não modifica dados.
 *
 * Resposta de exemplo:
 * {
 *   "success": true,
 *   "data": {
 *     "totalLivros": 5,
 *     "mediaPreco": 34.50,
 *     "precoMinimo": 19.90,
 *     "precoMaximo": 89.90,
 *     "livrosPorGenero": { "Romance": 2, "Ficção": 3 },
 *     "livrosPorAno": { "1899": 1, "2024": 4 }
 *   }
 * }
 *
 * @example
 * // curl -X GET "http://localhost:3000/stats"
 */
const { getStats } = require("./data/books");

app.get("/stats", (req, res, next) => {
  try {
    const stats = getStats();
    res.json({ success: true, data: stats });
  } catch (err) {
    next(err);
  }
});

// ============================================
// MIDDLEWARES DE ERRO (deve ser o ÚLTIMO middleware)
// ============================================

const { errorHandler, notFoundMiddleware } = require("./middleware/errorHandler");

// Rota não encontrada: captura requisições para rotas inexistentes
app.use(notFoundMiddleware);

// Tratamento centralizado de erros
app.use(errorHandler);

// ============================================
// INICIALIZAÇÃO DO SERVIDOR
// ============================================

const PORT = process.env.PORT || 3000; // Porta configurável via variável de ambiente

/**
 * Inicia o servidor e faz log de confirmação.
 * O callback é executado quando o servidor começa a ouvir conexões.
 */
app.listen(PORT, () => {
  console.log(`📚 API de Livros rodando em http://localhost:${PORT}`);
  console.log(`📖 Documentação dos endpoints:`);
  console.log(`   GET    http://localhost:${PORT}/books          — Listar livros`);
  console.log(`   GET    http://localhost:${PORT}/books/:id      — Obter livro por ID`);
  console.log(`   POST   http://localhost:${PORT}/books          — Criar livro`);
  console.log(`   PUT    http://localhost:${PORT}/books/:id      — Atualizar livro`);
  console.log(`   DELETE http://localhost:${PORT}/books/:id      — Excluir livro`);
  console.log(`   GET    http://localhost:${PORT}/stats          — Estatísticas`);
});

module.exports = app; // Exporta para testes (ex: jest, supertest)
```

**Explicação:** O Express processa middlewares e rotas em ordem sequencial. Por isso, `notFoundMiddleware` e `errorHandler` devem vir por último — se colocados antes das rotas, interceptariam todas as requisições. O `app.listen()` é assíncrono: o callback só executa quando o servidor realmente começa a aceitar conexões. A porta pode ser sobrescrita via variável de ambiente `PORT`, facilitando deploy em diferentes ambientes (desenvolvimento, staging, produção).

