```javascript
/**
 * ============================================================================
 * CUSTOM ERROR CLASSES
 * ============================================================================
 *
 * WHY custom error classes instead of plain Error objects?
 *   - They carry structured metadata (statusCode, isOperational) that middleware
 *     can read to produce consistent JSON error responses.
 *   - "isOperational" distinguishes bugs in our code (not operational) from
 *     expected failures like "resource not found" (operational).
 *   - This pattern lets the error-handling middleware decide: should we log this
 *     as a server bug, or return a 4xx to the client?
 */

/**
 * Base class for all application errors.
 * Extends Node's built-in Error so it works with instanceof checks and stack traces.
 */
class AppError extends Error {
  /**
   * @param {string} message - Human-readable error description.
   * @param {number} statusCode - HTTP status code to return (e.g., 400, 404).
   */
  constructor(message, statusCode) {
    super(message); // Pass message up to Error so .message and stack work normally.

    this.statusCode = statusCode;       // HTTP status for the response.
    this.isOperational = true;          // True = expected failure (client's fault).
    this.errorType = 'AppError';        // Tag for logging/middleware identification.

    // Capture a clean stack trace (without the constructor noise from Error.captureStackTrace).
    Error.captureStackTrace(this, this.constructor);
  }
}

/**
 * BadRequestError — The client sent invalid data or parameters.
 * Example: missing required fields, malformed ID, invalid filter values.
 */
class BadRequestError extends AppError {
  /** @param {string} [message='Bad request'] */
  constructor(message = 'Bad request') {
    super(message, 400); // 400 = Bad Request per HTTP spec.
    this.errorType = 'BadRequestError';
  }
}

/**
 * NotFoundError — The requested resource does not exist.
 * Example: GET /books/999 when only IDs 1–5 exist.
 */
class NotFoundError extends AppError {
  /** @param {string} [message='Resource not found'] */
  constructor(message = 'Resource not found') {
    super(message, 404); // 404 = Not Found per HTTP spec.
    this.errorType = 'NotFoundError';
  }
}

/**
 * ConflictError — The request conflicts with the current state.
 * Example: creating a book with an ID that already exists.
 */
class ConflictError extends AppError {
  /** @param {string} [message='Resource conflict'] */
  constructor(message = 'Resource conflict') {
    super(message, 409); // 409 = Conflict per HTTP spec.
    this.errorType = 'ConflictError';
  }
}

/**
 * InternalServerError — An unexpected server-side failure.
 * Used as a fallback when no other error class fits.
 */
class InternalServerError extends AppError {
  /** @param {string} [message='Internal server error'] */
  constructor(message = 'Internal server error') {
    super(message, 500); // 500 = Internal Server Error per HTTP spec.
    this.errorType = 'InternalServerError';
    this.isOperational = false; // This is a BUG, not a client mistake.
  }
}

// Export all error classes so routes and middleware can import them.
module.exports = {
  AppError,
  BadRequestError,
  NotFoundError,
  ConflictError,
  InternalServerError,
};
```

**Design rationale:** Each error class extends `AppError`, which itself extends Node's native `Error`. This means:
- `.message` and `.stack` work automatically (inherited from `Error`).
- `instanceof Error` checks still pass.
- The middleware can inspect `error.statusCode` and `error.isOperational` to decide how to respond.

