    title: 'To Kill a Mockingbird',
    author: 'Harper Lee',
    isbn: '978-0061120084',
    publishedYear: 1960,
    genre: 'Fiction',
    createdAt: new Date('2024-01-01T00:00:00.000Z'),
    updatedAt: new Date('2024-01-01T00:00:00.000Z'),
  },
  {
    id: nextId++,
    title: 'A Brief History of Time',
    author: 'Stephen Hawking',
    isbn: '978-0553380163',
    publishedYear: 1988,
    genre: 'Science',
    createdAt: new Date('2024-01-01T00:00:00.000Z'),
    updatedAt: new Date('2024-01-01T00:00:00.000Z'),
  },
  {
    id: nextId++,
    title: 'The Art of War',
    author: 'Sun Tzu',
    isbn: '978-1599869773',
    publishedYear: -500, // BCE year — negative for historical accuracy
    genre: 'Philosophy',
    createdAt: new Date('2024-01-01T00:00:00.000Z'),
    updatedAt: new Date('2024-01-01T00:00:00.000Z'),
  },
  {
    id: nextId++,
    title: 'Clean Code',
    author: 'Robert C. Martin',
    isbn: '978-0132350884',
    publishedYear: 2008,
    genre: 'Technology',
    createdAt: new Date('2024-01-01T00:00:00.000Z'),
    updatedAt: new Date('2024-01-01T00:00:00.000Z'),
  },
];

// Populate the store on module load.
books.push(...seedBooks);

// ─── CRUD Operations ──────────────────────────────────────────────────────────

/**
 * Retrieves all books, optionally filtered by query parameters.
 *
 * @param {Object} [filters] - Optional filter criteria from request query string.
 * @param {string} [filters.genre] - Filter by genre (case-insensitive partial match).
 * @param {string} [filters.author] - Filter by author name (case-insensitive partial match).
 * @param {number} [filters.minYear] - Minimum published year (inclusive).
 * @param {number} [filters.maxYear] - Maximum published year (inclusive).
 * @returns {Array<Object>} Array of book objects matching the filters.
 *
 * WHY return a new array instead of mutating `books`?
 *   - Immutability prevents accidental side effects in other parts of the app.
 *   - filter() returns a shallow copy, so callers can safely modify the result
 *     without affecting the stored data.
 */
function getAllBooks(filters = {}) {
  let result = books;

  // Apply genre filter if provided — case-insensitive partial match for usability.
  if (filters.genre) {
    const genrePattern = new RegExp(filters.genre, 'i'); // 'i' flag = case-insensitive
    result = result.filter((book) => genrePattern.test(book.genre));
  }

  // Apply author filter — also case-insensitive partial match.
  if (filters.author) {
    const authorPattern = new RegExp(filters.author, 'i');
    result = result.filter((book) => authorPattern.test(book.author));
  }

  // Apply year range filters if provided.
  if (filters.minYear !== undefined) {
    result = result.filter((book) => book.publishedYear >= Number(filters.minYear));
  }
  if (filters.maxYear !== undefined) {
    result = result.filter((book) => book.publishedYear <= Number(filters.maxYear));
  }

  return result;
}

/**
 * Finds a single book by its numeric ID.
 *
 * @param {number} id - The unique identifier of the book.
 * @returns {Object|null} The book object if found, null otherwise.
 *
 * WHY use Array.find() instead of a Map?
 *   - For small datasets (dozens to hundreds), find() is fast enough and keeps
 *     the code simple. A Map would be better for thousands+ records where O(1)
 *     lookups matter. This trade-off is documented so you know when to upgrade.
 */
function getBookById(id) {
  return books.find((book) => book.id === id) || null;
}

/**
 * Creates a new book and adds it to the store.
 *
 * @param {Object} bookData - The book data to create (without id, createdAt, updatedAt).
 * @param {string} bookData.title - Book title (required).
 * @param {string} bookData.author - Author name (required).
 * @param {string} [bookData.isbn] - ISBN-13 format string.
 * @param {number} [bookData.publishedYear] - Year of publication.
 * @param {string} [bookData.genre] - Book genre/category.
 * @returns {Object} The newly created book with generated id, createdAt, and updatedAt.
 *
 * WHY generate IDs server-side?
 *   - Prevents clients from guessing or colliding with existing IDs.
 *   - Ensures uniqueness without client coordination.
 *   - In a real app, databases handle this via auto-increment or UUID generators.
 */
function createBook(bookData) {
  const now = new Date(); // Capture creation time once to keep timestamps consistent.

  const newBook = {
    id: nextId++,                    // Auto-increment: simple, predictable, unique.
    title: bookData.title,
    author: bookData.author,
    isbn: bookData.isbn || null,     // ISBN is optional; store null if not provided.
    publishedYear: bookData.publishedYear || null,
    genre: bookData.genre || null,
    createdAt: now,                  // ISO 8601 timestamp for audit trail.
    updatedAt: now,                  // Same as createdAt on creation.
  };

  books.push(newBook);               // Add to in-memory store.
  return newBook;                    // Return the full object including generated fields.
}

/**
 * Updates an existing book by ID with partial or full data.
 *
 * @param {number} id - The ID of the book to update.
 * @param {Object} updates - Fields to update (only provided fields are changed).
 * @returns {Object|null} The updated book object, or null if not found.
 *
 * WHY use spread operator ({ ...book, ...updates })?
 *   - Creates a new object with updated fields without mutating the original.
 *   - Only explicitly provided fields in `updates` are overwritten; others stay.
 *   - This is the essence of a PATCH-style update (partial replacement).
 */
function updateBook(id, updates) {
  const index = books.findIndex((book) => book.id === id);
  if (index === -1) return null; // Book not found — caller should throw NotFoundError.

  // Create updated object: spread existing fields, then overlay new values.
  const updatedBook = {
    ...books[index],               // Copy all existing fields.
    ...updates,                    // Overwrite with provided updates.
    id,                            // ID must never change (primary key immutability).
    updatedAt: new Date(),         // Track when the record was last modified.
  };

  books[index] = updatedBook;      // Replace in store (in-place mutation of array slot).
  return updatedBook;
}

/**
 * Deletes a book by ID.
 *
 * @param {number} id - The ID of the book to delete.
 * @returns {boolean} True if the book was found and deleted, false otherwise.
 *
 * WHY use filter() instead of splice()?
 *   - filter() is functional and returns a new array (immutability).
 *   - splice() mutates in place but is equally valid here since we're replacing
 *     the entire `books` reference anyway. Both approaches are fine; this choice
 *     keeps the code declarative.
 */
function deleteBook(id) {
  const initialLength = books.length;
  // Keep only books whose ID does NOT match the target — effectively removing it.
  Object.assign(books, books.filter((book) => book.id !== id));
  return books.length < initialLength; // True if something was actually removed.
}

// ─── Statistics ────────────────────────────────────────────────────────────────

/**
 * Computes aggregate statistics about the book collection.
 *
 * @returns {Object} Statistics object containing:
 *   - totalBooks: Total number of books in the store.
 *   - genres: Record mapping each genre to its book count.
 *   - authors: Record mapping each author to their book count.
 *   - averagePublishedYear: Mean publication year (null if no books).
 *   - oldestBook: The book with the earliest publishedYear.
 *   - newestBook: The book with the latest publishedYear.
 *
 * WHY compute stats on-demand instead of caching?
 *   - For an in-memory store, computation is trivial (< 1ms for any reasonable size).
 *   - Caching would add complexity (invalidation logic) without meaningful benefit.
 *   - In a real app with a database, you'd use SQL aggregations or a dedicated stats table.
 */
function getStats() {
  const totalBooks = books.length;

  // Build genre counts by reducing the array into an accumulator object.
  const genres = books.reduce((acc, book) => {
    const genre = book.genre || 'Unknown'; // Treat null/undefined genre as 'Unknown'.
    acc[genre] = (acc[genre] || 0) + 1;   // Increment count for this genre.
    return acc;
  }, {});

  // Build author counts the same way.
  const authors = books.reduce((acc, book) => {
    const author = book.author || 'Unknown';
    acc[author] = (acc[author] || 0) + 1;
    return acc;
  }, {});

  // Compute average published year, handling the empty-case gracefully.
  let averagePublishedYear = null;
  if (totalBooks > 0) {
    const sumYears = books.reduce((sum, book) => sum + (book.publishedYear || 0), 0);
    averagePublishedYear = Math.round(sumYears / totalBooks);
  }

  // Find oldest and newest books by publishedYear.
  let oldestBook = null;
  let newestBook = null;
  if (totalBooks > 0) {
    oldestBook = books.reduce((oldest, book) =>
      (!oldest || (book.publishedYear !== null && book.publishedYear < oldest.publishedYear))
        ? book : oldest
    , null);

    newestBook = books.reduce((newest, book) =>
      (!newest || (book.publishedYear !== null && book.publishedYear > newest.publishedYear))
        ? book : newest
    , null);
  }

  return {
    totalBooks,
    genres,
    authors,
    averagePublishedYear,
    oldestBook,
    newestBook,
  };
}

// ─── Exports ──────────────────────────────────────────────────────────────────

module.exports = {
  getAllBooks,
  getBookById,
  createBook,
  updateBook,
  deleteBook,
  getStats,
};
```

**Key design decisions explained:**

| Decision | Rationale |
|---|---|
| In-memory array | No DB dependency; easy to understand and extend |
| `nextId` counter | Simple auto-increment; avoids client-side ID collisions |
| `filter()` for deletion | Functional style; returns new array reference |
| Spread operator for updates | Partial update support (PATCH semantics) without mutating original |
| On-demand stats computation | Trivial cost for in-memory data; no cache invalidation needed |

