/**
 * ============================================================================
 * ERROR HANDLING MIDDLEWARE
 * ============================================================================
 *
 * WHY a dedicated error-handling middleware?
 *   - Express provides a special 4-argument middleware signature (err, req, res, next)
 *     that catches errors from ANY route or middleware in the chain.
 *   - Centralizing error formatting here ensures ALL API responses have the same
 *     JSON structure, regardless of where the error originated.
 *   - This is the "single source of truth" for error response format.
 *
 * MIDDLEWARE ORDER MATTERS:
 *   - Error handlers MUST be placed AFTER all route definitions.
 *   - Express matches middleware in order; if an error handler were defined before
 *     a route, it would intercept requests prematurely.
 */

const { InternalServerError } = require('../errors/customErrors');

/**
 * Global error-handling middleware.
 * Catches all errors (thrown synchronously or passed to next(err)) and formats them.
 *
 * @param {Error} err - The error object caught by Express.
 * @param {import('express').Request} req - The HTTP request object.
 * @param {import('express').Response} res - The HTTP response object.
 * @param {import('express').NextFunction} next - Express next() function (unused here).
 *
 * RESPONSE FORMAT:
 *   All errors return JSON with this shape:
 *   {
 *     "success": false,
 *     "error": {
 *       "message": "Human-readable description",
 *       "statusCode": 404,
 *       "errorType": "NotFoundError"
 *     }
 *   }
 *
 * WHY always return success: false for errors?
 *   - Consistent API contract: every response has a top-level "success" flag.
 *   - Clients can check res.data.success before accessing res.data.data.
 */
function errorHandler(err, req, res, next) {
  // If the error is NOT our custom AppError, wrap it in InternalServerError.
  // This catches unexpected errors (e.g., TypeError from null reference).
  if (!(err instanceof require('../errors/customErrors').AppError)) {
    console.error('[UNCAUGHT ERROR]', err); // Log for debugging; don't expose stack to client.
    err = new InternalServerError('An unexpected error occurred. Please try again later.');
  }

  // Build the standardized error response object.
  const errorResponse = {
    success: false,
    error: {
      message: err.message,           // Human-readable message for the client.
      statusCode: err.statusCode,     // HTTP status code (400, 404, etc.).
      errorType: err.errorType,       // Class name for client-side error handling.
    },
  };

  // Log operational errors at WARN level; bugs at ERROR level.
  const logLevel = err.isOperational ? 'warn' : 'error';
  console.log(`[${logLevel.toUpperCase()}] ${err.errorType}: ${err.message}`);

  // Send the JSON response with the appropriate HTTP status code.
  res.status(err.statusCode).json(errorResponse);
}

/**
 * Validation middleware factory.
 * Validates required fields in the request body and throws BadRequestError if missing.
 *
 * @param {Array<string>} requiredFields - Array of field names that must be present.
 * @returns {Function} Express middleware function.
 *
 * WHY a factory pattern (function returning middleware)?
 *   - Allows reusing the same validation logic with different field sets.
 *   - Keeps route handlers clean by separating validation from business logic.
 *   - Example: validateRequired(['title', 'author']) vs validateRequired(['genre']).
 */
function validateRequired(requiredFields) {
  /**
   * @param {import('express').Request} req
   * @param {import('express').Response} res
   * @param {import('express').NextFunction} next
   */
  return (req, res, next) => {
    // Collect all missing fields.
    const missing = requiredFields.filter((field) => {
      const value = req.body[field];
      // Treat empty strings and whitespace-only as missing.
      return value === undefined || value === null || String(value).trim() === '';
    });

    if (missing.length > 0) {
      // Throw a structured error that the global handler will catch and format.
      throw new (require('../errors/customErrors').BadRequestError)(
        `Missing required fields: ${missing.join(', ')}`
      );
    }

    next(); // All validations passed; proceed to the route handler.
  };
}

/**
 * ID parameter validation middleware.
 * Ensures the :id URL parameter is a valid positive integer.
 *
 * @param {import('express').Request} req
 * @param {import('express').Response} res
 * @param {import('express').NextFunction} next
 */
function validateIdParam(req, res, next) {
  const id = parseInt(req.params.id, 10); // Parse as base-10 integer.

  if (isNaN(id) || id < 1 || !Number.isInteger(id)) {
    throw new (require('../errors/customErrors').BadRequestError)(
      `Invalid ID parameter: "${req.params.id}". Must be a positive integer.`
    );
  }

  // Replace the string param with a parsed number for downstream use.
  req.params.id = id;
  next();
}

module.exports = {
  errorHandler,
  validateRequired,
  validateIdParam,
};
```

**Why this middleware architecture?**

1. **`errorHandler`** is a single catch-all that ensures every error gets the same JSON shape. Without it, unhandled errors would return Express's default HTML error page — terrible for API consumers.

2. **`validateRequired`** factory lets us reuse validation logic across POST and PUT handlers without duplicating code.

3. **`validateIdParam`** prevents `NaN` or string IDs from reaching the model layer, where they'd cause silent failures or type coercion bugs.

