const bookRoutes = require('./routes/books');
const statsRoutes = require('./routes/stats');
const { errorHandler } = require('./middleware/errorHandler');

// ─── Application Setup ────────────────────────────────────────────────────────

/**
 * Create and configure the Express application instance.
 * This is where we wire together middleware, routes, and error handling.
 */
function createApp() {
  const app = express(); // Create a new Express application.

  // ── Body Parsing Middleware ────────────────────────────────────────────────
  // express.json() parses incoming JSON payloads and populates req.body.
  // limit: '10kb' prevents abuse by rejecting excessively large payloads.
  app.use(express.json({ limit: '10kb' }));

  // express.urlencoded() parses URL-encoded form data (application/x-www-form-urlencoded).
  // extended: true allows rich objects and arrays (uses qs library).
  app.use(express.urlencoded({ extended: true, limit: '10kb' }));

  // ── Request Logging Middleware ─────────────────────────────────────────────
  // Simple request logger for development — logs method, path, and status code.
  // In production, you'd use a proper logging library (winston, pino).
  app.use((req, res, next) => {
    const start = Date.now(); // Capture start time for response duration calculation.
    // Hook into res.end() to log after the response is sent.
    res.on('finish', () => {
      const duration = Date.now() - start;
      console.log(
        `[${new Date().toISOString()}] ${req.method} ${req.originalUrl} ` +
        `→ ${res.statusCode} (${duration}ms)`
      );
    });
    next(); // Continue to the next middleware/route.
  });

  // ── Health Check Endpoint ──────────────────────────────────────────────────
  // Simple endpoint to verify the server is running (used by load balancers, etc.).
  app.get('/health', (req, res) => {
    res.json({ status: 'ok', timestamp: new Date().toISOString() });
  });

  // ── Route Registration ─────────────────────────────────────────────────────
  // Mount route modules at their respective paths.
  // All book CRUD operations are under /books.
  app.use('/books', bookRoutes);

  // Stats endpoint is separate to keep concerns isolated.
  app.use('/stats', statsRoutes);

  // ── 404 Handler for Undefined Routes ───────────────────────────────────────
  // If no route matches, return a structured 404 response instead of Express's default.
  app.use((req, res, next) => {
    const { NotFoundError } = require('./errors/customErrors');
    throw new NotFoundError(`Route ${req.method} ${req.originalUrl} not found`);
  });

  // ── Global Error Handler ───────────────────────────────────────────────────
  // MUST be the last middleware. Catches all errors from routes and above.
  // Express identifies this by its 4-argument signature (err, req, res, next).
  app.use(errorHandler);

  return app;
}

// Export the factory function so server.js can require it.
module.exports = createApp;
```

**Middleware order explained:**

```
Request arrives
    │
    ▼
express.json()          ← Parse JSON body into req.body
    │
    ▼
express.urlencoded()    ← Parse form data into req.body
    │
    ▼
Logging middleware      ← Log request details (non-blocking)
    │
    ▼
Route handlers          ← Business logic, model calls, validation
    │
    ▼
404 handler             ← Catch unmatched routes
    │
    ▼
errorHandler            ← Format and send error responses
```

