/**
 * ============================================================================
 * SERVER STARTUP
 * ============================================================================
 *
 * WHY a separate server.js file?
 *   - Keeps HTTP server lifecycle separate from Express app configuration.
 *   - Enables graceful shutdown handling (important for production).
 *   - Allows the app to be tested without starting an HTTP server.
 */

const createApp = require('./app');

// Determine port: use PORT env var, fall back to 3000.
// This allows different environments (dev, test, prod) to use different ports.
const PORT = process.env.PORT || 3000;

// Create the Express application.
const app = createApp();

/**
 * Start the HTTP server and listen on the configured port.
 */
const server = app.listen(PORT, () => {
  console.log(`========================================`);
  console.log(`  Book REST API running on port ${PORT}`);
  console.log(`  Environment: ${process.env.NODE_ENV || 'development'}`);
  console.log(`  Base URL: http://localhost:${PORT}`);
  console.log(`========================================`);
  console.log(`\nQuick test:`);
  console.log(`  curl http://localhost:${PORT}/books`);
  console.log(`  curl http://localhost:${PORT}/stats`);
});

/**
 * Graceful shutdown handler.
 * Catches SIGINT (Ctrl+C) and SIGTERM (kill signal) to close the server cleanly.
 * This ensures in-flight requests complete before the process exits.
 */
function gracefulShutdown(signal) {
  console.log(`\n${signal} received. Shutting down gracefully...`);
  server.close(() => {
    console.log('HTTP server closed.');
    process.exit(0);
  });

  // Force exit after 10 seconds if connections are still open.
  setTimeout(() => {
    console.error('Could not close connections in time. Forcing exit.');
    process.exit(1);
  }, 10000);
}

process.on('SIGINT', gracefulShutdown);
process.on('SIGTERM', gracefulShutdown);

module.exports = server;
