## Arquivo 2: `src/middleware/errorHandler.js`

```javascript
/**
 * ============================================================
 *  MIDDLEWARE DE TRATAMENTO DE ERROS
 * ============================================================
 *
 * POR QUE UM ARQUIVO SEPARADO?
 * ----------------------------
 * Separar o middleware de erro do app principal mantém o código
 * organizado e reutilizável. Em projetos maiores, poderíamos ter
 * múltiplos middlewares de validação antes deste.
 *
 * PADRÃO DO MIDDLEWARE DE ERRO NO EXPRESS:
 * -----------------------------------------
 * Middleware de erro no Express tem 4 parâmetros obrigatórios:
 *   (err, req, res, next)
 * O quarto parâmetro "next" é essencial — sem ele, o Express não
 * reconhece a função como middleware de erro. Os três primeiros
 * representam a requisição, resposta e o objeto de erro capturado.
 *
 * CLASSE DE ERRO PERSONALIZADA:
 * ------------------------------
 * Criamos uma classe ValidationError que estende Error para
 * diferenciar erros de validação (400) de outros tipos de erro.
 * Isso permite tratar cada tipo com código HTTP adequado.
 */

// ============================================================
//  CLASSE DE ERRO PERSONALIZADA: NotFoundError
// ============================================================
/**
 * Erro lançado quando um recurso solicitado não é encontrado.
 * Exemplo: GET /books/999 onde o ID 999 não existe.
 *
 * @extends Error
 */
class NotFoundError extends Error {
  /**
   * Construtor do NotFoundError.
   *
   * @param {string} message - Mensagem descritiva do erro.
   * @param {*} resource - Nome do recurso afetado (ex: "Book").
   * @param {*} id - ID do recurso que não foi encontrado.
   */
  constructor(message, resource, id) {
    super(message); // Chama o construtor da classe Error pai
    this.name = 'NotFoundError'; // Nome da classe para identificação
    this.statusCode = 404;       // Código HTTP: Not Found
    this.resource = resource;    // Ex: "Book"
    this.id = id;                // Ex: 1
  }
}

// ============================================================
//  CLASSE DE ERRO PERSONALIZADA: ValidationError
// ============================================================
/**
 * Erro lançado quando os dados enviados pelo cliente não passam
 * nas validações. Exemplo: título vazio, preço negativo.
 *
 * @extends Error
 */
class ValidationError extends Error {
  /**
   * Construtor do ValidationError.
   *
   * @param {string} message - Mensagem descritiva do erro.
   * @param {Array<Object>} details - Array de detalhes da validação.
   *    Cada objeto tem: { field, message }
   */
  constructor(message, details = []) {
    super(message);
    this.name = 'ValidationError';
    this.statusCode = 400;       // Código HTTP: Bad Request
    this.details = details;      // Detalhes específicos de cada campo
  }
}

// ============================================================
//  CLASSE DE ERRO PERSONALIZADA: InternalError
// ============================================================
/**
 * Erro lançado para erros inesperados do servidor.
 * Usado como fallback quando nenhum outro tipo de erro se aplica.
 *
 * @extends Error
 */
class InternalError extends Error {
  /**
   * Construtor do InternalError.
   *
   * @param {string} message - Mensagem descritiva do erro.
   */
  constructor(message = 'Erro interno no servidor') {
    super(message);
    this.name = 'InternalError';
    this.statusCode = 500;       // Código HTTP: Internal Server Error
  }
}

// ============================================================
//  FUNÇÃO: validateBookData
// ============================================================
/**
 * Valida os dados de um livro antes de criar ou atualizar.
 *
 * POR QUE VALIDAR AQUI E NÃO NO SERVIÇO?
 * ----------------------------------------
 * Colocar a validação no middleware mantém o serviço limpo e
 * focado apenas na lógica de negócio. O middleware é a camada
 * ideal para verificar integridade dos dados de entrada.
 *
 * @param {Object} data - Dados do livro a serem validados.
 * @returns {Array<Object>} Array de erros de validação (vazio se válido).
 */
function validateBookData(data) {
  const errors = [];

  // Verifica se o título foi fornecido e não é apenas espaços em branco
  if (!data.title || data.title.trim() === '') {
    errors.push({ field: 'title', message: 'O título é obrigatório' });
  }

  // Verifica se o autor foi fornecido e não é apenas espaços em branco
  if (!data.author || data.author.trim() === '') {
    errors.push({ field: 'author', message: 'O autor é obrigatório' });
  }

  // Verifica se o preço é um número válido e positivo
  if (data.price === undefined || data.price === null) {
    errors.push({ field: 'price', message: 'O preço é obrigatório' });
  } else if (typeof data.price !== 'number' || data.price < 0) {
    errors.push({ field: 'price', message: 'O preço deve ser um número positivo' });
  }

  // Verifica se o ano, se fornecido, é um número válido
  if (data.year !== undefined && data.year !== null) {
    if (!Number.isInteger(data.year) || data.year < 0 || data.year > new Date().getFullYear() + 1) {
      errors.push({ field: 'year', message: 'O ano deve ser um número inteiro válido' });
    }
  }

  return errors;
}

// ============================================================
//  MIDDLEWARE PRINCIPAL: errorHandler
// ============================================================
/**
 * Middleware central de tratamento de erros do Express.
 *
 * POR QUE COLOCAR DEPOIS DE TODAS AS ROTAS?
 * -------------------------------------------
 * No Express, middlewares são executados na ordem em que são
 * definidos. Colocamos este middleware APÓS todas as rotas para
 * que ele capture apenas erros não tratados pelas rotas.
 * Se colocássemos antes, interceptaria tudo e as rotas nunca
 * veriam seus próprios erros.
 *
 * PADRÃO async/await COM CATCH:
 * ------------------------------
 * Usamos try/catch em cada rota para capturar erros síncronos
 * e assíncronos de forma uniforme. Quando um erro é capturado,
 * chamamos next(err) para encadeá-lo a este middleware.
 *
 * @param {Error} err - Objeto de erro capturado.
 * @param {Object} req - Objeto de requisição do Express.
 * @param {Object} res - Objeto de resposta do Express.
 * @param {Function} next - Função para encadear ao próximo middleware.
 */
function errorHandler(err, req, res, next) {
  // Define o código de status com base no tipo de erro
  const statusCode = err.statusCode || 500;

  // Monta a resposta de erro de forma consistente
  const errorResponse = {
    success: false,           // Indica que a operação falhou
    error: {
      name: err.name,         // Nome da classe do erro (ex: NotFoundError)
      message: err.message,   // Mensagem legível para o cliente
    }
  };

  // Adiciona detalhes de validação se disponíveis
  if (err.details && Array.isArray(err.details)) {
    errorResponse.error.details = err.details;
  }

  // Em desenvolvimento, logamos o erro completo no console
  // Para segurança, em produção não expomos stack traces
  if (process.env.NODE_ENV !== 'production') {
    console.error(`[${err.name}] ${err.message}`);
    console.error(err.stack);
  }

  // Envia a resposta JSON com o código de status apropriado
  res.status(statusCode).json(errorResponse);
}

// ============================================================
//  EXPORTAÇÕES
// ============================================================
module.exports = {
  NotFoundError,
  ValidationError,
  InternalError,
  validateBookData,
  errorHandler
};
```

