## Arquivo 3: `src/services/bookService.js`

```javascript
/**
 * ============================================================
 *  SERVIÇO DE LIVROS — Lógica de Negócio
 * ============================================================
 *
 * POR QUE UMA CAMADA DE SERVIÇO?
 * --------------------------------
 * Separar a lógica de negócio das rotas permite:
 *   1. Reutilizar a lógica em diferentes contextos (API, CLI, testes)
 *   2. Manter as rotas limpas e focadas apenas em HTTP
 *   3. Facilitar testes unitários isolando a lógica de negócio
 *
 * ESTRUTURA DE DADOS — POR QUE ARRAY?
 * -------------------------------------
 * Usamos um array em memória porque:
 *   - É simples e fácil de entender para fins educacionais
 *   - Permite iterar rapidamente sobre todos os livros
 *   - Para uma API real, substituiríamos por um banco de dados
 *     (MongoDB, PostgreSQL, etc.) mantendo a mesma interface
 *
 * POR QUE CADA LIVRO TEM PROPRIEDADES ESPECÍFICAS?
 * -------------------------------------------------
 *   - id: identificador único gerado automaticamente (auto-incremento)
 *   - title: título do livro (obrigatório, string)
 *   - author: autor do livro (obrigatório, string)
 *   - price: preço em reais/dólares (obrigatório, número >= 0)
 *   - year: ano de publicação (opcional, número inteiro)
 *   - createdAt / updatedAt: timestamps para auditoria
 */

// ============================================================
//  BANCO DE DADOS EM MEMÓRIA
// ============================================================

/**
 * Array que armazena todos os livros.
 *
 * Escolha: array em vez de objeto/map porque:
 *   - A ordem de inserção é preservada (importante para listagem)
 *   - Operações de filtro e iteração são mais naturais com arrays
 *   - Em produção, este seria substituído por uma consulta SQL/NoSQL
 */
const books = [];

/**
 * Contador para gerar IDs únicos.
 *
 * Usamos um contador simples em vez de UUIDs porque:
 *   - É mais legível e previsível para fins educacionais
 *   - Evita colisões sem necessidade de bibliotecas externas
 *   - Em produção, usaríamos o ID do banco de dados
 */
let nextId = 1;

// ============================================================
//  FUNÇÃO: getAllBooks
// ============================================================
/**
 * Retorna todos os livros com filtragem opcional.
 *
 * PARÂMETROS DE FILTRAGEM:
 * -------------------------
 *   - title: filtra por substring no título (case-insensitive)
 *   - author: filtra por substring no autor (case-insensitive)
 *   - minPrice / maxPrice: faixa de preço
 *   - year: ano exato de publicação
 *
 * POR QUE USAR FILTER() EM VEZ DE FOR?
 * --------------------------------------
 * Array.prototype.filter() é mais declarativo e encadeável.
 * Ele retorna um novo array sem mutar o original, seguindo
 * princípios de programação funcional.
 *
 * @param {Object} filters - Objetos de filtragem opcionais.
 * @returns {Array<Object>} Lista de livros filtrados.
 */
function getAllBooks(filters = {}) {
  let result = [...books]; // Cria cópia para não mutar o array original

  // Filtra por título (substring, case-insensitive)
  if (filters.title) {
    const searchTerm = filters.title.toLowerCase();
    result = result.filter(book =>
      book.title.toLowerCase().includes(searchTerm)
    );
  }

  // Filtra por autor (substring, case-insensitive)
  if (filters.author) {
    const searchTerm = filters.author.toLowerCase();
    result = result.filter(book =>
      book.author.toLowerCase().includes(searchTerm)
    );
  }

  // Filtra por faixa de preço mínima
  if (filters.minPrice !== undefined) {
    result = result.filter(book => book.price >= Number(filters.minPrice));
  }

  // Filtra por faixa de preço máxima
  if (filters.maxPrice !== undefined) {
    result = result.filter(book => book.price <= Number(filters.maxPrice));
  }

  // Filtra por ano exato
  if (filters.year !== undefined) {
    result = result.filter(book => book.year === Number(filters.year));
  }

  return result;
}

// ============================================================
//  FUNÇÃO: getBookById
// ============================================================
/**
 * Busca um livro pelo ID.
 *
 * POR QUE USAR find() EM VEZ DE findIndex()?
 * --------------------------------------------
 * Array.prototype.find() retorna o objeto diretamente,
 * enquanto findIndex() retornaria apenas o índice, exigindo
 * uma segunda operação para acessar o elemento.
 *
 * @param {number} id - ID do livro a ser buscado.
 * @returns {Object|null} Livro encontrado ou null se não existir.
 */
function getBookById(id) {
  return books.find(book => book.id === Number(id)) || null;
}

// ============================================================
//  FUNÇÃO: createBook
// ============================================================
/**
 * Cria um novo livro e o adiciona ao array.
 *
 * POR QUE USAR SPREAD (...) PARA CLONAR?
 * ----------------------------------------
 * Usamos { ...data } para criar uma cópia rasa dos dados
 * enviados pelo cliente, evitando mutações acidentais no
 * objeto original da requisição. Isso é importante porque
 * o Express pode reutilizar objetos de request em certas
 * configurações.
 *
 * @param {Object} data - Dados do novo livro.
 * @returns {Object} Livro criado com ID e timestamps.
 */
function createBook(data) {
  const now = new Date().toISOString(); // Timestamp ISO 8601 para consistência

  const newBook = {
    id: nextId++,                    // ID auto-incremento, depois incrementa
    title: data.title,
    author: data.author,
    price: Number(data.price),       // Garante que preço é número
    year: data.year ? Number(data.year) : null, // Ano opcional
    createdAt: now,                  // Timestamp de criação
    updatedAt: now                   // Timestamp de atualização (mesmo valor inicial)
  };

  books.push(newBook); // Adiciona ao final do array
  return newBook;
}

// ============================================================
//  FUNÇÃO: updateBook
// ============================================================
/**
 * Atualiza um livro existente pelo ID.
 *
 * POR QUE USAR SPREAD NO RETORNO?
 * ---------------------------------
 * O spread operator { ...book, ...updates } cria um novo objeto
 * mesclando o livro original com as atualizações. Isso garante
 * que campos não mencionados na atualização sejam preservados
 * (atualização parcial / PATCH-like).
 *
 * @param {number} id - ID do livro a ser atualizado.
 * @param {Object} updates - Campos a serem atualizados.
 * @returns {Object|null} Livro atualizado ou null se não encontrado.
 */
function updateBook(id, updates) {
  const index = books.findIndex(book => book.id === Number(id));

  if (index === -1) {
    return null; // Livro não encontrado
  }

  // Cria o livro atualizado preservando campos não mencionados
  const updatedBook = {
    ...books[index],              // Copia todos os campos existentes
    ...updates,                   // Sobrescreve com novos valores
    id: books[index].id,          // Garante que ID não seja alterado
    createdAt: books[index].createdAt, // Garante que createdAt não mude
    updatedAt: new Date().toISOString() // Atualiza timestamp de modificação
  };

  books[index] = updatedBook; // Substitui no array
  return updatedBook;
}

// ============================================================
//  FUNÇÃO: deleteBook
// ============================================================
/**
 * Exclui um livro pelo ID.
 *
 * POR QUE USAR splice() EM VEZ DE filter()?
 * -------------------------------------------
 * splice() modifica o array original in-place, o que é mais
 * eficiente para remoções únicas (O(n) vs O(n) com cópia).
 * Para arrays pequenos como este, a diferença é insignificante,
 * mas splice() é semanticamente mais claro para "remover".
 *
 * @param {number} id - ID do livro a ser excluído.
 * @returns {boolean} true se excluído, false se não encontrado.
 */
function deleteBook(id) {
  const index = books.findIndex(book => book.id === Number(id));

  if (index === -1) {
    return false; // Livro não encontrado
  }

  books.splice(index, 1); // Remove 1 elemento na posição encontrada
  return true;
}

// ============================================================
//  FUNÇÃO: getStats
// ============================================================
/**
 * Retorna estatísticas agregadas sobre os livros.
 *
 * POR QUE USAR REDUCE() PARA CÁLCULOS AGREGADOS?
 * ------------------------------------------------
 * Array.prototype.reduce() é a ferramenta ideal para calcular
 * valores agregados (soma, média, contagem) percorrendo o array
 * uma única vez. É mais eficiente que múltiplos loops separados.
 *
 * @returns {Object} Estatísticas dos livros.
 */
function getStats() {
  if (books.length === 0) {
    // Retorna zeros quando não há livros para evitar divisão por zero
    return {
      total: 0,
      averagePrice: 0,
      minPrice: 0,
      maxPrice: 0,
      totalValue: 0,
      booksByYear: {},
      booksByAuthor: {}
    };
  }

  // Calcula soma e média de preços em uma única passagem
  const { sum, count } = books.reduce(
    (acc, book) => ({
      sum: acc.sum + book.price,
      count: acc.count + 1
    }),
    { sum: 0, count: 0 }
  );

  // Encontra preço mínimo e máximo
  const prices = books.map(book => book.price);
  const minPrice = Math.min(...prices);
  const maxPrice = Math.max(...prices);

  // Conta livros por ano de publicação
  const booksByYear = books.reduce((acc, book) => {
    const year = book.year ? String(book.year) : 'unknown';
    acc[year] = (acc[year] || 0) + 1;
    return acc;
  }, {});

  // Conta livros por autor
  const booksByAuthor = books.reduce((acc, book) => {
    acc[book.author] = (acc[book.author] || 0) + 1;
    return acc;
  }, {});

  return {
    total: count,
    averagePrice: parseFloat((sum / count).toFixed(2)), // Arredonda para 2 casas decimais
    minPrice,
    maxPrice,
    totalValue: parseFloat(sum.toFixed(2)),
    booksByYear,
    booksByAuthor
  };
}

// ============================================================
//  EXPORTAÇÕES
// ============================================================
module.exports = {
  getAllBooks,
  getBookById,
  createBook,
  updateBook,
  deleteBook,
  getStats
};
