/**
 * ============================================================
 *  ROTAS DA API DE LIVROS
 * ============================================================
 *
 * POR QUE ARQUIVO DE ROTAS SEPARADO?
 * ------------------------------------
 * Separar rotas do app principal permite:
 *   1. Manter o arquivo app.js limpo e focado na configuração
 *   2. Organizar endpoints por domínio (livros, usuários, etc.)
 *   3. Facilitar testes de integração isolando as rotas
 *   4. Escalar para múltiplos arquivos de rota em projetos maiores
 *
 * CONVENÇÕES REST ADOTADAS:
 * ---------------------------
 *   - GET    /books       → Listar todos (com filtragem via query params)
 *   - GET    /books/:id    → Obter um específico
 *   - POST   /books        → Criar novo
 *   - PUT    /books/:id    → Atualizar completo (substituição)
 *   - DELETE /books/:id    → Excluir
 *   - GET    /stats        → Estatísticas agregadas
 *
 * PADRÃO async/await:
 * --------------------
 * Usamos async/await em vez de promessas .then() porque:
 *   - Código mais legível e linear (sem callback hell)
 *   - Tratamento de erros mais claro com try/catch
 *   - Padrão moderno do ecossistema Node.js
 *
 * EXEMPLOS DE SOLICITAÇÕES CURL:
 * --------------------------------
 *
 * # Listar todos os livros
 * curl http://localhost:3000/books
 *
 * # Filtrar por título
 * curl "http://localhost:3000/books?title=javascript"
 *
 * # Filtrar por autor e faixa de preço
 * curl "http://localhost:3000/books?author=knuth&minPrice=50&maxPrice=100"
 *
 * # Obter livro por ID
 * curl http://localhost:3000/books/1
 *
 * # Criar novo livro
 * curl -X POST http://localhost:3000/books \
 *   -H "Content-Type: application/json" \
 *   -d '{"title":"The Art of Computer Programming","author":"Donald Knuth","price":299.90,"year":1968}'
 *
 * # Atualizar livro (PUT = substituição completa)
 * curl -X PUT http://localhost:3000/books/1 \
 *   -H "Content-Type: application/json" \
 *   -d '{"title":"The Art of Computer Programming, 4th Ed","author":"Donald Knuth","price":399.90,"year":2011}'
 *
 * # Excluir livro
 * curl -X DELETE http://localhost:3000/books/1
 *
 * # Obter estatísticas
 * curl http://localhost:3000/stats
 */

const express = require('express');
const router = express.Router(); // Cria um roteador Express independente

// Importa o serviço de livros (lógica de negócio)
const {
  getAllBooks,
  getBookById,
  createBook,
  updateBook,
  deleteBook,
  getStats
} = require('../services/bookService');

// Importa classes de erro e validação do middleware
const { NotFoundError, ValidationError } = require('../middleware/errorHandler');

// ============================================================
//  GET /books — Listar todos os livros com filtragem
// ============================================================
/**
 * Endpoint: GET /books
 *
 * QUERY PARAMS OPCIONAIS:
 *   - title      : filtra por substring no título
 *   - author     : filtra por substring no autor
 *   - minPrice   : preço mínimo (número)
 *   - maxPrice   : preço máximo (número)
 *   - year       : ano exato de publicação
 *
 * RESPOSTA DE SUCESSO (200 OK):
 * {
 *   "success": true,
 *   "data": [
 *     {
 *       "id": 1,
 *       "title": "Clean Code",
 *       "author": "Robert C. Martin",
 *       "price": 89.90,
 *       "year": 2008,
 *       "createdAt": "2024-01-15T10:30:00.000Z",
 *       "updatedAt": "2024-01-15T10:30:00.000Z"
 *     }
 *   ],
 *   "count": 1
 * }
 *
 * EXEMPLO CURL:
 *   curl "http://localhost:3000/books?title=clean&minPrice=50"
 */
router.get('/books', (req, res) => {
  try {
    // Extrai parâmetros de query da URL (ex: ?title=javascript)
    const filters = {
      title: req.query.title,
      author: req.query.author,
      minPrice: req.query.minPrice,
      maxPrice: req.query.maxPrice,
      year: req.query.year
    };

    // Chama o serviço para obter livros filtrados
    const books = getAllBooks(filters);

    // Resposta padronizada com metadados de paginação
    res.json({
      success: true,
      data: books,
      count: books.length  // Total de livros retornados (útil para paginação futura)
    });
  } catch (error) {
    // Encadeia o erro ao middleware de tratamento de erros
    next(error);
  }
});

// ============================================================
//  GET /books/:id — Obter livro por ID
// ============================================================
/**
 * Endpoint: GET /books/:id
 *
 * PARÂMETRO DE ROTA:
 *   - id : identificador numérico do livro
 *
 * RESPOSTA DE SUCESSO (200 OK):
 * {
 *   "success": true,
 *   "data": {
 *     "id": 1,
 *     "title": "Clean Code",
 *     "author": "Robert C. Martin",
 *     "price": 89.90,
 *     "year": 2008,
 *     "createdAt": "2024-01-15T10:30:00.000Z",
 *     "updatedAt": "2024-01-15T10:30:00.000Z"
 *   }
 * }
 *
 * RESPOSTA DE ERRO (404 Not Found):
 * {
 *   "success": false,
 *   "error": {
 *     "name": "NotFoundError",
 *     "message": "Livro não encontrado com ID: 999"
 *   }
 * }
 *
 * EXEMPLO CURL:
 *   curl http://localhost:3000/books/1
 */
router.get('/books/:id', (req, res) => {
  try {
    // Converte o ID de string (vem da URL) para número
    const id = Number(req.params.id);

    // Busca o livro no serviço
    const book = getBookById(id);

    // Se não encontrado, lança NotFoundError personalizado
    if (!book) {
      throw new NotFoundError(
        `Livro não encontrado com ID: ${id}`,
        'Book',
        id
      );
    }

    res.json({ success: true, data: book });
  } catch (error) {
    next(error); // Encadeia ao middleware de erro
  }
});

// ============================================================
//  POST /books — Criar novo livro
// ============================================================
/**
 * Endpoint: POST /books
 *
 * CORPO DA REQUISIÇÃO (JSON):
 * {
 *   "title": "Clean Code",
 *   "author": "Robert C. Martin",
 *   "price": 89.90,
 *   "year": 2008
 * }
 *
 * Campos obrigatórios: title, author, price
 * Campo opcional: year
 *
 * RESPOSTA DE SUCESSO (201 Created):
 * {
 *   "success": true,
 *   "data": {
 *     "id": 1,
 *     "title": "Clean Code",
 *     ...
 *   }
 * }
 *
 * RESPOSTA DE ERRO (400 Bad Request):
 * {
 *   "success": false,
 *   "error": {
 *     "name": "ValidationError",
 *     "message": "Dados inválidos para criação do livro",
 *     "details": [
 *       { "field": "title", "message": "O título é obrigatório" }
 *     ]
 *   }
 * }
 *
 * EXEMPLO CURL:
 *   curl -X POST http://localhost:3000/books \
 *     -H "Content-Type: application/json" \
 *     -d '{"title":"The Pragmatic Programmer","author":"David Thomas","price":79.90,"year":1999}'
 */
router.post('/books', (req, res) => {
  try {
    // Extrai os dados do corpo da requisição
    const { title, author, price, year } = req.body;

    // Valida os dados antes de processar
    // A validação é feita aqui para dar feedback imediato ao cliente
    if (!title || !author || price === undefined) {
      throw new ValidationError(
        'Dados inválidos para criação do livro',
        [
          !title ? { field: 'title', message: 'O título é obrigatório' } : null,
          !author ? { field: 'author', message: 'O autor é obrigatório' } : null,
          price === undefined ? { field: 'price', message: 'O preço é obrigatório' } : null
        ].filter(Boolean) // Remove entries nulas
      );
    }

    // Cria o livro no serviço
    const newBook = createBook({ title, author, price, year });

    // 201 Created indica que um novo recurso foi criado com sucesso
    res.status(201).json({ success: true, data: newBook });
  } catch (error) {
    next(error);
  }
});

// ============================================================
//  PUT /books/:id — Atualizar livro existente
// ============================================================
/**
 * Endpoint: PUT /books/:id
 *
 * CORPO DA REQUISIÇÃO (JSON):
 * {
 *   "title": "Clean Code, 10th Anniversary Edition",
 *   "author": "Robert C. Martin",
 *   "price": 99.90,
 *   "year": 2018
 * }
 *
 * NOTA: PUT implica SUBSTITUIÇÃO COMPLETA. Todos os campos
 * obrigatórios devem ser enviados. Para atualização parcial,
 * o ideal seria usar PATCH (não implementado neste exemplo).
 *
 * RESPOSTA DE SUCESSO (200 OK):
 * {
 *   "success": true,
 *   "data": { ...livro atualizado... }
 * }
 *
 * EXEMPLO CURL:
 *   curl -X PUT http://localhost:3000/books/1 \
 *     -H "Content-Type: application/json" \
 *     -d '{"title":"Clean Code, 10th Anniversary Edition","author":"Robert C. Martin","price":99.90,"year":2018}'
 */
router.put('/books/:id', (req, res) => {
  try {
    const id = Number(req.params.id);
    const updates = req.body;

    // Valida os dados de atualização
    if (!updates.title || !updates.author || updates.price === undefined) {
      throw new ValidationError(
        'Dados inválidos para atualização do livro',
        [
          !updates.title ? { field: 'title', message: 'O título é obrigatório' } : null,
          !updates.author ? { field: 'author', message: 'O autor é obrigatório' } : null,
          updates.price === undefined ? { field: 'price', message: 'O preço é obrigatório' } : null
        ].filter(Boolean)
      );
    }

    // Atualiza o livro no serviço
    const updatedBook = updateBook(id, updates);

    // Se não encontrado, lança NotFoundError
    if (!updatedBook) {
      throw new NotFoundError(
        `Livro não encontrado com ID: ${id}`,
        'Book',
        id
      );
    }

    res.json({ success: true, data: updatedBook });
  } catch (error) {
    next(error);
  }
});

// ============================================================
//  DELETE /books/:id — Excluir livro
// ============================================================
/**
 * Endpoint: DELETE /books/:id
 *
 * RESPOSTA DE SUCESSO (200 OK):
 * {
 *   "success": true,
 *   "message": "Livro excluído com sucesso",
 *   "data": { ...livro excluído... }
 * }
 *
 * RESPOSTA DE ERRO (404 Not Found):
 * {
 *   "success": false,
 *   "error": {
 *     "name": "NotFoundError",
 *     "message": "Livro não encontrado com ID: 999"
 *   }
 * }
 *
 * EXEMPLO CURL:
 *   curl -X DELETE http://localhost:3000/books/1
 */
router.delete('/books/:id', (req, res) => {
  try {
    const id = Number(req.params.id);

    // Primeiro, busca o livro para retorná-lo na resposta
    const book = getBookById(id);

    if (!book) {
      throw new NotFoundError(
        `Livro não encontrado com ID: ${id}`,
        'Book',
        id
      );
    }

    // Exclui o livro no serviço
    deleteBook(id);

    // 200 OK com o livro excluído retornado (boa prática para confirmação)
    res.json({
      success: true,
      message: 'Livro excluído com sucesso',
      data: book
    });
  } catch (error) {
    next(error);
  }
});

// ============================================================
//  GET /stats — Estatísticas dos livros
// ============================================================
/**
 * Endpoint: GET /stats
 *
 * RESPOSTA DE SUCESSO (200 OK):
 * {
 *   "success": true,
 *   "data": {
 *     "total": 5,
 *     "averagePrice": 149.98,
 *     "minPrice": 29.90,
 *     "maxPrice": 399.90,
 *     "totalValue": 749.90,
 *     "booksByYear": { "2008": 2, "1968": 1 },
 *     "booksByAuthor": { "Robert C. Martin": 2, "Donald Knuth": 1 }
 *   }
 * }
 *
 * EXEMPLO CURL:
 *   curl http://localhost:3000/stats
 */
router.get('/stats', (req, res) => {
  try {
    const stats = getStats();
    res.json({ success: true, data: stats });
  } catch (error) {
    next(error);
  }
});

// ============================================================
//  EXPORTAÇÕES
// ============================================================
module.exports = router;
