/**
 * ============================================================
 *  APP PRINCIPAL — Configuração do Servidor Express
 * ============================================================
 *
 * POR QUE CONFIGURAR MIDDLEWARE ANTES DAS ROTAS?
 * -----------------------------------------------
 * O Express executa middlewares na ordem em que são definidos.
 * Precisamos de:
 *   1. body-parser (express.json()) antes das rotas para
 *      parsear o corpo JSON das requisições POST/PUT
 *   2. middleware de erro DEPOIS de todas as rotas para
 *      capturar erros não tratados
 *
 * POR QUE USAR express.json()?
 * -----------------------------
 * Sem este middleware, req.body seria undefined porque o Express
 * não parseia automaticamente JSON. Este middleware extrai o corpo
 * da requisição e o disponibiliza como objeto em req.body.
 *
 * PADRÃO DE RESPOSTA CONSISTENTE:
 * ---------------------------------
 * Todas as respostas seguem o formato:
 *   { success: boolean, data?: any, error?: object }
 * Isso facilita o consumo da API por clientes frontend/mobile.
 */

const express = require('express');
const app = express(); // Cria a aplicação Express
const PORT = process.env.PORT || 3000; // Porta configurável via variável de ambiente

// ============================================================
//  MIDDLEWARES GLOBAIS
// ============================================================

/**
 * Middleware: express.json()
 * Parseia o corpo de requisições com Content-Type: application/json.
 * Sem isso, req.body seria undefined em POST/PUT.
 */
app.use(express.json());

/**
 * Middleware: Logger simples de requisições.
 * Loga método, URL e timestamp de cada requisição.
 * Útil para debugging e monitoramento básico.
 */
app.use((req, res, next) => {
  console.log(`[${new Date().toISOString()}] ${req.method} ${req.url}`);
  next(); // Passa para o próximo middleware/rota
});

// ============================================================
//  ROTAS DA API
// ============================================================

/**
 * Importa o roteador de livros.
 * Todas as rotas ficam sob o prefixo /api (boa prática REST).
 * O prefixo /api permite versionamento futuro: /api/v1/, /api/v2/
 */
const bookRoutes = require('./routes/books');
app.use('/api', bookRoutes);

// ============================================================
//  ROTA RAIZ — Documentação da API
// ============================================================
/**
 * Endpoint: GET /
 * Retorna informações básicas sobre a API.
 * Útil para verificar se o servidor está no ar.
 */
app.get('/', (req, res) => {
  res.json({
    success: true,
    message: 'API de Livros — Servidor rodando!',
    endpoints: {
      documentation: 'GET /',
      listBooks: 'GET /api/books',
      getBook: 'GET /api/books/:id',
      createBook: 'POST /api/books',
      updateBook: 'PUT /api/books/:id',
      deleteBook: 'DELETE /api/books/:id',
      stats: 'GET /api/stats'
    }
  });
});

// ============================================================
//  ROTA 404 — Tratamento de rotas inexistentes
// ============================================================
/**
 * Middleware: Captura todas as requisições para rotas não definidas.
 * Deve vir DEPOIS de todas as rotas e ANTES do middleware de erro.
 */
app.use((req, res) => {
  res.status(404).json({
    success: false,
    error: {
      name: 'NotFoundError',
      message: `Rota não encontrada: ${req.method} ${req.url}`
    }
  });
});

// ============================================================
//  MIDDLEWARE DE TRATAMENTO DE ERROS
// ============================================================
/**
 * Middleware de erro deve ter EXATAMENTE 4 parâmetros.
 * Express o reconhece automaticamente quando detecta este padrão.
 * Deve ser o ÚLTIMO middleware registrado.
 */
const { errorHandler } = require('./middleware/errorHandler');
app.use(errorHandler);

// ============================================================
//  INICIALIZAÇÃO DO SERVIDOR
// ============================================================
app.listen(PORT, () => {
  console.log(`========================================`);
  console.log(`  API de Livros rodando na porta ${PORT}`);
  console.log(`  Ambiente: ${process.env.NODE_ENV || 'development'}`);
  console.log(`  Base URL: http://localhost:${PORT}/api`);
  console.log(`========================================`);
  console.log(`\nEndpoints disponíveis:`);
  console.log(`  GET    http://localhost:${PORT}/api/books       — Listar livros`);
  console.log(`  GET    http://localhost:${PORT}/api/books/:id   — Obter livro`);
  console.log(`  POST   http://localhost:${PORT}/api/books       — Criar livro`);
  console.log(`  PUT    http://localhost:${PORT}/api/books/:id   — Atualizar livro`);
  console.log(`  DELETE http://localhost:${PORT}/api/books/:id   — Excluir livro`);
  console.log(`  GET    http://localhost:${PORT}/api/stats       — Estatísticas`);
});

module.exports = app; // Exporta para testes
```

