 *   - isbn (string): ISBN-13 format for uniqueness validation.
 *   - publishedYear (number): Year the book was first published.
 *   - genre (string): Primary genre/category.
 *   - createdAt (string): ISO 8601 timestamp of creation.
 *   - updatedAt (string): ISO 8601 timestamp of last modification.
 */
const books = [
  {
    id: 1,
    title: "The Great Gatsby",
    author: "F. Scott Fitzgerald",
    isbn: "978-0743273565",
    publishedYear: 1925,
    genre: "Fiction",
    createdAt: "2024-01-01T00:00:00.000Z",
    updatedAt: "2024-01-01T00:00:00.000Z"
  },
  {
    id: 2,
    title: "To Kill a Mockingbird",
    author: "Harper Lee",
    isbn: "978-0061120084",
    publishedYear: 1960,
    genre: "Fiction",
    createdAt: "2024-01-01T00:00:00.000Z",
    updatedAt: "2024-01-01T00:00:00.000Z"
  },
  {
    id: 3,
    title: "A Brief History of Time",
    author: "Stephen Hawking",
    isbn: "978-0553380163",
    publishedYear: 1988,
    genre: "Science",
    createdAt: "2024-01-01T00:00:00.000Z",
    updatedAt: "2024-01-01T00:00:00.000Z"
  }
];

/**
 * Next available ID for auto-increment.
 * Initialized to the max existing ID + 1 so new books don't collide.
 */
let nextId = 4;

