## File 3: `src/errors/customErrors.js`

```javascript
/**
 * ============================================================================
 * CUSTOM ERROR CLASSES — Structured Error Handling
 * ============================================================================
 *
 * WHY CUSTOM ERROR CLASSES?
 * -------------------------
 * JavaScript's built-in Error class is generic. By creating subclasses we can:
 *   1. Distinguish error types in middleware (e.g., NotFound vs ValidationError).
 *   2. Attach extra properties (like `statusCode` and `details`).
 *   3. Provide meaningful messages without leaking internal details to clients.
 *
 * WHY NOT JUST THROW ERRORS WITH STATUS CODES?
 * ---------------------------------------------
 * Without custom classes, error-handling middleware would need string matching
 * on error messages or try/catch blocks with manual status code assignment.
 * Custom classes make the intent explicit and the middleware cleaner.
 */

/**
 * Base error class that all custom errors extend.
 * Provides a consistent shape: { name, message, statusCode, isOperational }.
 */
class AppError extends Error {
  /**
   * @param {string} message - Human-readable error description.
   * @param {number} statusCode - HTTP status code (4xx client, 5xx server).
   */
  constructor(message, statusCode) {
    super(message); // Pass message to built-in Error constructor

    this.statusCode = statusCode;
    this.isOperational = true; // Marks as expected error (not a bug)

    // Capture the stack trace for debugging (omitted in production logs if desired)
    Error.captureStackTrace(this, this.constructor);
  }
}

/**
 * 404 Not Found — Resource does not exist.
 * Thrown when a requested book ID is invalid or no results match a query.
 */
class NotFoundError extends AppError {
  constructor(resource = "resource") {
    super(`${resource} not found`, 404);
    this.name = "NotFoundError";
  }
}

/**
 * 400 Bad Request — Client sent invalid data.
 * Thrown when validation fails (missing fields, wrong types, duplicate ISBN).
 */
class ValidationError extends AppError {
  /**
   * @param {string} message - General error description.
   * @param {Array<Object>} details - Array of { field, message } objects.
   */
  constructor(message = "Validation failed", details = []) {
    super(message, 400);
    this.name = "ValidationError";
    this.details = details; // Structured per-field errors for client feedback
  }
}

/**
 * 500 Internal Server Error — Unexpected server-side failure.
 * Used as a fallback in the error-handling middleware.
 */
class InternalError extends AppError {
  constructor(message = "An unexpected error occurred") {
    super(message, 500);
    this.name = "InternalError";
  }
}

/**
 * ============================================================================
 * EXPORTS
 * ============================================================================
 */
module.exports = { AppError, NotFoundError, ValidationError, InternalError };
```

> **Why `isOperational`?** This flag lets our error middleware distinguish between:
> - **Operational errors** (expected, like "book not found") — log the message but don't alert on-call engineers.
> - **Programming errors** (bugs, undefined variables) — these should trigger alerts because they indicate real problems.

