## File 4: `src/middleware/errorHandler.js`

```javascript
/**
 * ============================================================================
 * ERROR HANDLING MIDDLEWARE — Centralized Error Management
 * ============================================================================
 *
 * WHY EXPRESS ERROR-MIDDLEWARE PATTERN?
 * ---------------------------------------
 * Express has a special signature for error-handling middleware:
 *   (err, req, res, next) => { ... }
 *
 * This is triggered when:
 *   1. `next(err)` is called explicitly in a route or service.
 *   2. An async function throws an unhandled exception.
 *   3. A synchronous error occurs inside a route handler.
 *
 * Placing this middleware LAST (after all routes) ensures it catches errors
 * from any preceding middleware or route handler. Express scans middlewares
 * in order and skips normal ones when an error is present, landing here.
 *
 * WHY RETURN JSON FOR ALL ERRORS?
 * --------------------------------
 * Consistent error responses let API consumers parse errors uniformly:
 *   { "error": { "message": "...", "statusCode": 404 } }
 *
 * This is the pattern used by Stripe, Twilio, and many other well-designed APIs.
 */

const { AppError } = require("../errors/customErrors");

/**
 * Centralized error-handling middleware.
 *
 * @param {Error} err - The error object (custom or built-in).
 * @param {import("express").Request} req - Express request object.
 * @param {import("express").Response} res - Express response object.
 * @param {import("express").NextFunction} next - Express next middleware function.
 */
function errorHandler(err, req, res, next) {
  // Log the full error for debugging (in production, use a logging service)
  console.error(`[ERROR] ${new Date().toISOString()} — ${err.name}: ${err.message}`);
  if (err.stack) {
    console.error(err.stack);
  }

  // Determine the response shape based on error type
  let statusCode = err.statusCode || 500;
  let errorMessage = err.message || "Internal Server Error";
  let errorDetails = null;

  // Custom errors carry their own status and details
  if (err instanceof AppError) {
    statusCode = err.statusCode;
    errorMessage = err.message;
    if (err.details && err.details.length > 0) {
      errorDetails = err.details;
    }
  }
  // For unknown errors, we intentionally do NOT expose the raw message
  // to avoid leaking stack traces or internal paths to API consumers.

  /**
   * Send a consistent JSON error response.
   * Example shape:
   * {
   *   "error": {
   *     "message": "Book not found",
   *     "statusCode": 404,
   *     "details": null
   *   }
   * }
   */
  res.status(statusCode).json({
    error: {
      message: errorMessage,
      statusCode: statusCode,
      details: errorDetails
    }
  });
}

/**
 * ============================================================================
 * EXPORTS
 * ============================================================================
 */
module.exports = errorHandler;
```

> **Why not use `next()` inside the error handler?** Once we send a response, we must not call `next()` — that would attempt to send a second response and crash the server. The error handler is always the terminal middleware in the chain.

