## File 5: `src/services/bookService.js`

```javascript
/**
 * ============================================================================
 * BOOK SERVICE — Business Logic Layer
 * ============================================================================
 *
 * WHY A SEPARATE SERVICE LAYER?
 * -------------------------------
 * Keeping business logic out of route handlers gives us:
 *   1. **Testability** — Services can be unit-tested without HTTP overhead.
 *   2. **Reusability** — The same logic could be used by a CLI tool or scheduler.
 *   3. **Clarity** — Routes stay thin (parse input → call service → send response).
 *
 * WHY NOT PUT LOGIC IN ROUTES?
 * ------------------------------
 * Route handlers should only handle HTTP concerns (parsing, validation, formatting).
 * Mixing business logic into routes creates "fat controllers" that are hard to test
 * and maintain. This separation is a core principle of clean architecture.
 *
 * WHY USE ASYNC/AWAIT?
 * --------------------
 * Even though our data layer is synchronous (in-memory array), we use async/await
 * so the service is ready for a database swap later without changing route code.
 * It also lets us use try/catch cleanly and keeps error handling consistent.
 */

const { books, nextId } = require("../models/book");
const { NotFoundError, ValidationError } = require("../errors/customErrors");

/**
 * Validates that all required fields are present and have correct types.
 *
 * @param {Object} data - The book data to validate.
 * @returns {Array<{field: string, message: string}>} Array of validation errors (empty if valid).
 */
function validateBookData(data) {
  const errors = [];

  // Check required fields exist and are non-empty strings
  if (!data.title || typeof data.title !== "string" || data.title.trim() === "") {
    errors.push({ field: "title", message: "Title is required and must be a non-empty string" });
  }

  if (!data.author || typeof data.author !== "string" || data.author.trim() === "") {
    errors.push({ field: "author", message: "Author is required and must be a non-empty string" });
  }

  if (!data.isbn || typeof data.isbn !== "string" || data.isbn.trim() === "") {
    errors.push({ field: "isbn", message: "ISBN is required and must be a non-empty string" });
  }

  // Validate publishedYear is a positive integer
  if (
    data.publishedYear === undefined ||
    data.publishedYear === null ||
    !Number.isInteger(data.publishedYear) ||
    data.publishedYear < 0 ||
    data.publishedYear > new Date().getFullYear() + 1
  ) {
    errors.push({
      field: "publishedYear",
      message: "Published year is required and must be a positive integer"
    });
  }

  // Validate genre is a non-empty string
  if (!data.genre || typeof data.genre !== "string" || data.genre.trim() === "") {
    errors.push({ field: "genre", message: "Genre is required and must be a non-empty string" });
  }

  return errors;
}

/**
 * ============================================================================
 * CREATE — POST /books
 * ============================================================================
 * Creates a new book with auto-generated ID and timestamps.
 *
 * @param {Object} bookData - Book properties from request body.
 * @returns {Object} The created book object.
 * @throws {ValidationError} If required fields are missing or invalid.
 * @throws {ValidationError} If ISBN already exists (duplicate).
 */
async function createBook(bookData) {
  // Step 1: Validate input — fail fast before any mutations
  const validationErrors = validateBookData(bookData);
  if (validationErrors.length > 0) {
    throw new ValidationError("Invalid book data", validationErrors);
  }

  // Step 2: Check for duplicate ISBN — ISBNs should be globally unique
  const isbnExists = books.some((book) => book.isbn === bookData.isbn.trim());
  if (isbnExists) {
    throw new ValidationError("Duplicate ISBN", [
      { field: "isbn", message: `ISBN ${bookData.isbn} already exists` }
    ]);
  }

  // Step 3: Build the book object with timestamps
  const now = new Date().toISOString();
  const newBook = {
    id: nextId++, // Auto-increment: read current value, then increment
    title: bookData.title.trim(),
    author: bookData.author.trim(),
    isbn: bookData.isbn.trim(),
    publishedYear: bookData.publishedYear,
    genre: bookData.genre.trim(),
    createdAt: now,
    updatedAt: now
  };

  // Step 4: Add to in-memory store
  books.push(newBook);

  return newBook;
}

/**
 * ============================================================================
 * READ ALL — GET /books
 * ============================================================================
 * Returns all books with optional filtering by genre and/or author.
 *
 * @param {Object} filters - Optional query parameters.
 * @param {string} [filters.genre] - Filter by genre (case-insensitive).
 * @param {string} [filters.author] - Filter by author name substring (case-insensitive).
 * @returns {Array<Object>} Array of matching book objects.
 */
async function getAllBooks(filters = {}) {
  let result = [...books]; // Spread to avoid mutating the original array

  // Apply genre filter if provided
  if (filters.genre) {
    const genreLower = filters.genre.toLowerCase();
    result = result.filter((book) => book.genre.toLowerCase() === genreLower);
  }

  // Apply author filter if provided (substring match for flexibility)
  if (filters.author) {
    const authorLower = filters.author.toLowerCase();
    result = result.filter((book) => book.author.toLowerCase().includes(authorLower));
  }

  return result;
}

/**
 * ============================================================================
 * READ ONE — GET /books/:id
 * ============================================================================
 * Returns a single book by its numeric ID.
 *
 * @param {number} id - The book's unique identifier.
 * @returns {Object} The matching book object.
 * @throws {NotFoundError} If no book with the given ID exists.
 */
async function getBookById(id) {
  const book = books.find((b) => b.id === id);

  if (!book) {
    throw new NotFoundError("Book");
  }

  return book;
}

/**
 * ============================================================================
 * UPDATE — PUT /books/:id
 * ============================================================================
 * Replaces all updatable fields of an existing book.
 *
 * NOTE: We do NOT allow changing the `id` or `createdAt` timestamp, as these
 * are immutable identifiers. The `updatedAt` timestamp is refreshed automatically.
 *
 * @param {number} id - The book's unique identifier.
 * @param {Object} updateData - Fields to update (partial object).
 * @returns {Object} The updated book object.
 * @throws {NotFoundError} If the book does not exist.
 * @throws {ValidationError} If provided data fails validation.
 */
async function updateBook(id, updateData) {
  // Step 1: Find the existing book
  const bookIndex = books.findIndex((b) => b.id === id);

  if (bookIndex === -1) {
    throw new NotFoundError("Book");
  }

  // Step 2: Validate any provided fields (only if they're being changed)
  const validationErrors = validateBookData(updateData);
  if (validationErrors.length > 0) {
    throw new ValidationError("Invalid book data", validationErrors);
  }

  // Step 3: Check ISBN uniqueness only if ISBN is being changed
  if (updateData.isbn && updateData.isbn !== books[bookIndex].isbn) {
    const isbnExists = books.some(
      (book) => book.isbn === updateData.isbn.trim() && book.id !== id
    );
    if (isbnExists) {
      throw new ValidationError("Duplicate ISBN", [
        { field: "isbn", message: `ISBN ${updateData.isbn} already exists` }
      ]);
    }
  }

  // Step 4: Build the updated book object
  const now = new Date().toISOString();
  const updatedBook = {
    ...books[bookIndex], // Start with existing data (preserves id, createdAt)
    title: updateData.title ? updateData.title.trim() : books[bookIndex].title,
    author: updateData.author ? updateData.author.trim() : books[bookIndex].author,
    isbn: updateData.isbn ? updateData.isbn.trim() : books[bookIndex].isbn,
    publishedYear: updateData.publishedYear !== undefined ? updateData.publishedYear : books[bookIndex].publishedYear,
    genre: updateData.genre ? updateData.genre.trim() : books[bookIndex].genre,
    updatedAt: now // Always refresh the update timestamp
  };

  // Step 5: Replace in the array (splice is O(n) but fine for small datasets)
  books.splice(bookIndex, 1, updatedBook);

  return updatedBook;
}

/**
 * ============================================================================
 * DELETE — DELETE /books/:id
 * ============================================================================
 * Removes a book from the store by its ID.
 *
 * @param {number} id - The book's unique identifier.
 * @returns {Object} The deleted book object (for confirmation).
 * @throws {NotFoundError} If the book does not exist.
 */
async function deleteBook(id) {
  const bookIndex = books.findIndex((b) => b.id === id);

  if (bookIndex === -1) {
    throw new NotFoundError("Book");
  }

  // Remove exactly one element at the found index
  const [deletedBook] = books.splice(bookIndex, 1);

  return deletedBook;
}

/**
 * ============================================================================
 * STATISTICS — GET /stats
 * ============================================================================
 * Computes aggregate statistics across all books.
 *
 * Statistics include:
 *   - totalBooks: Total number of books in the store.
 *   - genres: Count of books per genre (object mapping genre → count).
 *   - authors: Count of books per author (object mapping author → count).
 *   - averagePublishedYear: Mean year of publication (rounded to 2 decimals).
 *   - oldestBook: Title and year of the earliest published book.
 *   - newestBook: Title and year of the most recently published book.
 *
 * @returns {Object} Statistics object.
 */
async function getStats() {
  const totalBooks = books.length;

  // Build genre counts using reduce for O(n) single-pass aggregation
  const genres = books.reduce((acc, book) => {
    acc[book.genre] = (acc[book.genre] || 0) + 1;
    return acc;
  }, {});

  // Build author counts similarly
  const authors = books.reduce((acc, book) => {
    acc[book.author] = (acc[book.author] || 0) + 1;
    return acc;
  }, {});

  // Compute average published year
  let averagePublishedYear = 0;
  if (totalBooks > 0) {
    const totalYear = books.reduce((sum, book) => sum + book.publishedYear, 0);
    averagePublishedYear = Math.round((totalYear / totalBooks) * 100) / 100;
  }

  // Find oldest and newest books
  let oldestBook = null;
  let newestBook = null;
  if (totalBooks > 0) {
    oldestBook = books.reduce(
      (oldest, book) => (book.publishedYear < oldest.publishedYear ? book : oldest),
      books[0]
    );
    newestBook = books.reduce(
      (newest, book) => (book.publishedYear > newest.publishedYear ? book : newest),
      books[0]
    );
  }

  return {
    totalBooks,
    genres,
    authors,
    averagePublishedYear,
    oldestBook: oldestBook
      ? { title: oldestBook.title, author: oldestBook.author, publishedYear: oldestBook.publishedYear }
      : null,
    newestBook: newestBook
      ? { title: newestBook.title, author: newestBook.author, publishedYear: newestBook.publishedYear }
      : null
  };
}

/**
 * ============================================================================
 * EXPORTS
 * ============================================================================
 */
module.exports = {
  createBook,
  getAllBooks,
  getBookById,
  updateBook,
  deleteBook,
  getStats
};
```

> **Why `splice` instead of filter for deletion?** `splice` modifies the array in place and is O(n) — perfectly fine for small datasets. For a production app with thousands of records, you'd use a Set or database query. The key point is we're mutating a shared reference (`books`), so all modules see the change immediately.

