## File 6: `src/routes/books.js`

```javascript
/**
 * ============================================================================
 * BOOK ROUTES — HTTP Endpoint Definitions
 * ============================================================================
 *
 * WHY SEPARATE ROUTE FILES?
 * -------------------------
 * As the API grows, keeping all routes in one file becomes unwieldy.
 * Separate route files allow:
 *   1. Parallel development (different team members work on different resources).
 *   2. Easier testing (route tests are isolated from other endpoints).
 *   3. Clear organization — all book-related endpoints live together.
 *
 * WHY USE `express.Router()`?
 * ----------------------------
 * `Router` creates a modular, mountable route handler. It lets us:
 *   - Define routes with a base path prefix (`/books`).
 *   - Apply route-specific middleware (e.g., authentication) in one place.
 *   - Reuse the router across multiple mounts if needed.
 *
 * WHY ASYNC/AWAIT IN ROUTE HANDLERS?
 * -----------------------------------
 * Express 4 supports async route handlers natively — errors are caught and
 * passed to the error-handling middleware automatically. This avoids the
 * verbose try/catch + next(err) pattern while keeping code readable.
 */

const express = require("express");
const router = express.Router();

// Import service functions (business logic lives here, not in routes)
const {
  createBook,
  getAllBooks,
  getBookById,
  updateBook,
  deleteBook
} = require("../services/bookService");

/**
 * ============================================================================
 * GET /books — List All Books (with optional filtering)
 * ============================================================================
 *
 * Query Parameters:
 *   - genre (string): Filter by exact genre match (case-insensitive).
 *   - author (string): Filter by author name substring (case-insensitive).
 *
 * Response Examples:
 *
 *   // All books
 *   GET /books
 *   → 200 OK
 *   { "books": [ {...}, {...} ] }
 *
 *   // Filtered by genre
 *   GET /books?genre=Science
 *   → 200 OK
 *   { "books": [ {...} ] }
 *
 *   // Filtered by author
 *   GET /books?author=hawking
 *   → 200 OK
 *   { "books": [ {...} ] }
 *
 *   // No matches
 *   GET /books?genre=Fantasy
 *   → 200 OK
 *   { "books": [] }
 */
router.get("/", async (req, res, next) => {
  try {
    // Extract optional query parameters with defaults
    const filters = {
      genre: req.query.genre || undefined,
      author: req.query.author || undefined
    };

    // Call service layer — routes stay thin
    const result = await getAllBooks(filters);

    // Send JSON response with 200 status (default in Express)
    res.json({ books: result });
  } catch (error) {
    // Pass any error to the centralized error handler
    next(error);
  }
});

/**
 * ============================================================================
 * GET /books/:id — Get Single Book by ID
 * ============================================================================
 *
 * Path Parameters:
 *   - id (number): The unique identifier of the book.
 *
 * Response Examples:
 *
 *   // Success
 *   GET /books/1
 *   → 200 OK
 *   { "book": { "id": 1, "title": "...", ... } }
 *
 *   // Not found
 *   GET /books/999
 *   → 404 Not Found
 *   { "error": { "message": "Book not found", "statusCode": 404 } }
 */
router.get("/:id", async (req, res, next) => {
  try {
    // Parse the ID from the URL path — Express makes this available as req.params
    const id = parseInt(req.params.id, 10);

    // Validate that the ID is a valid integer
    if (isNaN(id)) {
      return res.status(400).json({
        error: { message: "Invalid book ID. Must be a number.", statusCode: 400 }
      });
    }

    const book = await getBookById(id);
    res.json({ book });
  } catch (error) {
    next(error);
  }
});

/**
 * ============================================================================
 * POST /books — Create a New Book
 * ============================================================================
 *
 * Request Body (JSON):
 *   {
 *     "title": "The Hobbit",
 *     "author": "J.R.R. Tolkien",
 *     "isbn": "978-0547928227",
 *     "publishedYear": 1937,
 *     "genre": "Fantasy"
 *   }
 *
 * Response Examples:
 *
 *   // Success — returns the created book with auto-generated ID and timestamps
 *   POST /books
 *   → 201 Created
 *   { "book": { "id": 4, "title": "...", ... } }
 *
 *   // Validation error — missing required field
 *   POST /books
 *   Body: { "title": "Incomplete" }
 *   → 400 Bad Request
 *   { "error": { "message": "Invalid book data", "statusCode": 400, "details": [...] } }
 *
 *   // Duplicate ISBN
 *   POST /books
 *   Body: { "title": "...", "author": "...", "isbn": "978-0743273565", ... }
 *   → 400 Bad Request
 */
router.post("/", async (req, res, next) => {
  try {
    // Express's built-in JSON parser populates req.body automatically
    // when the client sends Content-Type: application/json
    const bookData = req.body;

    const newBook = await createBook(bookData);

    // 201 Created is the standard status for resource creation
    res.status(201).json({ book: newBook });
  } catch (error) {
    next(error);
  }
});

/**
 * ============================================================================
 * PUT /books/:id — Update an Existing Book
 * ============================================================================
 *
 * Path Parameters:
 *   - id (number): The unique identifier of the book to update.
 *
 * Request Body (JSON) — all fields are optional (partial update):
 *   {
 *     "title": "Updated Title",
 *     "author": "Updated Author",
 *     "isbn": "978-0000000000",
 *     "publishedYear": 2000,
 *     "genre": "Updated Genre"
 *   }
 *
 * Response Examples:
 *
 *   // Success — returns the fully updated book
 *   PUT /books/1
 *   → 200 OK
 *   { "book": { "id": 1, "title": "The Great Gatsby (Updated)", ... } }
 *
 *   // Not found
 *   PUT /books/999
 *   → 404 Not Found
 */
router.put("/:id", async (req, res, next) => {
  try {
    const id = parseInt(req.params.id, 10);

    if (isNaN(id)) {
      return res.status(400).json({
        error: { message: "Invalid book ID. Must be a number.", statusCode: 400 }
      });
    }

    const updatedBook = await updateBook(id, req.body);
    res.json({ book: updatedBook });
  } catch (error) {
    next(error);
  }
});

/**
 * ============================================================================
 * DELETE /books/:id — Delete a Book
 * ============================================================================
 *
 * Path Parameters:
 *   - id (number): The unique identifier of the book to delete.
 *
 * Response Examples:
 *
 *   // Success — returns the deleted book for confirmation
 *   DELETE /books/1
 *   → 200 OK
 *   { "book": { "id": 1, ... } }
 *
 *   // Not found
 *   DELETE /books/999
 *   → 404 Not Found
 */
router.delete("/:id", async (req, res, next) => {
  try {
    const id = parseInt(req.params.id, 10);

    if (isNaN(id)) {
      return res.status(400).json({
        error: { message: "Invalid book ID. Must be a number.", statusCode: 400 }
      });
    }

    const deletedBook = await deleteBook(id);
    res.json({ book: deletedBook });
  } catch (error) {
    next(error);
  }
});

/**
 * ============================================================================
 * EXPORTS
 * ============================================================================
 */
module.exports = router;
```

> **Why return the full object on DELETE?** This is a RESTful convention that lets clients confirm exactly what was removed. Some APIs return `204 No Content` instead, but returning the deleted resource is more informative for debugging and testing.

