/**
 * ============================================================================
 * STATS ROUTES — API Statistics Endpoint
 * ============================================================================
 *
 * WHY A SEPARATE ENDPOINT?
 * -------------------------
 * Keeping stats separate from the books collection makes semantic sense:
 *   - `/books` returns book resources.
 *   - `/stats` returns aggregate metadata about those resources.
 *
 * This follows REST conventions where each endpoint represents a distinct
 * resource or collection, even if they're related.
 */

const express = require("express");
const router = express.Router();
const { getStats } = require("../services/bookService");

/**
 * ============================================================================
 * GET /stats — Return API Statistics
 * ============================================================================
 *
 * Returns aggregate statistics about the book collection:
 *   - totalBooks: Total count of books.
 *   - genres: Breakdown of books by genre.
 *   - authors: Breakdown of books by author.
 *   - averagePublishedYear: Mean publication year.
 *   - oldestBook / newestBook: Extremes in publication date.
 *
 * Response Example:
 * {
 *   "stats": {
 *     "totalBooks": 3,
 *     "genres": { "Fiction": 2, "Science": 1 },
 *     "authors": { "F. Scott Fitzgerald": 1, "Harper Lee": 1, "Stephen Hawking": 1 },
 *     "averagePublishedYear": 1924.33,
 *     "oldestBook": { "title": "The Great Gatsby", "author": "F. Scott Fitzgerald", "publishedYear": 1925 },
 *     "newestBook": { "title": "A Brief History of Time", "author": "Stephen Hawking", "publishedYear": 1988 }
 *   }
 * }
 */
router.get("/", async (req, res, next) => {
  try {
    const stats = await getStats();
    res.json({ stats });
  } catch (error) {
    next(error);
  }
});

/**
 * ============================================================================
 * EXPORTS
