## File 8: `src/app.js` — Main Application Entry Point

```javascript
/**
 * ============================================================================
 * APPLICATION ENTRY POINT
 * ============================================================================
 *
 * WHY THIS ORDER OF MIDDLEWARE?
 * -------------------------------
 * Express executes middleware in the order it's registered. The sequence matters:
 *
 *   1. `express.json()` — Parses incoming JSON request bodies. Must come BEFORE
 *      route handlers so req.body is populated when routes run.
 *
 *   2. `app.use('/books', bookRoutes)` — Mounts the book router at /books.
 *      All book routes are now accessible under this prefix.
 *
 *   3. `app.use('/stats', statsRoutes)` — Mounts the stats router at /stats.
 *
 *   4. `app.use(errorHandler)` — MUST be last. Express only routes to error
 *      handlers after all normal middleware has been exhausted. If placed
 *      earlier, it would intercept errors before they reach route handlers.
 *
 * WHY `app.listen()` HERE AND NOT IN A SEPARATE FILE?
 * ----------------------------------------------------
 * For this educational example, keeping everything in one file is simpler.
 * In a production app, you'd typically separate server creation (server.js)
 * from the Express app definition (app.js) to enable testing the app
 * without starting an HTTP server.
 */

const express = require("express");

// Import route modules
const bookRoutes = require("./routes/books");
const statsRoutes = require("./routes/stats");

// Import centralized error handler
const errorHandler = require("./middleware/errorHandler");

// Create the Express application instance
const app = express();

// ============================================================================
// MIDDLEWARE CONFIGURATION
// ============================================================================

/**
 * Parse JSON request bodies.
 * Enables req.body to contain parsed JSON when clients send POST/PUT requests.
 * Without this, req.body would be undefined.
 */
app.use(express.json());

/**
 * Log every incoming request for debugging.
 * In production, consider using a proper logging library (winston, pino).
 */
app.use((req, res, next) => {
  console.log(`[${new Date().toISOString()}] ${req.method} ${req.url}`);
  next(); // Must call next() to continue the middleware chain
});

// ============================================================================
// ROUTE MOUNTING
// ============================================================================

/**
 * Mount book routes at /books.
 * All routes in books.js are now prefixed with /books:
 *   GET    /books          → list all books
 *   GET    /books/:id      → get single book
 *   POST   /books          → create new book
 *   PUT    /books/:id      → update existing book
 *   DELETE /books/:id      → delete a book
 */
app.use("/books", bookRoutes);

/**
 * Mount stats routes at /stats.
 *   GET /stats → return aggregate statistics
 */
app.use("/stats", statsRoutes);

// ============================================================================
// 404 HANDLER — Catch-all for undefined routes
// ============================================================================

/**
 * If a request reaches here, no route matched.
 * This is NOT an error middleware (no `err` parameter), so it acts as normal
 * middleware that responds to unmatched paths.
 */
app.use((req, res) => {
  res.status(404).json({
    error: {
      message: `Route ${req.method} ${req.url} not found`,
      statusCode: 404
    }
  });
});

// ============================================================================
// ERROR HANDLING — Must be LAST middleware
// ============================================================================

/**
 * Centralized error handler catches all errors from routes and services.
 * See src/middleware/errorHandler.js for full implementation details.
 */
app.use(errorHandler);

// ============================================================================
// SERVER STARTUP
// ============================================================================

const PORT = process.env.PORT || 3000;

app.listen(PORT, () => {
  console.log(`========================================`);
  console.log(`  Book REST API running on port ${PORT}`);
  console.log(`  Environment: ${process.env.NODE_ENV || "development"}`);
  console.log(`========================================`);
  console.log(`\nAvailable endpoints:`);
  console.log(`  GET    http://localhost:${PORT}/books          — List all books`);
  console.log(`  GET    http://localhost:${PORT}/books/:id      — Get a book by ID`);
  console.log(`  POST   http://localhost:${PORT}/books          — Create a new book`);
  console.log(`  PUT    http://localhost:${PORT}/books/:id      — Update a book`);
  console.log(`  DELETE http://localhost:${PORT}/books/:id      — Delete a book`);
  console.log(`  GET    http://localhost:${PORT}/stats          — Get statistics`);
  console.log(`\nTry: curl http://localhost:${PORT}/books\n`);
});

/**
 * ============================================================================
 * EXPORTS (for testing)
 * ============================================================================
 */
module.exports = app;
```

> **Why export `app`?** Even though we start the server here, exporting the Express app instance allows unit tests to import it and make HTTP requests without starting a real server (using Supertest or similar). This is a common pattern in Node.js testing.

