## Arquivo 2: `src/middleware/errorHandler.js`

```javascript
/**
 * ============================================================
 *  MIDDLEWARE DE TRATAMENTO DE ERROS
 * ============================================================
 *
 * POR QUE UM ARQUIVO SEPARADO?
 * ----------------------------
 * Separar o tratamento de erros do código principal segue o princípio
 * de responsabilidade única (Single Responsibility Principle). Isso torna
 * mais fácil adicionar novos tipos de erro, modificar mensagens ou integrar
 * com sistemas de logging sem tocar nas rotas.
 *
 * POR QUE CLASSES DE ERRO PERSONALIZADAS?
 * ----------------------------------------
 * Classes como NotFoundError e ValidationError herdam de Error e adicionam
 * propriedades específicas (statusCode, isOperational). Isso permite que o
 * middleware identifique o tipo de erro e responda com códigos HTTP adequados.
 * Erros "operacionais" são aqueles esperados (ex: recurso não encontrado),
 * enquanto erros "não operacionais" indicam bugs no código e devem ser logados.
 * ============================================================
 */

const express = require('express');

// ----------------------------------------------------------
// CLASSES DE ERRO PERSONALIZADAS
// ----------------------------------------------------------

/**
 * Erro personalizado para quando um recurso não é encontrado.
 *
 * Escolha do padrão: Usamos uma classe que herda de Error e define
 * statusCode como 404, que é o código HTTP padrão para "Not Found".
 * Isso permite que o middleware responda automaticamente com o status correto.
 */
class NotFoundError extends Error {
  /**
   * @param {string} message - Mensagem descritiva do erro
   * @param {number} [statusCode=404] - Código HTTP da resposta de erro
   */
  constructor(message, statusCode = 404) {
    super(message); // Chama o construtor da classe Error pai
    this.statusCode = statusCode;
    this.isOperational = true; // Indica que é um erro esperado, não um bug

    // Mantém o stack trace correto mesmo com a herança customizada
    Error.captureStackTrace(this, this.constructor);
  }
}

/**
 * Erro personalizado para validação de dados inválidos.
 *
 * Escolha do padrão: Usamos 400 (Bad Request) porque o cliente enviou
 * dados que não atendem aos requisitos do servidor. O campo 'details'
 * armazena informações específicas sobre quais campos falharam na validação.
 */
class ValidationError extends Error {
  /**
   * @param {string} message - Mensagem descritiva do erro
   * @param {Array<Object>} [details=[]] - Lista de detalhes da validação
   * @param {number} [statusCode=400] - Código HTTP da resposta de erro
   */
  constructor(message, details = [], statusCode = 400) {
    super(message);
    this.statusCode = statusCode;
    this.details = details; // Ex: [{ field: 'title', message: 'obrigatório' }]
    this.isOperational = true;
    Error.captureStackTrace(this, this.constructor);
  }
}

/**
 * Erro para quando o cliente tenta acessar um recurso inexistente via ID.
 *
 * Escolha do padrão: Diferenciamos NotFoundError (recurso não existe) de
 * este erro (ID malformado). O código 422 (Unprocessable Entity) indica que
 * o servidor entende a solicitação mas não pode processá-la devido ao ID inválido.
 */
class InvalidIdError extends Error {
  /**
   * @param {string} id - O ID recebido que é inválido
   * @param {number} [statusCode=422] - Código HTTP da resposta de erro
   */
  constructor(id, statusCode = 422) {
    super(`ID inválido: "${id}". Deve ser um número inteiro positivo.`);
    this.statusCode = statusCode;
    this.isOperational = true;
    Error.captureStackTrace(this, this.constructor);
  }
}

// ----------------------------------------------------------
// FUNÇÃO DE VALIDAÇÃO DE ID
// ----------------------------------------------------------

/**
 * Valida se um ID recebido nos parâmetros da URL é válido.
 *
 * POR QUE VALIDAR O ID AQUI?
 * ---------------------------
 * Centralizamos a validação do ID em uma única função para evitar repetição
 * de código em múltiplas rotas. Se a lógica de validação mudar no futuro,
 * basta atualizar esta função.
 *
 * @param {string} id - O ID recebido como parâmetro da URL
 * @returns {number} O ID convertido para número inteiro
 * @throws {InvalidIdError} Se o ID não for um número inteiro positivo
 */
function validateId(id) {
  const numericId = parseInt(id, 10); // Converte string para número

  // Verifica se a conversão foi bem-sucedida E se é maior que zero
  if (isNaN(numericId) || numericId <= 0 || !Number.isInteger(numericId)) {
    throw new InvalidIdError(id);
  }

  return numericId;
}

// ----------------------------------------------------------
// MIDDLEWARE PRINCIPAL DE TRATAMENTO DE ERROS
// ----------------------------------------------------------

/**
 * Middleware global de tratamento de erros do Express.
 *
 * POR QUE ESTA ASSINATURA?
 * -------------------------
 * O Express identifica middlewares de erro pela assinatura com 4 parâmetros:
 * (err, req, res, next). Se tiver 3 ou menos, é tratado como middleware normal.
 * Este middleware captura TODOS os erros lançados em qualquer rota ou middleware.
 *
 * A ordem importa: este middleware DEVE ser o último a ser registrado no app,
 * após todas as rotas e middlewares de tratamento de erro específicos.
 *
 * @param {Error} err - O objeto de erro lançado
 * @param {import('express').Request} req - Objeto de requisição do Express
 * @param {import('express').Response} res - Objeto de resposta do Express
 * @param {import('express').NextFunction} next - Função para passar ao próximo middleware
 */
function errorHandler(err, req, res, next) {
  // ----------------------------------------------------------
  // ERROS NÃO OPERACIONAIS (BUGS NO CÓDIGO)
  // ----------------------------------------------------------
  // Estes erros não têm statusCode definido e indicam problemas
  // no código do servidor. Respondemos com 500 e logamos o erro.
  if (!err.isOperational) {
    console.error('[ERRO DO SERVIDOR]', err); // Log completo para depuração
    return res.status(500).json({
      success: false,
      error: 'Erro interno do servidor',
      message: 'Ocorreu um erro inesperado. Tente novamente mais tarde.'
    });
  }

  // ----------------------------------------------------------
  // ERROS OPERACIONAIS (COMPORTAMENTO ESPERADO)
  // ----------------------------------------------------------
  // Estes erros têm statusCode definido e indicam problemas
  // causados pela entrada do cliente ou estado do recurso.

  let response = {
    success: false,
    error: err.name || 'Erro',
    message: err.message
  };

  // Adiciona detalhes de validação quando disponíveis
  if (err.details && err.details.length > 0) {
    response.details = err.details;
  }

  // Responde com o código HTTP apropriado do erro
  res.status(err.statusCode || 500).json(response);
}

// ----------------------------------------------------------
// EXPORTAÇÕES
// ----------------------------------------------------------

module.exports = {
  NotFoundError,
  ValidationError,
  InvalidIdError,
  validateId,
  errorHandler
};
