```javascript
/**
 * ============================================================
 *  SERVIÇO DE LIVROS — LÓGICA DE NEGÓCIO
 * ============================================================
 *
 * POR QUE UMA CAMADA DE SERVIÇO?
 * -------------------------------
 * Separar a lógica de negócio das rotas segue o padrão MVC (Model-View-Controller).
 * As rotas se preocupam apenas com HTTP (requisição/resposta), enquanto o serviço
 * cuida dos dados. Isso permite reutilizar a lógica, testá-la isoladamente e
 * trocar o armazenamento (array → banco de dados) sem alterar as rotas.
 *
 * POR QUE ARRAY EM MEMÓRIA?
 * --------------------------
 * Para este exemplo educacional, usamos um array porque:
 * 1. Não requer configuração de banco de dados
 * 2. É fácil de entender e depurar
 * 3. Permite focar nos conceitos de API REST
 * Em produção, substituiríamos por um banco como MongoDB ou PostgreSQL.
 * ============================================================
 */

const { NotFoundError, ValidationError } = require('../middleware/errorHandler');

// ----------------------------------------------------------
// ARMAZENAMENTO EM MEMÓRIA
// ----------------------------------------------------------

/**
 * Array que armazena todos os livros em memória.
 *
 * POR QUE ARRAY E NÃO OBJETO?
 * ----------------------------
 * Escolhemos array porque:
 * - A ordem de inserção é preservada (útil para listagem)
 * - Permite filtragem eficiente com métodos como filter() e findIndex()
 * - É mais simples de serializar para JSON
 * Um objeto com chaves numéricas também funcionaria, mas arrays são mais
 * idiomáticos em JavaScript para coleções ordenadas.
 *
 * INICIALIZAÇÃO COM DADOS DE EXEMPLO
 * -----------------------------------
 * Populamos com dados fictícios para que a API já funcione ao ser iniciada,
 * sem necessidade de criar registros manualmente primeiro.
 */
const books = [
  {
    id: 1,
    title: 'O Senhor dos Anéis',
    author: 'J.R.R. Tolkien',
    year: 1954,
    genre: 'Fantasia',
    createdAt: new Date('2024-01-15T10:00:00Z')
  },
  {
    id: 2,
    title: '1984',
    author: 'George Orwell',
    year: 1949,
    genre: 'Distopia',
    createdAt: new Date('2024-01-16T14:30:00Z')
  },
  {
    id: 3,
    title: 'Dom Casmurro',
    author: 'Machado de Assis',
    year: 1899,
    genre: 'Romance',
    createdAt: new Date('2024-01-17T09:15:00Z')
  }
];

/**
 * Contador para gerar IDs únicos automaticamente.
 *
 * POR QUE UM CONTADOR?
 * --------------------
 * Em vez de usar timestamps ou UUIDs, usamos um contador simples porque:
 * - Garante IDs sequenciais e legíveis
 * - É suficiente para um exemplo educacional
 * - Evita colisões de ID sem complexidade adicional
 * Em produção,推荐使用 UUID v4 ou snowflake IDs.
 */
let nextId = 4; // Começa após os IDs dos dados de exemplo

// ----------------------------------------------------------
// FUNÇÕES DE VALIDAÇÃO
// ----------------------------------------------------------

/**
 * Valida os campos obrigatórios e o formato de um livro.
 *
 * POR QUE VALIDAR AQUI E NÃO NAS ROTAS?
 * --------------------------------------
 * A validação pertence à camada de serviço porque:
 * 1. É uma regra de negócio, não uma preocupação de HTTP
 * 2. Pode ser reutilizada por diferentes fontes (API, CLI, worker)
 * 3. Mantém as rotas limpas e focadas em mapeamento HTTP
 *
 * @param {Object} bookData - Dados do livro a serem validados
 * @returns {Array<Object>} Lista de erros de validação (vazia se válido)
 */
function validateBook(bookData) {
  const errors = [];

  // Título é obrigatório e deve ser uma string não vazia
  if (!bookData.title || typeof bookData.title !== 'string' || bookData.title.trim() === '') {
    errors.push({ field: 'title', message: 'O título é obrigatório e deve ser uma string não vazia' });
  }

  // Autor é obrigatório e deve ser uma string não vazia
  if (!bookData.author || typeof bookData.author !== 'string' || bookData.author.trim() === '') {
    errors.push({ field: 'author', message: 'O autor é obrigatório e deve ser uma string não vazia' });
  }

  // Ano é opcional, mas se fornecido, deve ser um número inteiro positivo
  if (bookData.year !== undefined && bookData.year !== null) {
    if (typeof bookData.year !== 'number' || !Number.isInteger(bookData.year)) {
      errors.push({ field: 'year', message: 'O ano deve ser um número inteiro' });
    } else if (bookData.year < 1000 || bookData.year > new Date().getFullYear() + 1) {
      errors.push({ field: 'year', message: `O ano deve estar entre 1000 e ${new Date().getFullYear() + 1}` });
    }
  }

  // Gênero é opcional, mas se fornecido, deve ser uma string
  if (bookData.genre !== undefined && bookData.genre !== null) {
    if (typeof bookData.genre !== 'string' || bookData.genre.trim() === '') {
      errors.push({ field: 'genre', message: 'O gênero deve ser uma string não vazia' });
    }
  }

  return errors;
}

// ----------------------------------------------------------
// OPERAÇÕES CRUD (Create, Read, Update, Delete)
// ----------------------------------------------------------

/**
 * Lista todos os livros com suporte a filtragem opcional.
 *
 * POR QUE FILTRAGEM VIA QUERY PARAMS?
 * ------------------------------------
 * Seguimos a convenção REST de usar query parameters para filtragem:
 * - /books?author=Orwell → filtra por autor
 * - /books?genre=Fantasia → filtra por gênero
 * - /books?year=1954 → filtra por ano
 * Isso mantém a URL semântica e permite combinações de filtros.
 *
 * @param {Object} [filters={}] - Filtros opcionais aplicados aos livros
 * @param {string} [filters.author] - Filtrar por autor (case-insensitive)
 * @param {string} [filters.genre] - Filtrar por gênero (case-insensitive)
 * @param {number} [filters.year] - Filtrar por ano exato
 * @returns {Array<Object>} Lista de livros que correspondem aos filtros
 */
function getAllBooks(filters = {}) {
  let result = [...books]; // Criamos cópia para não mutar o array original

  // Aplica filtro por autor se fornecido (case-insensitive)
  if (filters.author) {
    const authorLower = filters.author.toLowerCase();
    result = result.filter(book => book.author.toLowerCase().includes(authorLower));
  }

  // Aplica filtro por gênero se fornecido (case-insensitive)
  if (filters.genre) {
    const genreLower = filters.genre.toLowerCase();
    result = result.filter(book => book.genre && book.genre.toLowerCase() === genreLower);
  }

  // Aplica filtro por ano se fornecido
  if (filters.year) {
    result = result.filter(book => book.year === parseInt(filters.year, 10));
  }

  return result;
}

/**
 * Busca um livro pelo seu ID.
 *
 * POR QUE LANÇAR NotFoundError?
 * -----------------------------
 * Em vez de retornar null ou undefined quando o livro não é encontrado,
 * lançamos NotFoundError. Isso permite que o middleware de erros capture
 * a exceção e responda com 404 automaticamente, mantendo as rotas limpas.
 *
 * @param {number} id - O ID do livro a ser buscado
 * @returns {Object} O livro encontrado
 * @throws {NotFoundError} Se o livro não for encontrado
 */
function getBookById(id) {
  const book = books.find(book => book.id === id);

  if (!book) {
    throw new NotFoundError(`Livro com ID ${id} não encontrado`);
  }

  return book;
}

/**
 * Cria um novo livro no armazenamento.
 *
 * POR QUE USAR SPREAD OPERATOR?
 * ------------------------------
 * Usamos {...bookData} para criar uma cópia dos dados do cliente, evitando
 * que referências externas modifiquem o objeto armazenado. Isso é uma prática
 * de imutabilidade que previne bugs de side-effects.
 *
 * @param {Object} bookData - Dados do novo livro (sem id nem createdAt)
 * @returns {Object} O livro criado com id e createdAt gerados automaticamente
 */
function createBook(bookData) {
  const newBook = {
    id: nextId++, // Incrementa o contador e atribui o valor atual
    ...bookData,  // Espalha todos os campos fornecidos pelo cliente
    createdAt: new Date() // Registra o timestamp de criação
  };

  books.push(newBook); // Adiciona ao array de armazenamento
  return newBook;
}

/**
 * Atualiza um livro existente com novos dados.
 *
 * POR QUE USAR PUT E NÃO PATCH?
 * ------------------------------
 * PUT substitui o recurso inteiro — todos os campos obrigatórios devem ser
 * enviados. Se quiséssemos atualizar apenas campos específicos, usaríamos
 * PATCH. Para este exemplo, PUT é mais simples de implementar e documentar.
 *
 * @param {number} id - O ID do livro a ser atualizado
 * @param {Object} updateData - Novos dados para o livro (campos opcionais)
 * @returns {Object} O livro atualizado
 * @throws {NotFoundError} Se o livro não for encontrado
 */
function updateBook(id, updateData) {
  const bookIndex = books.findIndex(book => book.id === id);

  if (bookIndex === -1) {
    throw new NotFoundError(`Livro com ID ${id} não encontrado`);
  }

  // Cria uma cópia do livro existente e aplica as atualizações
  const updatedBook = {
    ...books[bookIndex], // Mantém todos os campos existentes
    ...updateData,       // Sobrescreve com os novos valores (campos fornecidos)
    id: books[bookIndex].id, // Garante que o ID não seja alterado
    createdAt: books[bookIndex].createdAt // Garante que o timestamp original seja mantido
  };

  // Atualiza o array com o livro modificado
  books[bookIndex] = updatedBook;
  return updatedBook;
}

/**
 * Exclui um livro do armazenamento pelo seu ID.
 *
 * POR QUE USAR FILTER EM VEZ DE SPICE?
 * -------------------------------------
 * Usamos filter() porque é imutável (não altera o array original diretamente)
 * e mais legível. Em arrays pequenos como este, a diferença de performance
 * é irrelevante. Para arrays grandes, splice() seria mais eficiente.
 *
 * @param {number} id - O ID do livro a ser excluído
 * @returns {boolean} true se o livro foi encontrado e excluído, false caso contrário
 * @throws {NotFoundError} Se o livro não for encontrado
 */
function deleteBook(id) {
  const bookIndex = books.findIndex(book => book.id === id);

  if (bookIndex === -1) {
    throw new NotFoundError(`Livro com ID ${id} não encontrado`);
  }

  // Cria um novo array sem o livro excluído
  books.splice(bookIndex, 1);
  return true;
}

/**
 * Retorna estatísticas agregadas sobre os livros armazenados.
 *
 * POR QUE ESTA FUNÇÃO?
 * --------------------
 * Estatísticas são um recurso de leitura que não se encaixa no padrão CRUD.
 * Criamos uma função dedicada para calcular métricas como total de livros,
 * média de anos de publicação, distribuição por gênero, etc.
 *
 * @returns {Object} Estatísticas dos livros
 */
function getStats() {
  const totalBooks = books.length;

  // Calcula a média de anos de publicação (se houver livros)
  const averageYear = totalBooks > 0
    ? Math.round(books.reduce((sum, book) => sum + book.year, 0) / totalBooks)
    : 0;

  // Conta a distribuição por gênero
  const genreDistribution = books.reduce((acc, book) => {
    const genre = book.genre || 'Sem gênero';
    acc[genre] = (acc[genre] || 0) + 1;
    return acc;
  }, {});

  // Encontra o autor com mais livros
  const authorCounts = books.reduce((acc, book) => {
    acc[book.author] = (acc[book.author] || 0) + 1;
    return acc;
  }, {});

  const mostProlificAuthor = Object.entries(authorCounts)
    .sort((a, b) => b[1] - a[1])[0]?.[0] || 'N/A';

  return {
    totalBooks,
    averageYear,
    genreDistribution,
    mostProlificAuthor
  };
}

// ----------------------------------------------------------
// EXPORTAÇÕES
// ----------------------------------------------------------

module.exports = {
  getAllBooks,
  getBookById,
  createBook,
  updateBook,
  deleteBook,
  getStats,
  validateBook
};
