/**
 * ============================================================
 *  ROTAS DA API DE LIVROS
 * ============================================================
 *
 * POR QUE ARQUIVO DE ROTAS SEPARADO?
 * ----------------------------------
 * Separar rotas em arquivos distintos segue o princípio de separação de
 * preocupações. O arquivo app.js fica responsável apenas por configurar o
 * servidor, enquanto as rotas definem a interface HTTP da API. Isso facilita:
 * - Encontrar e modificar endpoints específicos
 * - Adicionar novas rotas sem poluir o arquivo principal
 * - Testar rotas isoladamente
 *
 * POR QUE EXPRESS.Router()?
 * -------------------------
 * O Router do Express permite agrupar rotas com um prefixo comum (/books)
 * e middlewares específicos. Isso cria uma "mini-aplicação" dentro da aplicação
 * principal, tornando o código mais modular e organizado.
 * ============================================================
 */

const express = require('express');
const router = express.Router(); // Cria um roteador isolado para as rotas de livros

// Importa os serviços (lógica de negócio) e utilitários de erro
const {
  getAllBooks,
  getBookById,
  createBook,
  updateBook,
  deleteBook,
  validateBook
} = require('../services/bookService');
const { validateId } = require('../middleware/errorHandler');

// ----------------------------------------------------------
// GET /books — LISTAR TODOS OS LIVROS COM FILTRAGEM
// ----------------------------------------------------------

/**
 * @route   GET /books
 * @desc    Lista todos os livros com suporte a filtragem opcional
 * @access  Public
 *
 * QUERY PARAMETERS (opcionais):
 * - author: string — Filtra por autor (busca parcial, case-insensitive)
 * - genre: string — Filtra por gênero (correspondência exata, case-insensitive)
 * - year: number — Filtra por ano de publicação
 *
 * @example <caption>Exemplo de requisição curl</caption>
 *   # Listar todos os livros
 *   curl http://localhost:3000/books
 *
 *   # Filtrar por autor
 *   curl "http://localhost:3000/books?author=tolkien"
 *
 *   # Filtrar por gênero e ano
 *   curl "http://localhost:3000/books?genre=fantasia&year=1954"
 *
 * @example <caption>Resposta de sucesso (200 OK)</caption>
 *   {
 *     "success": true,
 *     "count": 3,
 *     "data": [
 *       {
 *         "id": 1,
 *         "title": "O Senhor dos Anéis",
 *         "author": "J.R.R. Tolkien",
 *         "year": 1954,
 *         "genre": "Fantasia",
 *         "createdAt": "2024-01-15T10:00:00.000Z"
 *       }
 *     ]
 *   }
 */
router.get('/books', (req, res) => {
  // Extrai os parâmetros de query da URL (ex: ?author=Orwell&genre=Fantasia)
  const { author, genre, year } = req.query;

  // Constrói o objeto de filtros apenas com os parâmetros fornecidos
  const filters = {};
  if (author) filters.author = author;
  if (genre) filters.genre = genre;
  if (year) filters.year = year;

  // Chama o serviço para obter os livros filtrados
  const books = getAllBooks(filters);

  // Responde com a lista de livros e contagem
  res.json({
    success: true,
    count: books.length,
    data: books
  });
});

// ----------------------------------------------------------
// GET /books/stats — RETORNAR ESTATÍSTICAS
// ----------------------------------------------------------

/**
