  });
});

// ----------------------------------------------------------
// GET /books/:id — OBTER LIVRO POR ID
// ----------------------------------------------------------

/**
 * @route   GET /books/:id
 * @desc    Busca um livro específico pelo seu ID numérico
 * @access  Public
 *
 * PARAMETROS DE URL:
 * - id: number — ID do livro (deve ser um número inteiro positivo)
