 *   }
 */
router.get('/books/:id', (req, res) => {
  // Valida o ID antes de prosseguir — lança InvalidIdError se inválido
  const id = validateId(req.params.id);

  // Chama o serviço para buscar o livro — lança NotFoundError se não existir
  const book = getBookById(id);

  res.json({
    success: true,
    data: book
  });
});

// ----------------------------------------------------------
// POST /books — CRIAR NOVO LIVRO
// ----------------------------------------------------------

/**
 * @route   POST /books
 * @desc    Cria um novo livro no sistema
 * @access  Public
 *
 * CORPO DA REQUISIÇÃO (JSON):
 * - title: string — Título do livro (obrigatório)
 * - author: string — Autor do livro (obrigatório)
 * - year: number — Ano de publicação (opcional)
 * - genre: string — Gênero literário (opcional)
 *
 * @example <caption>Exemplo de requisição curl</caption>
 *   curl -X POST http://localhost:3000/books \
 *     -H "Content-Type: application/json" \
 *     -d '{"title": "Admirável Mundo Novo", "author": "Aldous Huxley", "year": 1932, "genre": "Distopia"}'
 *
 * @example <caption>Resposta de sucesso (201 Created)</caption>
 *   {
 *     "success": true,
 *     "data": {
 *       "id": 4,
 *       "title": "Admirável Mundo Novo",
 *       "author": "Aldous Huxley",
 *       "year": 1932,
 *       "genre": "Distopia",
 *       "createdAt": "2024-06-15T12:00:00.000Z"
 *     }
 *   }
 *
 * @example <caption>Resposta de erro (400 Bad Request)</caption>
 *   {
 *     "success": false,
 *     "error": "ValidationError",
 *     "message": "Dados inválidos para criação do livro",
 *     "details": [
 *       { "field": "title", "message": "O título é obrigatório" }
 *     ]
 *   }
 */
router.post('/books', (req, res) => {
  // Extrai os dados do corpo da requisição
  const { title, author, year, genre } = req.body;

  // Valida os dados antes de criar o livro
  const validationErrors = validateBook({ title, author, year, genre });

  if (validationErrors.length > 0) {
    // Lança ValidationError com todos os erros coletados
    throw new Error('Dados inválidos para criação do livro');
  }

  // Cria o livro no serviço e obtém o objeto completo com id gerado
  const book = createBook({ title, author, year, genre });

  // Responde com 201 (Created) indicando que o recurso foi criado com sucesso
  res.status(201).json({
    success: true,
    data: book
  });
});

