 * @access  Public
 *
 * PARAMETROS DE URL:
 * - id: number — ID do livro a ser atualizado
 *
 * CORPO DA REQUISIÇÃO (JSON):
 * - title: string — Novo título (obrigatório)
 * - author: string — Novo autor (obrigatório)
 * - year: number — Novo ano de publicação (opcional)
 * - genre: string — Novo gênero (opcional)
 *
 * NOTA: PUT substitui o recurso inteiro. Todos os campos obrigatórios devem
 * ser enviados, mesmo que não estejam mudando. Para atualizações parciais,
 * use PATCH no futuro.
 *
 * @example <caption>Exemplo de requisição curl</caption>
 *   curl -X PUT http://localhost:3000/books/1 \
 *     -H "Content-Type: application/json" \
 *     -d '{"title": "O Senhor dos Anéis - Edição Ilustrada", "author": "J.R.R. Tolkien", "year": 1954, "genre": "Fantasia"}'
 *
 * @example <caption>Resposta de sucesso (200 OK)</caption>
 *   {
 *     "success": true,
 *     "data": {
 *       "id": 1,
 *       "title": "O Senhor dos Anéis - Edição Ilustrada",
 *       "author": "J.R.R. Tolkien",
 *       "year": 1954,
 *       "genre": "Fantasia",
 *       "createdAt": "2024-01-15T10:00:00.000Z"
 *     }
 *   }
 */
router.put('/books/:id', (req, res) => {
