  const id = validateId(req.params.id);

  // Extrai os dados de atualização do corpo
  const { title, author, year, genre } = req.body;

  // Valida os dados antes de atualizar
  const validationErrors = validateBook({ title, author, year, genre });

  if (validationErrors.length > 0) {
    throw new Error('Dados inválidos para atualização do livro');
  }

  // Atualiza o livro no serviço
  const updatedBook = updateBook(id, { title, author, year, genre });

  res.json({
