```javascript
/**
 * ============================================================
 *  APLICAÇÃO PRINCIPAL — CONFIGURAÇÃO DO SERVIDOR EXPRESS
 * ============================================================
 *
 * POR QUE ESTA ESTRUTURA?
 * -----------------------
 * O arquivo app.js é o ponto de entrada da aplicação. Ele:
 * 1. Configura o Express com middlewares globais (JSON parsing, CORS)
 * 2. Registra as rotas importadas do arquivo de rotas
 * 3. Adiciona o middleware de tratamento de erros por último
 * 4. Inicia o servidor ouvindo uma porta específica
 *
 * POR QUE USAR async/await?
 * -------------------------
 * Embora esta API não faça requisições assíncronas (uso array em memória),
 * usamos a estrutura que suporta async/await para preparar o código para
 * futuras integrações com banco de dados. O Express suporta funções de rota
 * assíncronas e encadeia automaticamente os erros para o middleware de erro.
 * ============================================================
 */

const express = require('express');

// Importa o roteador de livros (todas as rotas CRUD)
const bookRoutes = require('./routes/books');

// Importa o middleware de tratamento de erros
const { errorHandler } = require('./middleware/errorHandler');

// ----------------------------------------------------------
// CONFIGURAÇÃO DO SERVIDOR
// ----------------------------------------------------------

/**
 * Cria a instância do aplicativo Express.
 *
 * O Express é um framework minimalista que fornece:
 * - Roteamento (mapeamento de URLs para handlers)
 * - Middlewares (funções que interceptam requisições/respostas)
 * - Parsing automático de corpos de requisição
 */
const app = express();

// ----------------------------------------------------------
// MIDDLEWARES GLOBAIS
// ----------------------------------------------------------

/**
 * Middleware para parsing de JSON no corpo das requisições.
 *
 * POR QUE ESTE MIDDLEWARE?
 * ------------------------
 * Sem este middleware, req.body seria undefined. O Express não faz parsing
 * automático de JSON desde a versão 4.16+. Este middleware converte o corpo
 * da requisição (string JSON) em um objeto JavaScript.
 */
app.use(express.json());

/**
 * Middleware para habilitar CORS (Cross-Origin Resource Sharing).
 *
 * POR QUE CORS?
 * -------------
 * Por padrão, navegadores bloqueiam requisições de origens diferentes.
 * Este middleware permite que a API seja acessada por aplicações frontend
 * hospedadas em domínios diferentes (ex: React rodando em localhost:3000
 * consumindo esta API em localhost:3001).
 */
app.use((req, res, next) => {
  // Permite requisições de qualquer origem
  res.header('Access-Control-Allow-Origin', '*');
  // Permite os métodos HTTP comuns
  res.header('Access-Control-Allow-Methods', 'GET, POST, PUT, DELETE, OPTIONS');
  // Permite headers personalizados (como Content-Type)
  res.header('Access-Control-Allow-Headers', 'Content-Type, Authorization');

  // Responde imediatamente a requisições OPTIONS (preflight do CORS)
  if (req.method === 'OPTIONS') {
    return res.sendStatus(200);
  }

  next(); // Passa para o próximo middleware/rota
});

// ----------------------------------------------------------
// REGISTRO DAS ROTAS
// ----------------------------------------------------------

/**
 * Registra as rotas de livros com o prefixo /books.
 *
 * POR QUE USAR O ROTEADOR?
 * ------------------------
 * Ao usar bookRoutes, todas as rotas definidas em routes/books.js são
 * automaticamente prefixadas com /books. Isso significa que:
 * - router.get('/books') → fica disponível como GET /books
 * - router.get('/stats') → fica disponível como GET /books/stats
 * - router.get('/:id') → fica disponível como GET /books/:id
 *
 * Isso evita repetição do prefixo em cada definição de rota.
 */
app.use('/books', bookRoutes);

// ----------------------------------------------------------
// ROTA DE HEALTH CHECK (BÔNUS)
// ----------------------------------------------------------

/**
 * @route   GET /
 * @desc    Health check — verifica se o servidor está respondendo
 * @access  Public
 *
 * Esta rota é útil para:
 * - Monitoramento de saúde do serviço (load balancers, Kubernetes)
 * - Testes rápidos de conectividade
 * - Verificação de que o servidor iniciou corretamente
 */
app.get('/', (req, res) => {
  res.json({
    success: true,
    message: 'API de Livros está rodando!',
    endpoints: {
      docs: 'http://localhost:3001/books',
      stats: 'http://localhost:3001/books/stats'
    }
  });
});

// ----------------------------------------------------------
// ROTA 404 PARA RECURSOS NÃO ENCONTRADOS
// ----------------------------------------------------------

/**
 * Middleware para lidar com rotas não definidas.
 *
 * POR QUE ESTE MIDDLEWARE?
 * ------------------------
 * Se um cliente acessar uma URL que não corresponde a nenhuma rota registrada,
 * este middleware captura a requisição e responde com 404. Sem ele, o Express
 * simplesmente fecharia a conexão sem resposta, o que é confuso para os clientes.
 */
app.use((req, res) => {
  res.status(404).json({
    success: false,
    error: 'Not Found',
    message: `Rota ${req.method} ${req.originalUrl} não encontrada`
  });
});

// ----------------------------------------------------------
// MIDDLEWARE DE TRATAMENTO DE ERROS (DEVE SER O ÚLTIMO)
// ----------------------------------------------------------

/**
 * Registra o middleware de tratamento de erros por último.
 *
 * POR QUE POR ÚLTIMO?
 * -------------------
 * O Express executa middlewares na ordem em que são registrados. O middleware
 * de erro deve ser o último porque:
 * 1. Precisa capturar erros de TODOS os middlewares e rotas anteriores
 * 2. Se registrado antes das rotas, interceptaria requisições normais
 * 3. A assinatura com 4 parâmetros (err, req, res, next) identifica
 *    automaticamente como middleware de erro pelo Express
 */
app.use(errorHandler);

// ----------------------------------------------------------
// INICIALIZAÇÃO DO SERVIDOR
// ----------------------------------------------------------

/**
 * Porta onde o servidor irá ouvir.
 *
 * POR QUE 3001?
 * -------------
 * Usamos a porta 3001 para evitar conflito com aplicações frontend comuns
 * (que geralmente usam 3000). Em produção, esta variável seria lida do
 * ambiente (process.env.PORT) para flexibilidade.
 */
const PORT = process.env.PORT || 3001;

/**
 * Inicia o servidor e registra o callback de inicialização.
 *
 * O método listen() é assíncrono por natureza (opera com I/O de rede).
 * Usamos uma função arrow para manter o escopo léxico do PORT.
 */
app.listen(PORT, () => {
  console.log(`╔══════════════════════════════════════════════════╗`);
  console.log(`║     API de Livros REST — Servidor Iniciado!      ║`);
  console.log(`╠══════════════════════════════════════════════════╣`);
  console.log(`║  Porta: ${PORT}                                       ║`);
  console.log(`║  Base URL: http://localhost:${PORT}                  ║`);
  console.log(`║                                                  ║`);
  console.log(`║  Endpoints disponíveis:                          ║`);
  console.log(`║    GET    /              → Health check          ║`);
  console.log(`║    GET    /books         → Listar livros         ║`);
  console.log(`║    GET    /books/stats   → Estatísticas          ║`);
  console.log(`║    GET    /books/:id     → Buscar livro por ID   ║`);
  console.log(`║    POST   /books         → Criar livro           ║`);
  console.log(`║    PUT    /books/:id     → Atualizar livro       ║`);
  console.log(`║    DELETE /books/:id     → Excluir livro         ║`);
  console.log(`╚══════════════════════════════════════════════════╝`);
});

// ----------------------------------------------------------
// EXPORTAÇÃO (para testes)
// ----------------------------------------------------------

module.exports = app;
