## 3. File: `server.js` — Application Entry Point

```js
/**
 * server.js
 *
 * This file bootstraps the Express application, mounts middleware,
 * registers route modules, and starts listening on port 3000.
 *
 * Architecture notes:
 * - Middleware is applied in a logical order: body parsing → routing → error handling.
 * - Using `express.json()` allows us to read JSON payloads from POST/PUT requests.
 * - Routes are mounted under `/api/v1` so the API can be versioned without breaking clients.
 */

const express = require('express');
const bookRoutes = require('./routes/books');
const statsRoutes = require('./routes/stats');
const { errorHandler } = require('./middleware/errorHandler');

// Create an Express application instance.
const app = express();

// ──────────────────────────────────────────────
// Middleware
// ──────────────────────────────────────────────

/**
 * Body‑parser middleware.
 * Parses incoming JSON request bodies and makes them available on `req.body`.
 * Without this, POST/PUT payloads would be raw strings.
 */
app.use(express.json());

// Optional: log every request for debugging (useful during development)
app.use((req, res, next) => {
  console.log(`[${new Date().toISOString()}] ${req.method} ${req.url}`);
  next();
});

// ──────────────────────────────────────────────
// Routes
// ──────────────────────────────────────────────

/**
 * Mount book CRUD routes under /api/v1/books.
 * All endpoints defined in routes/books.js become available here.
 */
app.use('/api/v1/books', bookRoutes);

/**
 * Mount statistics route under /api/v1/stats.
 * Returns aggregate data about the current book collection.
 */
app.use('/api/v1/stats', statsRoutes);

// ──────────────────────────────────────────────
// Root endpoint (health check)
// ──────────────────────────────────────────────

/**
 * GET /api/v1
 * Simple health‑check endpoint to verify the server is running.
 */
app.get('/api/v1', (_req, res) => {
  res.json({ message: 'Book REST API is running' });
});

// ──────────────────────────────────────────────
// Error‑handling middleware (must be last)
// ──────────────────────────────────────────────

/**
 * Express error‑handling middleware.
 * Catches any error thrown in previous middleware/routes and returns a consistent JSON response.
 * The `next(err)` pattern is the standard way to signal an error in Express.
 */
app.use(errorHandler);

// ──────────────────────────────────────────────
// Start server
// ──────────────────────────────────────────────

const PORT = process.env.PORT || 3000;

app.listen(PORT, () => {
  console.log(`Server listening on http://localhost:${PORT}`);
});
```

**Key points**  
- `express.json()` is essential for reading JSON bodies.  
- Routes are namespaced under `/api/v1` so you can later introduce v2 without breaking existing clients.  
- The error‑handling middleware **must** be registered after all routes; otherwise it would intercept normal responses instead of errors.

