## 5. File: `routes/books.js` — Book CRUD Routes

```js
/**
 * routes/books.js
 *
 * Implements all book‑related HTTP endpoints:
 *   GET    /books          – list with optional filters
 *   GET    /books/:id      – retrieve a single book
 *   POST   /books          – create a new book
 *   PUT    /books/:id      – fully update an existing book
 *   DELETE /books/:id      – remove a book
 *
 * Data store: in‑memory array `books`. Each element is a plain object with fields:
 *   { id, title, author, genre, publishedYear, rating }
 *
 * Validation rules (applied to POST/PUT bodies):
 *   - title, author, genre are required strings.
 *   - publishedYear must be an integer between 1000 and the current year.
 *   - rating must be a number between 0 and 5 (inclusive).
 */

const { AppError } = require('../middleware/errorHandler');

// ──────────────────────────────────────────────
// In‑memory data store
// ──────────────────────────────────────────────

/**
 * Array of book objects.
 * Using an array gives O(1) access by index, but we search by `id` with `.find()`.
 * For a small educational dataset this is perfectly fine; a real app would use a DB.
 */
let books = [
  { id: 1, title: 'The Great Gatsby', author: 'F. Scott Fitzgerald', genre: 'Fiction', publishedYear: 1925, rating: 4.5 },
  { id: 2, title: 'To Kill a Mockingbird', author: 'Harper Lee', genre: 'Fiction', publishedYear: 1960, rating: 4.8 },
  { id: 3, title: 'A Brief History of Time', author: 'Stephen Hawking', genre: 'Science', publishedYear: 1988, rating: 4.7 },
];

// Helper to generate the next integer ID (simple auto‑increment)
let nextId = 4;

/**
 * Express router instance.
 * Using `express.Router()` keeps route definitions self‑contained and reusable.
 */
const router = require('express').Router();

// ──────────────────────────────────────────────
// Validation helpers
// ──────────────────────────────────────────────

/**
 * Validates a book payload (used by POST and PUT).
 * Throws an AppError(400) with a descriptive message if validation fails.
 *
 * @param {object} body - The request body to validate.
 */
function validateBookBody(body) {
  const { title, author, genre, publishedYear, rating } = body;

  // All three core fields are required
  if (!title || typeof title !== 'string' || title.trim() === '') {
    throw new AppError('Title is required and must be a non‑empty string', 400);
  }
  if (!author || typeof author !== 'string' || author.trim() === '') {
    throw new AppError('Author is required and must be a non‑empty string', 400);
  }
  if (!genre || typeof genre !== 'string' || genre.trim() === '') {
    throw new AppError('Genre is required and must be a non‑empty string', 400);
  }

  // publishedYear: optional, but if provided must be an integer in a reasonable range
  if (publishedYear !== undefined) {
    const year = Number(publishedYear);
    const currentYear = new Date().getFullYear();
    if (!Number.isInteger(year) || year < 1000 || year > currentYear) {
      throw new AppError(`publishedYear must be an integer between 1000 and ${currentYear}`, 400);
    }
  }

  // rating: optional, but if provided must be a number in [0, 5]
  if (rating !== undefined) {
    const r = Number(rating);
    if (typeof r !== 'number' || isNaN(r) || r < 0 || r > 5) {
      throw new AppError('rating must be a number between 0 and 5', 400);
    }
  }
}

// ──────────────────────────────────────────────
// GET /books – List all books (with optional filters)
// ──────────────────────────────────────────────

/**
 * @openapi
 * /books:
 *   get:
 *     summary: List all books
 *     parameters:
 *       - in: query
 *         name: genre
 *         schema: { type: string }
 *         description: Filter by genre (case‑insensitive)
 *       - in: query
 *         name: minRating
 *         schema: { type: number, minimum: 0, maximum: 5 }
 *         description: Minimum rating filter
 *     responses:
 *       200:
 *         description: A list of books
 */
router.get('/', (_req, res) => {
  const { genre, minRating } = _req.query;

  // Start with the full array and apply filters sequentially.
  let result = books;

  if (genre) {
    // Case‑insensitive substring match on genre
    const lowerGenre = genre.toLowerCase();
    result = result.filter((book) => book.genre.toLowerCase().includes(lowerGenre));
  }

  if (minRating !== undefined) {
    const min = Number(minRating);
    if (!isNaN(min)) {
      result = result.filter((book) => book.rating >= min);
    }
  }

  // Return the filtered list with a 200 OK status.
  res.json({ count: result.length, data: result });
});

// ──────────────────────────────────────────────
// GET /books/:id – Get a single book by ID
// ──────────────────────────────────────────────

/**
 * @openapi
 * /books/{id}:
 *   get:
 *     summary: Get a book by its ID
 *     parameters:
 *       - in: path
 *         name: id
 *         required: true
 *         schema: { type: integer }
 *     responses:
 *       200:
 *         description: The requested book
 *       404:
 *         description: Book not found
 */
router.get('/:id', (req, res) => {
  const id = Number(req.params.id);

  // `.find()` returns the first matching element or undefined.
  const book = books.find((b) => b.id === id);

  if (!book) {
    throw new AppError(`Book with id ${id} not found`, 404);
  }

  res.json(book);
});

// ──────────────────────────────────────────────
// POST /books – Create a new book
// ──────────────────────────────────────────────

/**
 * @openapi
 * /books:
 *   post:
 *     summary: Create a new book
 *     requestBody:
 *       required: true
 *       content:
 *         application/json:
 *           schema:
 *             type: object
 *             required: [title, author, genre]
 *             properties:
 *               title: { type: string }
 *               author: { type: string }
 *               genre: { type: string }
 *               publishedYear: { type: integer }
 *               rating: { type: number }
 *     responses:
 *       201:
 *         description: Book created successfully
 *       400:
 *         description: Validation error
 */
router.post('/', (req, res) => {
  // Validate the incoming payload before touching the store.
  validateBookBody(req.body);

  const newBook = {
    id: nextId++,
    title: req.body.title.trim(),
    author: req.body.author.trim(),
    genre: req.body.genre.trim(),
    publishedYear: req.body.publishedYear,
    rating: req.body.rating,
  };

  books.push(newBook);

  // 201 Created is the standard status for successful resource creation.
  res.status(201).json(newBook);
});

// ──────────────────────────────────────────────
// PUT /books/:id – Fully update an existing book
// ──────────────────────────────────────────────

/**
 * @openapi
 * /books/{id}:
 *   put:
 *     summary: Replace an existing book completely
 *     parameters:
 *       - in: path
 *         name: id
 *         required: true
 *         schema: { type: integer }
 *     requestBody:
 *       required: true
 *       content:
 *         application/json:
 *           schema:
 *             type: object
 *             required: [title, author, genre]
 *             properties:
 *               title: { type: string }
 *               author: { type: string }
 *               genre: { type: string }
 *               publishedYear: { type: integer }
 *               rating: { type: number }
 *     responses:
 *       200:
 *         description: Book updated successfully
 *       400:
 *         description: Validation error
 *       404:
 *         description: Book not found
 */
router.put('/:id', (req, res) => {
  const id = Number(req.params.id);
  const index = books.findIndex((b) => b.id === id);

  if (index === -1) {
    throw new AppError(`Book with id ${id} not found`, 404);
  }

  // Validate the entire payload; PUT replaces the resource, so all required fields must be present.
  validateBookBody(req.body);

  const updatedBook = {
    id,
    title: req.body.title.trim(),
    author: req.body.author.trim(),
    genre: req.body.genre.trim(),
    publishedYear: req.body.publishedYear,
    rating: req.body.rating,
  };

  // Replace the old object in‑place.
  books[index] = updatedBook;

  res.json(updatedBook);
});

// ──────────────────────────────────────────────
// DELETE /books/:id – Remove a book
// ──────────────────────────────────────────────

/**
 * @openapi
 * /books/{id}:
 *   delete:
 *     summary: Delete a book by its ID
 *     parameters:
 *       - in: path
 *         name: id
 *         required: true
 *         schema: { type: integer }
 *     responses:
 *       204:
 *         description: Book deleted successfully (no content)
 *       404:
 *         description: Book not found
 */
router.delete('/:id', (req, res) => {
  const id = Number(req.params.id);
  const index = books.findIndex((b) => b.id === id);

  if (index === -1) {
    throw new AppError(`Book with id ${id} not found`, 404);
  }

  // `.splice()` removes the element and returns an array containing the removed item.
  books.splice(index, 1);

  // 204 No Content is appropriate when the response body is intentionally empty.
  res.status(204).end();
});

module.exports = router;
```

**Design notes**  
- **Validation before mutation**: We call `validateBookBody` early so invalid requests never touch the store.  
- **PUT vs PATCH**: This implementation uses full replacement (`PUT`). If you wanted partial updates, you’d use `PATCH` and merge only supplied fields.  
- **204 for DELETE**: Returning no body is the REST‑recommended status when deletion succeeds and there’s nothing to return.  
- **Query filtering**: The `genre` filter does a case‑insensitive substring match; `minRating` filters by numeric comparison. Both are optional, so you can combine them or omit either.

