## 6. File: `routes/stats.js` — Aggregate Statistics

```js
/**
 * routes/stats.js
 *
 * Provides a single endpoint that returns aggregate statistics about the book collection.
 * This demonstrates how to compute derived data without exposing raw store mutations.
 */

const { AppError } = require('../middleware/errorHandler');

// Import the shared in‑memory store from books.js.
// In a larger app you might extract this into a dedicated `store.js` module.
const { books } = require('./books');

/**
 * GET /stats
 *
 * Returns:
 *   - totalBooks: number of books in the collection
 *   - averageRating: mean rating rounded to 2 decimal places (0 if empty)
 *   - topGenres: array of genre names sorted by frequency (descending)
 *
 * @openapi
 * /stats:
 *   get:
 *     summary: Get collection statistics
 *     responses:
 *       200:
 *         description: Statistics object
 */
function getStats() {
  const totalBooks = books.length;

  if (totalBooks === 0) {
    return {
      totalBooks: 0,
      averageRating: 0,
      topGenres: [],
    };
  }

  // Compute average rating.
  const sumRatings = books.reduce((sum, book) => sum + book.rating, 0);
  const averageRating = parseFloat((sumRatings / totalBooks).toFixed(2));

  // Count occurrences of each genre.
  const genreCounts = {};
  for (const book of books) {
    genreCounts[book.genre] = (genreCounts[book.genre] || 0) + 1;
  }

  // Convert to array of `{ genre, count }` and sort descending by count.
  const topGenres = Object.entries(genreCounts)
    .map(([genre, count]) => ({ genre, count }))
    .sort((a, b) => b.count - a.count);

  return { totalBooks, averageRating, topGenres };
}

const router = require('express').Router();

router.get('/', (_req, res) => {
  // In a real app you might cache this result; here we compute on every request.
  const stats = getStats();
  res.json(stats);
});

module.exports = router;
```

**Why separate route?**  
- Keeps the main book routes focused on CRUD.  
- Statistics are read‑only and involve aggregation logic that doesn’t belong alongside mutation handlers.  
- If you later add authentication, you can protect `/stats` independently.

> **Note**: The `books` array is exported from `routes/books.js` so both route files share the same in‑memory store. In a larger project you’d move the store to a dedicated module (e.g., `store.js`) and import it everywhere.

