## Arquivo 2: `src/utils/errors.js`

```javascript
/**
 * ============================================================
 * Módulo de Classes de Erro Personalizadas
 * ============================================================
 *
 * POR QUE classes de erro personalizadas?
 * ----------------------------------------
 * Em vez de lançar objetos genéricos ({ message: '...' }),
 * criamos subclasses de Error que carregam informações
 * estruturadas (statusCode, isOperational). Isso permite que
 * o middleware de tratamento de erros tome decisões diferentes
 * com base no TIPO do erro, não apenas na mensagem.
 *
 * Convenção REST: códigos HTTP padronizados
 * - 400 Bad Request:      Erro do cliente — dados inválidos
 * - 404 Not Found:        Recurso inexistente
 * - 500 Internal Error:   Falha interna do servidor
 * ============================================================
 */

/**
 * Classe base para erros operacionais (esperados).
 * São erros que o servidor espera e pode tratar gracefulmente,
 * como "recurso não encontrado" ou "dados inválidos".
 */
class AppError extends Error {
  /**
   * @param {string} message - Descrição legível do erro
   * @param {number} statusCode - Código HTTP correspondente (padrão: 500)
   * @param {boolean} isOperational - Indica se é um erro esperado (true) ou bug (false)
   */
  constructor(message, statusCode = 500, isOperational = true) {
    super(message); // Chama o construtor da classe Error nativa

    // Captura o nome da classe para debugging com stack trace correto
    this.name = this.constructor.name;

    // Propriedades customizadas usadas pelo middleware de erros
    this.statusCode = statusCode;
    this.isOperational = isOperational;

    // Mantém a pilha de chamadas (stack) limpa e informativa
    Error.captureStackTrace(this, this.constructor);
  }
}

/**
 * Erro para requisições com dados inválidos.
 * Mapeia para HTTP 400 — o cliente enviou algo que não pôde ser processado.
 *
 * Exemplo de uso:
 *   if (!book.title) throw new ValidationError('Título é obrigatório');
 */
class ValidationError extends AppError {
  constructor(message) {
    super(message, 400, true); // 400 = Bad Request, isOperational = true
  }
}

/**
 * Erro para recurso não encontrado.
 * Mapeia para HTTP 404 — o recurso solicitado não existe no servidor.
 *
 * Exemplo de uso:
 *   if (!book) throw new NotFoundError('Livro com ID 99 não encontrado');
 */
class NotFoundError extends AppError {
  constructor(message) {
    super(message, 404, true); // 404 = Not Found, isOperational = true
  }
}

/**
 * Erro para recursos duplicados.
 * Mapeia para HTTP 409 — conflito com estado atual do servidor.
 *
 * Exemplo de uso:
 *   if (bookExists) throw new ConflictError('Já existe um livro com este ISBN');
 */
class ConflictError extends AppError {
  constructor(message) {
    super(message, 409, true); // 409 = Conflict, isOperational = true
  }
}

/**
 * Erro para falha interna do servidor.
 * Mapeia para HTTP 500 — algo inesperado aconteceu no servidor.
 *
 * Exemplo de uso:
 *   try { ... } catch (err) { throw new InternalError('Falha ao salvar'); }
 */
class InternalError extends AppError {
  constructor(message) {
    super(message, 500, false); // 500 = Internal Server Error, isOperational = false
  }
}

module.exports = {
  AppError,
  ValidationError,
  NotFoundError,
  ConflictError,
  InternalError,
};
```

> **Explicação:** As classes de erro personalizadas formam a base do tratamento estruturado de erros. A hierarquia `AppError → subclasse específica` permite que o middleware distinga entre erros operacionais (esperados, como 404) e erros não-operacionais (bugs reais, como 500). O campo `isOperational` é crucial: erros operacionais são logados com moderação para não poluir os logs de produção, enquanto erros não-operacionais disparam alertas completos.

