## Arquivo 3: `src/middleware/errorMiddleware.js`

```javascript
/**
 * ============================================================
 * Middleware de Tratamento de Erros
 * ============================================================
 *
 * POR QUE um middleware dedicado para erros?
 * ------------------------------------------
 * Express possui uma convenção especial para middlewares de erro:
 * funções com 4 parâmetros (err, req, res, next). Quando qualquer
 * middleware ou rota chama next(err), a execução pula diretamente
 * para este middleware, ignorando todos os middlewares intermediários.
 *
 * Isso centraliza o tratamento de erros em UM único lugar, evitando
 * repetição de lógica de resposta de erro em cada rota.
 *
 * Padrão async/await + Express:
 * ------------------------------------------
 * Como Express não lida nativamente com promessas rejeitadas,
 * criamos um wrapper (asyncHandler) que captura erros de promessas
 * e os encaminha para o middleware de erro via next(err).
 * ============================================================
 */

const { InternalError } = require('../utils/errors');

/**
 * Wrapper para funções assíncronas de rota.
 *
 * Express.js não captura automaticamente rejeições de promessas.
 * Se uma função async lança um erro, a promessa é rejeitada mas
 * o Express não sabe que deve chamar next(err). Este wrapper
 * resolve esse problema capturando o erro e passando para next().
 *
 * @param {Function} fn - Função assíncrona da rota
 * @returns {Function} Middleware Express encapsulado
 *
 * Exemplo de uso:
 *   router.get('/books/:id', asyncHandler(async (req, res) => { ... }));
 */
function asyncHandler(fn) {
  return (req, res, next) => {
    // Executa a função assíncrona e captura qualquer erro
    fn(req, res, next).catch(next);
    // .catch(next) é equivalente a:
    //   .catch(err => next(err))
    // Isso garante que erros de promessas cheguem ao middleware de erro
  };
}

/**
 * Middleware principal de tratamento de erros.
 *
 * Este middleware é registrado POR ÚLTIMO na pilha de middlewares
 * (após todas as rotas) para capturar erros de qualquer lugar.
 *
 * A assinatura com 4 parâmetros (err, req, res, next) é o que
 * identifica um middleware de erro no Express — se tiver 3 ou
 * menos parâmetros, o Express o trata como middleware normal.
 *
 * @param {Error} err - O erro lançado em alguma rota/middleware
 * @param {Object} req - Objeto de requisição do Express
 * @param {Object} res - Objeto de resposta do Express
 * @param {Function} next - Função next (não usada aqui)
 */
function errorHandler(err, req, res, next) {
  // Determina o código HTTP com base no tipo de erro
  const statusCode = err.statusCode || 500;

  // Em desenvolvimento, incluímos o stack trace completo para debugging
  // Em produção, ocultamos detalhes internos por segurança
  const isDevelopment = process.env.NODE_ENV !== 'production';

  // Monta a resposta de erro com formato consistente (JSON)
  const errorResponse = {
    success: false,           // Campo padrão indicando falha
    status: statusCode,       // Código HTTP
    message: err.message,     // Mensagem legível para o cliente
    ...(isDevelopment && { stack: err.stack }), // Stack trace apenas em dev
  };

  // Log do erro no servidor (sempre, independente do ambiente)
  // Usamos console.error para diferenciar de logs normais (console.log)
  if (err.isOperational === false) {
    // Erros não-operacionais (bugs) recebem log completo
    console.error(`[ERRO NÃO OPERACIONAL] ${err.name}:`, err.message);
    console.error(err.stack);
  } else {
    // Erros operacionais (404, 400, etc.) recebem log resumido
    console.warn(`[ERRO OPERACIONAL] ${statusCode} - ${err.message}`);
  }

  // Envia a resposta JSON padronizada
  res.status(statusCode).json(errorResponse);
}

module.exports = { asyncHandler, errorHandler };
```

> **Explicação:** O middleware de erros é um dos padrões mais importantes em APIs Express. A convenção de 4 parâmetros `(err, req, res, next)` é o que diferencia middlewares de erro de middlewares normais — o Express usa a propriedade `length` (número de parâmetros) para identificar middlewares de erro. O `asyncHandler` resolve um problema comum: express não trata promessas rejeitadas automaticamente, então funções async que lançam erros causariam vazamento de promessa não tratada (unhandled promise rejection).

