 *
 * POR QUE rotas organizadas em módulo separado?
 * ---------------------------------------------
 * Separar rotas por recurso (livros, usuários, etc.) segue o princípio
 * de responsabilidade única. Cada arquivo de rota é responsável apenas
 * pelas operações do seu recurso, tornando o código mais fácil de:
 *   - Manter e atualizar
 *   - Testar isoladamente
 *   - Escalonar em equipes maiores
 *
 * Convenções REST adotadas:
 *   GET    /books          → Lista todos os livros (com filtragem)
 *   GET    /books/:id      → Busca um livro por ID
 *   POST   /books          → Cria um novo livro
 *   PUT    /books/:id      → Atualiza completamente um livro
 *   DELETE /books/:id      → Exclui um livro
 *   GET    /stats          → Estatísticas agregadas
 *
 * Estrutura de dados em memória:
 * ---------------------------------------------
 * Usamos um array de objetos porque:
 *   1. Para fins educacionais, é mais simples e legível que um Map ou DB
 *   2. A ordem dos elementos é preservada (arrays mantêm ordenação)
 *   3. Operações como filter(), map(), find() são nativas e expressivas
 *   4. Em produção, substituiríamos por um banco de dados real
 *
 * Cada livro tem a seguinte estrutura:
 * {
 *   id: number,           // Identificador único auto-incrementado
 *   title: string,        // Título do livro (obrigatório)
 *   author: string,       // Autor (obrigatório)
 *   isbn: string,         // ISBN (opcional, deve ser único se fornecido)
 *   genre: string,        // Gênero literário
 *   year: number,         // Ano de publicação
 *   createdAt: string,    // Timestamp ISO da criação
 *   updatedAt: string     // Timestamp ISO da última atualização
 * }
 * ============================================================
 */

const express = require('express');

// Importa o wrapper asyncHandler para tratamento de promessas
const { asyncHandler } = require('../middleware/errorMiddleware');

// Importa as classes de erro personalizadas
const {
  ValidationError,
  NotFoundError,
  ConflictError,
} = require('../utils/errors');

// Cria um roteador Express — permite agrupar rotas com middleware específico
const router = express.Router();

// ============================================================
// ARMAZENAMENTO EM MEMÓRIA (Array)
// ============================================================
//
// POR QUE array e não objeto/Map?
// - Array preserva ordem de inserção (importante para listagens)
// - Suporta operações de busca linear com find/filter nativos
// - Simples de serializar e entender para fins educacionais
//
// O ID auto-incrementado garante unicidade sem necessidade de UUID
// ou dependências externas. Em produção, usaríamos um banco com
// sequences/auto-increment nativo.
// ============================================================

/**
 * Array que armazena todos os livros em memória.
 * Inicializado vazio — os dados persistem apenas durante o runtime do processo.
 */
let books = [];

/**
 * Contador para gerar IDs únicos auto-incrementados.
 * Começa em 1 e incrementa a cada novo livro criado.
 * Em um cenário real, o banco de dados gerencia isso automaticamente.
 */
let nextId = 1;

// ============================================================
// VALIDAÇÃO DE DADOS
// ============================================================
//
// POR QUE validar antes de processar?
// - Falha rápido (fail-fast): rejeita requisições inválidas o mais cedo possível
// - Segurança: previne injeção de dados maliciosos ou inconsistentes
// - UX: retorna mensagens de erro claras e específicas para o cliente
// ============================================================

/**
 * Valida os campos obrigatórios de um livro.
 *
 * @param {Object} data - Dados do livro a serem validados
 * @returns {void} Lança ValidationError se alguma validação falhar
 */
function validateBook(data) {
  // Verifica se o objeto foi fornecido
  if (!data || typeof data !== 'object') {
    throw new ValidationError('Corpo da requisição deve ser um objeto JSON');
  }

  // Título é obrigatório e deve ser string não vazia
  if (!data.title || typeof data.title !== 'string' || data.title.trim() === '') {
    throw new ValidationError('O campo "title" é obrigatório e deve ser uma string não vazia');
  }

  // Autor é obrigatório e deve ser string não vazia
  if (!data.author || typeof data.author !== 'string' || data.author.trim() === '') {
    throw new ValidationError('O campo "author" é obrigatório e deve ser uma string não vazia');
  }

  // ISBN, se fornecido, deve ser string
  if (data.isbn !== undefined && data.isbn !== null && typeof data.isbn !== 'string') {
    throw new ValidationError('O campo "isbn" deve ser uma string');
  }

  // Gênero, se fornecido, deve ser string
  if (data.genre !== undefined && data.genre !== null && typeof data.genre !== 'string') {
    throw new ValidationError('O campo "genre" deve ser uma string');
  }

  // Ano, se fornecido, deve ser número
  if (data.year !== undefined && data.year !== null) {
    if (!Number.isInteger(data.year)) {
      throw new ValidationError('O campo "year" deve ser um número inteiro');
    }
    if (data.year < 0 || data.year > new Date().getFullYear() + 1) {
      throw new ValidationError(`O campo "year" deve estar entre 0 e ${new Date().getFullYear() + 1}`);
    }
  }
}

/**
 * Valida o ID fornecido na URL.
 *
 * @param {*} id - Valor do parâmetro de rota
 * @returns {boolean} true se o ID é válido, lança erro caso contrário
 */
function validateId(id) {
  const numId = Number(id);
  if (!Number.isInteger(numId) || numId < 1) {
    throw new ValidationError('O parâmetro "id" deve ser um número inteiro positivo');
  }
  return numId;
}

// ============================================================
// GET /books — Listar todos os livros com filtragem opcional
// ============================================================
//
// POR QUE filtragem via query parameters?
// ---------------------------------------
// Query params são o padrão REST para filtros opcionais:
//   ?genre=ficcao        → Filtra por gênero
//   ?author=jk%20rowling → Filtra por autor (case-insensitive)
//   ?year=2023           → Filtra por ano exato
//   ?search=livro        → Busca textual em título e autor
//
// Isso mantém a URL legível e permite combinações de filtros.
// ============================================================

/**
 * @route   GET /books
 * @desc    Lista todos os livros com filtragem opcional
 * @access  Public
 *
 * Query Parameters (opcionais):
 *   - genre: string      → Filtra por gênero literário
 *   - author: string     → Filtra por autor (busca parcial, case-insensitive)
 *   - year: number       → Filtra por ano de publicação exato
 *   - search: string     → Busca textual em título e autor
 *
 * @example GET /books?genre=ficcao&author=tolkien
 * @example GET /books?search=senhor
 * @example GET /books (retorna todos)
 */
router.get(
  '/books',
  asyncHandler(async (req, res) => {
    // Começa com uma cópia do array para não mutar o original durante filtragem
    let result = [...books];

    const { genre, author, year, search } = req.query;

    // Aplica filtro por gênero (case-insensitive)
    if (genre) {
      result = result.filter(
        (book) => book.genre && book.genre.toLowerCase() === genre.toLowerCase()
      );
    }

    // Aplica filtro por autor (busca parcial, case-insensitive)
    if (author) {
      const authorLower = author.toLowerCase();
      result = result.filter((book) =>
        book.author.toLowerCase().includes(authorLower)
      );
    }

    // Aplica filtro por ano exato
    if (year) {
      const yearNum = Number(year);
      if (Number.isInteger(yearNum)) {
        result = result.filter((book) => book.year === yearNum);
      }
    }

    // Aplica busca textual em título e autor
    if (search) {
      const searchLower = search.toLowerCase();
      result = result.filter(
        (book) =>
          book.title.toLowerCase().includes(searchLower) ||
          book.author.toLowerCase().includes(searchLower)
      );
    }

    // Retorna os livros com metadados de paginação
    res.json({
      success: true,
      count: result.length,                    // Número de resultados retornados
      total: books.length,                     // Total de livros no sistema
      data: result,                            // Array de livros filtrados
      filters: {                               // Filtros aplicados (para debug)
        genre: genre || null,
        author: author || null,
        year: year ? Number(year) : null,
        search: search || null,
      },
    });
  })
);

// ============================================================
// GET /books/:id — Obter único livro por ID
// ============================================================
//
// POR que usar find() e não um loop manual?
// -----------------------------------------
// Array.find() é mais expressivo e idiomático em JavaScript moderno.
// Retorna o PRIMEIRO elemento que satisfaz a condição, ou undefined.
// ============================================================

/**
 * @route   GET /books/:id
 * @desc    Busca um livro específico por ID
 * @access  Public
 *
 * @param {number} id - ID numérico do livro (parâmetro de rota)
 *
 * @example GET /books/1
 * @example GET /books/99  → 404 Not Found
 */
router.get(
  '/books/:id',
  asyncHandler(async (req, res) => {
    // Converte e valida o ID
    const id = validateId(req.params.id);

    // Busca o livro pelo ID — find() retorna undefined se não encontrar
    const book = books.find((b) => b.id === id);

    // Se não encontrado, lança NotFoundError (capturado pelo middleware de erro)
    if (!book) {
      throw new NotFoundError(`Livro com ID ${id} não encontrado`);
    }

    // Retorna o livro encontrado
    res.json({
      success: true,
      data: book,
    });
  })
);

// ============================================================
// POST /books — Criar novo livro
// ============================================================
//
// POR que usar POST e não PUT para criação?
// -----------------------------------------
// REST define claramente:
//   POST = criar um novo recurso (body contém os dados)
//   PUT  = substituir um recurso existente (body contém todos os campos)
//   PATCH= atualizar parcialmente um recurso
// ============================================================

/**
 * @route   POST /books
 * @desc    Cria um novo livro
 * @access  Public
 *
 * Request Body (JSON):
 *   - title: string     (obrigatório) — Título do livro
 *   - author: string    (obrigatório) — Autor do livro
 *   - isbn: string      (opcional)    — ISBN, deve ser único
 *   - genre: string     (opcional)    — Gênero literário
 *   - year: number      (opcional)    — Ano de publicação
 *
 * @example POST /books
 * {
 *   "title": "O Senhor dos Anéis",
 *   "author": "J.R.R. Tolkien",
 *   "isbn": "978-0618640157",
 *   "genre": "Fantasia",
 *   "year": 1954
 * }
 */
router.post(
  '/books',
  asyncHandler(async (req, res) => {
    // Valida os dados de entrada antes de processar
    validateBook(req.body);

    // Verifica duplicidade de ISBN (se fornecido)
    if (req.body.isbn) {
      const existingByIsbn = books.find((b) => b.isbn === req.body.isbn);
      if (existingByIsbn) {
        throw new ConflictError(
          `Já existe um livro com o ISBN "${req.body.isbn}"`
        );
      }
    }

    // Cria o objeto livro com timestamp de criação
    const newBook = {
      id: nextId++,                              // ID auto-incrementado
      title: req.body.title.trim(),              // Trim remove espaços extras
      author: req.body.author.trim(),
      isbn: req.body.isbn ? req.body.isbn.trim() : null,
      genre: req.body.genre ? req.body.genre.trim() : null,
      year: req.body.year || null,
      createdAt: new Date().toISOString(),       // ISO 8601 para consistência
      updatedAt: new Date().toISOString(),
    };

    // Adiciona ao array — push() retorna o novo comprimento do array
    books.push(newBook);

    // Retorna 201 Created com o livro criado no body
    // 201 é o código HTTP padrão para recursos criados com sucesso
    res.status(201).json({
      success: true,
      message: 'Livro criado com sucesso',
      data: newBook,
    });
  })
);

// ============================================================
// PUT /books/:id — Atualizar completamente um livro
// ============================================================
//
// POR que PUT e não PATCH?
// -----------------------
// PUT substitui o recurso INTEIRAMENTE. Todos os campos obrigatórios
// devem ser fornecidos. PATCH atualizaria apenas os campos enviados.
// Para este exemplo educacional, PUT é mais simples de demonstrar.
// ============================================================

/**
 * @route   PUT /books/:id
 * @desc    Atualiza completamente um livro existente
 * @access  Public
 *
 * @param {number} id - ID do livro a ser atualizado
 * @request Body (JSON) — todos os campos obrigatórios:
 *   - title: string     (obrigatório)
 *   - author: string    (obrigatório)
 *   - isbn: string      (opcional)
 *   - genre: string     (opcional)
 *   - year: number      (opcional)
 *
 * @example PUT /books/1
 * {
 *   "title": "O Senhor dos Anéis — Edição Ilustrada",
 *   "author": "J.R.R. Tolkien",
 *   "isbn": "978-0618640157",
 *   "genre": "Fantasia",
 *   "year": 1954
 * }
 */
router.put(
  '/books/:id',
  asyncHandler(async (req, res) => {
    // Converte e valida o ID
    const id = validateId(req.params.id);

    // Encontra o índice do livro no array (indexOf é mais eficiente que find para atualizações)
    const bookIndex = books.findIndex((b) => b.id === id);

    if (bookIndex === -1) {
      throw new NotFoundError(`Livro com ID ${id} não encontrado`);
    }

    // Valida os dados de entrada
    validateBook(req.body);

    // Verifica duplicidade de ISBN (se fornecido e diferente do atual)
    if (req.body.isbn && req.body.isbn !== books[bookIndex].isbn) {
      const existingByIsbn = books.find(
        (b) => b.isbn === req.body.isbn && b.id !== id
      );
      if (existingByIsbn) {
        throw new ConflictError(
          `Já existe um livro com o ISBN "${req.body.isbn}"`
        );
      }
    }

    // Atualiza o livro no array (substituição completa via PUT)
    books[bookIndex] = {
      id: id,
      title: req.body.title.trim(),
      author: req.body.author.trim(),
      isbn: req.body.isbn ? req.body.isbn.trim() : null,
      genre: req.body.genre ? req.body.genre.trim() : null,
      year: req.body.year || null,
      createdAt: books[bookIndex].createdAt,     // Preserva o timestamp de criação
      updatedAt: new Date().toISOString(),       // Atualiza o timestamp de modificação
    };

    res.json({
      success: true,
      message: 'Livro atualizado com sucesso',
      data: books[bookIndex],
    });
  })
);

// ============================================================
// DELETE /books/:id — Excluir um livro
// ============================================================
//
// POR que usar splice() em vez de filter()?
// -----------------------------------------
// splice() modifica o array original in-place, sendo mais eficiente
// para remoções únicas. filter() criaria um novo array, gastando
// memória extra desnecessariamente.
// ============================================================

/**
 * @route   DELETE /books/:id
 * @desc    Exclui um livro pelo ID
 * @access  Public
 *
 * @param {number} id - ID do livro a ser excluído
 *
 * @example DELETE /books/1  → 200 OK com confirmação
 * @example DELETE /books/99 → 404 Not Found
 */
router.delete(
  '/books/:id',
  asyncHandler(async (req, res) => {
    // Converte e valida o ID
    const id = validateId(req.params.id);

    // Encontra o índice do livro a ser removido
    const bookIndex = books.findIndex((b) => b.id === id);

    if (bookIndex === -1) {
      throw new NotFoundError(`Livro com ID ${id} não encontrado`);
    }

    // Remove o livro do array in-place
    const [removedBook] = books.splice(bookIndex, 1);
    // splice(index, 1) remove 1 elemento a partir do índice
    // A desestruturação captura o elemento removido para retorno

    res.json({
      success: true,
      message: 'Livro excluído com sucesso',
      data: removedBook,
    });
  })
);

// ============================================================
// GET /stats — Estatísticas agregadas dos livros
// ============================================================
//
// POR que estatísticas como endpoint separado?
// -------------------------------------------
// Stats não é um recurso CRUD tradicional. É um dado derivado/
// agregado que requer processamento. Colocá-lo em uma rota
// separada (/stats) mantém a semântica REST clara:
//   - /books → recursos individuais/coletivos
//   - /stats → metadados/agregações sobre os recursos
// ============================================================

/**
 * @route   GET /stats
 * @desc    Retorna estatísticas agregadas sobre o acervo de livros
 * @access  Public
 *
 * Resposta inclui:
 *   - totalBooks: número total de livros
 *   - totalByGenre: contagem por gênero
 *   - totalByYear: contagem por ano de publicação
 *   - oldestBook: livro mais antigo (pelo year)
 *   - newestBook: livro mais recente (pelo year)
 *   - avgYear: média dos anos de publicação
 *
 * @example GET /stats
 */
router.get(
  '/stats',
  asyncHandler(async (req, res) => {
    // Se não há livros, retorna estatísticas zeradas
    if (books.length === 0) {
      return res.json({
        success: true,
        data: {
          totalBooks: 0,
          totalByGenre: {},
          totalByYear: {},
          oldestBook: null,
          newestBook: null,
          avgYear: null,
        },
      });
    }

    // Conta livros por gênero usando reduce (padrão funcional)
    const totalByGenre = books.reduce((acc, book) => {
      const genre = book.genre || 'Sem gênero';
      acc[genre] = (acc[genre] || 0) + 1;
      return acc;
    }, {});

    // Conta livros por ano usando reduce
    const totalByYear = books.reduce((acc, book) => {
      if (book.year) {
        const yearKey = String(book.year);
        acc[yearKey] = (acc[yearKey] || 0) + 1;
        return acc;
      }
      return acc;
    }, {});

    // Encontra o livro mais antigo e mais recente
    const sortedByYear = [...books].sort((a, b) => {
      // Livros sem ano vão para o final da ordenação
      if (!a.year && !b.year) return 0;
      if (!a.year) return 1;
      if (!b.year) return -1;
      return a.year - b.year;
    });

    const oldestBook = sortedByYear[0] || null;
    const newestBook = sortedByYear[sortedByYear.length - 1] || null;

    // Calcula a média dos anos de publicação
    const yearsWithData = books.filter((b) => b.year !== null);
    const avgYear =
      yearsWithData.length > 0
        ? yearsWithData.reduce((sum, b) => sum + b.year, 0) / yearsWithData.length
        : null;

    res.json({
      success: true,
      data: {
        totalBooks: books.length,
        totalByGenre,
        totalByYear,
        oldestBook,
        newestBook,
        avgYear: avgYear ? Math.round(avgYear * 100) / 100 : null, // Arredonda para 2 casas decimais
      },
    });
  })
);

// Exporta o roteador para ser usado no app principal
module.exports = router;
```

> **Explicação:** Este é o coração da API. Cada rota segue convenções REST rigorosas: métodos HTTP corretos, códigos de status apropriados e URLs semânticas. A validação centralizada em `validateBook()` evita repetição de lógica entre POST e PUT. O uso de `asyncHandler` garante que erros lançados dentro das funções async sejam capturados pelo middleware de erro. As estatísticas usam `reduce()`, um padrão funcional que transforma arrays de forma declarativa — mais legível que loops imperativos para agregações.

