## Arquivo 5: `src/app.js`

```javascript
/**
 * ============================================================
 * Configuração da Aplicação Express
 * ============================================================
 *
 * POR que separar app.js do server.js?
 * ------------------------------------
 * app.js configura a aplicação (middlewares, rotas).
 * server.js inicia o servidor (ouvindo na porta).
 * Esta separação permite:
 *   - Testar a aplicação sem precisar iniciar o servidor
 *   - Reutilizar a configuração em diferentes ambientes
 *   - Manter cada arquivo com responsabilidade única
 *
 * Middlewares configurados:
 *   1. express.json()     — Parseia bodies JSON automaticamente
 *   2. express.urlencoded — Parseia formulários (para compatibilidade)
 *   3. error handler      — Tratamento centralizado de erros
 * ============================================================
 */

const express = require('express');

// Importa as rotas de livros
const bookRoutes = require('./routes/books');

// Importa o middleware de tratamento de erros
const { errorHandler } = require('./middleware/errorMiddleware');

// Cria a instância da aplicação Express
const app = express();

// ============================================================
// MIDDLEWARES GLOBAIS
// ============================================================

/**
 * Middleware para parsear bodies JSON.
 * Sem este middleware, req.body seria undefined.
 * limit: '10kb' previne requisições excessivamente grandes.
 */
app.use(express.json({ limit: '10kb' }));

/**
 * Middleware para parsear formulários URL-encoded.
 * Utile para compatibilidade com requests de formulários HTML.
 */
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// ============================================================
// ROTAS
// ============================================================

/**
 * Rota raiz — health check da API.
 * Retorna 200 OK para indicar que o servidor está funcionando.
 * Útil para monitoramento e load balancers.
 */
app.get('/', (req, res) => {
  res.json({
    success: true,
    message: 'API de Livros — Servidor rodando com sucesso!',
    endpoints: {
      // Documentação inline dos endpoints disponíveis
      books: {
        list: 'GET /books',
        getById: 'GET /books/:id',
        create: 'POST /books',
        update: 'PUT /books/:id',
        delete: 'DELETE /books/:id',
      },
      stats: 'GET /stats',
    },
  });
});

/**
 * Rota para health check explícito.
 * Retorna informações detalhadas do servidor.
 */
app.get('/health', (req, res) => {
  res.json({
    success: true,
    status: 'healthy',
    timestamp: new Date().toISOString(),
    uptime: process.uptime(),           // Tempo de atividade do processo em segundos
    nodeVersion: process.version,       // Versão do Node.js
    environment: process.env.NODE_ENV || 'development',
  });
});

/**
 * Registra as rotas de livros sob o prefixo /api/v1.
 * O versionamento (v1) é uma convenção REST importante que permite
 * evoluir a API sem quebrar clientes existentes.
 */
app.use('/api/v1', bookRoutes);

// ============================================================
// TRATAMENTO DE ERROS
// ============================================================

/**
 * Middleware de tratamento de erros — deve ser o ÚLTIMO middleware registrado.
 * Express identifica middlewares de erro pela assinatura com 4 parâmetros.
 *
 * IMPORTANTE: A ordem importa! Middlewares de erro devem vir APÓS todas as rotas,
 * caso contrário eles capturariam requisições normais como erros.
 */
app.use(errorHandler);

// ============================================================
// MANIPULADOR PARA ROTAS NÃO ENCONTRADAS (404)
// ============================================================

/**
 * Middleware para rotas inexistentes.
 * Se nenhuma rota anterior corresponder, retorna 404.
 * Este middleware deve vir APÓS todas as rotas definidas.
 */
app.use((req, res, next) => {
  // Cria um NotFoundError customizado para rotas não mapeadas
  const error = new (require('./utils/errors').NotFoundError)(
    `Rota não encontrada: ${req.method} ${req.originalUrl}`
  );
  next(error); // Encaminha o erro para o middleware de tratamento de erros
});

module.exports = app;
```

> **Explicação:** O `app.js` configura a aplicação Express com middlewares globais e rotas. A separação entre configuração (app.js) e inicialização do servidor (server.js) segue o padrão de injeção de dependência: a aplicação pode ser testada isoladamente sem precisar iniciar um servidor HTTP. O versionamento `/api/v1` é uma convenção essencial em APIs REST — permite breaking changes futuros ao criar `/api/v2` sem afetar clientes existentes.

