```javascript
/**
 * ============================================================
 * Ponto de Entrada da Aplicação
 * ============================================================
 *
 * Este arquivo é responsável apenas por:
 *   1. Importar a configuração da aplicação
 *   2. Determinar a porta de escuta
 *   3. Iniciar o servidor HTTP
 *   4. Logar informações de inicialização
 *
 * POR que não colocar toda a lógica aqui?
 * ---------------------------------------
 * Manter este arquivo minimalista segue o princípio KISS (Keep It Simple, Stupid).
 * A lógica de negócio está em app.js e nas rotas; este arquivo é apenas o "plug"
 * que conecta tudo ao sistema operacional via servidor HTTP.
 * ============================================================
 */

const app = require('./app');

// Determina a porta: usa variável de ambiente PORT ou padrão 3000
// Em produção, serviços como Heroku/Render definem PORT automaticamente
const PORT = process.env.PORT || 3000;

// Determina o ambiente (padrão: development)
const NODE_ENV = process.env.NODE_ENV || 'development';

/**
 * Inicia o servidor e faz log de inicialização.
 * .listen() cria o servidor HTTP e começa a ouvir na porta especificada.
 * O callback é executado apenas após o servidor estar pronto para receber conexões.
 */
const server = app.listen(PORT, () => {
  console.log('╔══════════════════════════════════════════════════════╗');
  console.log('║         API de Livros — Servidor Iniciado           ║');
  console.log('╠══════════════════════════════════════════════════════╣');
  console.log(`║  Ambiente:    ${NODE_ENV.padEnd(38)}║`);
  console.log(`║  Porta:       ${PORT.toString().padEnd(38)}║`);
  console.log(`║  Base URL:    http://localhost:${PORT}/api/v1        ║`);
  console.log('╠══════════════════════════════════════════════════════╣');
  console.log('║  Endpoints Disponíveis:                             ║');
  console.log('║    GET    /api/v1/books          — Listar livros    ║');
  console.log('║    GET    /api/v1/books/:id      — Buscar livro     ║');
  console.log('║    POST   /api/v1/books          — Criar livro      ║');
  console.log('║    PUT    /api/v1/books/:id      — Atualizar livro  ║');
  console.log('║    DELETE /api/v1/books/:id      — Excluir livro    ║');
  console.log('║    GET    /api/v1/stats          — Estatísticas     ║');
  console.log('╚══════════════════════════════════════════════════════╝');
});

// ============================================================
// TRATAMENTO DE ERROS DO SERVIDOR
// ============================================================

/**
 * Evento 'error' do servidor HTTP.
 * Captura erros de nível de servidor (porta já em uso, permissões, etc.)
 */
server.on('error', (err) => {
  if (err.code === 'EADDRINUSE') {
    // Porta já está sendo usada — erro comum durante desenvolvimento
    console.error(`❌ ERRO: A porta ${PORT} já está em uso!`);
    console.error('   Dica: use "lsof -i :3000" (Linux/Mac) ou "netstat -ano | findstr :3000" (Windows)');
    console.error('   Ou mude a porta: PORT=3001 npm run dev');
  } else {
    console.error('❌ ERRO no servidor:', err.message);
  }
  process.exit(1); // Sai do processo com código de erro
});

/**
 * Evento 'SIGINT' — captura Ctrl+C para shutdown graceful.
 * Permite finalizar conexões ativas antes de encerrar o processo.
 */
process.on('SIGINT', () => {
  console.log('\n🛑 Encerrando servidor...');
  server.close(() => {
    console.log('✅ Servidor encerrado com sucesso.');
    process.exit(0);
  });
});

module.exports = server;
```

> **Explicação:** O `server.js` é o ponto de entrada mínimo e responsável. Ele usa `process.env.PORT` para compatibilidade com plataformas de cloud (Heroku, Railway, etc.) que definem a porta automaticamente. Os listeners de eventos `'error'` e `'SIGINT'` demonstram boas práticas de produção: tratamento de erros de rede e shutdown graceful respectivamente.

